window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["34430936"]={"book":{"id":34430936,"title":"教练型管理者","author":"俞清、金慧英","translator":"","publisher":"中信出版集团","pubdate":"2019-06-01","isbn":"9787521704174","tags":["管理"],"memCount":null},"np":1,"pb":[23],"idx":[{"i":19465,"t":"教练型管理者","l":"TF1-1","c":"姜超","g":1,"p":1},{"i":19387,"t":"积极性反馈AAA技术","l":"TF1-1","c":"吾心光明","g":1,"p":1},{"i":19296,"t":"积极的反馈技术","l":"TF1-1","c":"迎春","g":1,"p":1},{"i":14172,"t":"晋级","l":"TF1-1","c":"冬日阳光","g":1,"p":1},{"i":14165,"t":"教练型管理","l":"TF1-2","c":"无问西东","g":1,"p":1},{"i":13995,"t":"如何使用积极性反馈与建设性反馈，提升管理能力。","l":"TF2-4","c":"韩军华","g":1,"p":1},{"i":13900,"t":"如何使用积极性反馈与建设性反馈，提升管理能力。","l":"TF2-4","c":"韩军华","g":1,"p":1},{"i":13652,"t":"这样倾听，让人觉得你好懂","l":"TF3-1","c":"Frank Hung","g":1,"p":1},{"i":13474,"t":"赞美时说出具体的行为和事实（既对人也对事），批评时做到对事不对人","l":"TF3-3","c":"驰驰","g":1,"p":1},{"i":13447,"t":"TF2-4","l":"TF2-4","c":"Amber Shen","g":1,"p":1},{"i":13205,"t":"积极反馈正向激励之“3A积极反馈法”","l":"TF1-1","c":"西边懂佛","g":0,"p":1},{"i":12957,"t":"让你的批评有效果 — AID建设性反馈法","l":"TF2-1","c":"waynezhang","g":1,"p":1},{"i":12870,"t":"使用積極性反饋強化他人持續作出正向行為， 使用建設性反饋讓他人行為改善能符合自己的預期，期待學會的你能夠，表揚他人，讓人","l":"TF2-4","c":"Frank Hung","g":1,"p":1},{"i":12569,"t":"有效的积极性反馈 — AAA反馈法","l":"TF1-2","c":"waynezhang","g":1,"p":1},{"i":12105,"t":"教练型管理者的积极反馈技术  ","l":"TF1-1","c":"邹治","g":1,"p":1},{"i":11803,"t":"赞美力-积极性反馈技术","l":"TF1-1","c":"星辰陈","g":1,"p":1},{"i":11777,"t":"如何进行积极性反馈？","l":"TF2-1","c":"润芽心理","g":1,"p":1},{"i":11014,"t":"【郑州轩辕NO.226期】周日主题：“积极性反馈技巧”+“游戏：猜猜你是谁？”","l":"TF3-2","c":"肖利","g":1,"p":1},{"i":10629,"t":"未来导向型提问五步法","l":"TF1-2","c":"忆C","g":1,"p":1},{"i":10561,"t":"积极的反馈技术","l":"TF1-1","c":"张锡梅","g":1,"p":1},{"i":10474,"t":"积极反馈的技术 ","l":"TF1-1","c":"邹治","g":1,"p":1},{"i":10187,"t":"积极性反馈-AAA","l":"TF1-1","c":"韩璐","g":1,"p":1},{"i":10171,"t":"建设性反馈技术-AID","l":"TF2-3","c":"肖利","g":1,"p":1}],"ms":[{"id":19465,"topic":"教练型管理者","learn_goal":"","remark":"教练型管理者","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"姜超","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp> 各位小伙伴，大家好，很高兴能与各位相聚拆书帮，我是姜超，接下来我用三个标签做个自我介绍：\u003c/p>\u003cp>1、企业管理培训与咨询工作\u003c/p>\u003cp>2、运动爱好者，一天不运动浑身难受那种\u003c/p>\u003cp>3、阅读爱好者\u003c/p>\u003cp>拆书是将知识拆解为己用的一种学习方法，以提升能力，解决问题为目标，强调以学习者为中心，要把知识关联学习者的经验并规划具体的运用。不仅适用于个人，也适用于组织学习。个人学习的应用是便签法，读一本书就能达到参加同主题培训的效果，而组织学习的应用是一位拆书家那一本书加工成一场现场学习，引导一群人把书中的知识拆为己用。从学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师，所以更注重的是落地。\u003c/p>\u003cp>“拆书帮”是基于折书法的学习爱好者社群，在全国各地都有拆书帮分舵，使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":23840,"quote":"\u003ch3>\u003cstrong>【R：原文片段】积极的反馈技术 《教练型管理者》\u003c/strong>\u003c/h3>\u003cp>教练型管理的积极性反馈技术——AAA\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。\u003c/p>\u003cp>这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。\u003c/p>\u003cp>积极性反馈的注意要点如下：\u003c/p>\u003cp>\u003cstrong>首先，一定要聚焦行为和事实\u003c/strong>，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地评判。\u003c/p>\u003cp>\u003cstrong>其次，阐述这些行为和事实会带来什么样的影响\u003c/strong>，也可以针对相应影响给与评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>\u003cstrong>最后，表示由衷的欣赏和感谢。\u003c/strong>\u003c/p>","explains":"\u003cp>I：在日常团队管理中，“过程不重要，我只看结果” 是普遍存在的观念，而管理者的核心需求是通过有效引导，让团队既能在成功案例中提炼可复制的经验，也能在失败案例中找到可借鉴的价值，最终激发成员潜能、推动团队整体进步。\u003c/p>\u003cp>那么，管理者该如何跳出 “重结果轻过程” 的思维定式，通过科学的反馈方式，既能精准肯定成员的积极行为、激发其成就感，又能让团队从不同案例中明确学习方向，实现个人与团队的双向成长呢？\u003c/p>\u003cp>解决这一问题的关键，在于掌握教练型管理中的 “AAA 积极反馈技术”—— 这是一门兼具方法性与艺术性的反馈能力，既能针对性回应管理痛点，又能为团队成长提供清晰路径，具体实践可从以下维度展开：\u003c/p>\u003cp>1、Act（描述行为与事实）：管理者需跳出主观评判，聚焦事件的完整脉络，客观、具体地描述成员的行为细节。例如面对项目推进，不说 “你做得很好”，而说 “你在项目卡顿时主动梳理 3 个解决方案，并同步给团队投票选择”，用事实支撑反馈，让成员清晰感知 “自己哪件事被认可”。\u003c/p>\u003cp>2、Actor（阐述影响与评价）：不仅要分析行为对成员个人能力的提升，更要将影响扩大到团队层面，比如 “这个过程让团队养成了‘遇到问题先找方案’的习惯，后续类似项目的推进效率预计能提升 15%”。这种 “以点带面” 的阐述，既能让成员获得成就感，也能让团队明确 “标杆行为的价值”，形成集体学习的氛围。\u003c/p>\u003cp>3、Appreciation（传递欣赏与感谢）：对成员的积极行为及时表达认可，除了口头感谢，若条件允许可搭配小额正向激励，让所有人清晰知道 “什么样的行为是团队鼓励的”。 真正做到 “善于观察、以反馈促成长”。\u003c/p>","interaction":"\u003cp>A1：我曾经对过程的关注很少，只关注过程带来的结果。记得有一次我们团队的小林，在运作一个项目，这也是他来公司第一个项目，这个项目花了近6个月的时间，最终尘埃落定，大家都在夸他厉害，这也给大家留下了一个比较好的印象。喝酒庆祝的时候，我只和小林讲了“做的不错，继续努力”。不过在后面的工作中，我发现小林的一个问题，就是每一个的项目运作，他都像一个新人一样，无序的推进节奏，给大家造成了一些困扰。我当时对此很不理解，前面已经有过一次成功经验了，为什么还是出现这样的问题呢？我就找小林一起对当前项目进行了复盘，聊完之后，我当时的定论是：问题出现在前面每一次成功的经验都缺少了总结复制。不过后续的效果好像并不明显。\u003c/p>\u003cp>看到这个AAA反馈技术，我发现问题不仅仅在于小林，我本身也缺少了对他在成功项目中做得好的环节的反馈。比如第一个项目中，小林了解到客户当中有人反对我们的核心问题，对后面的解决方案方向提供了很好的输入，我应该对此行为给予更多的反馈：这是一个客户关系管理的好案例，原来那个反对的人，你先是了解到这个人性格的刚正不阿，并不是针对我们，只是他对这个项目到底产生什么价值不清楚，你后面识别到了他的痛点，再通过方案的价值呈现缓和了他的反对情绪，进一步把和他的关系拉进了，虽然没有成为极力支持者，但不反对我们就已经很完美了。很多人在遇见这种情况的时候，总是想着靠一些低劣的手段拉进关系，但往往适得其反，没有敏锐的发现现状背后的问题。而你的这种客户关系管理是非常舒适的，很值得借鉴。\u003c/p>\u003cp>A2：目标：找小林一起端到端复盘一个项目，通过AAA反馈技术给出积极反馈。3个月内在团队里找到3个可以积极反馈的案例。\u003c/p>\u003cp>行动与计划：寻找的案例不限于项目中，也可以在日常工作里，重点是多观察大家正在做的事情。\u003c/p>\u003cp>1、找到可圈可点的事情时，首先要从这件事情中看到这个人是怎么做的？比如：在去见客户之前要准备3份材料，要想他为什么要带这三份材料，好处是什么？这个行为是否值得团队学习？如果有思考不清楚的行为，必要的时候可以和他交流下，听听他的想法。\u003c/p>\u003cp>2、基于亮点从行为上以及思路上给予反馈，如果这个行为对团队还有影响，要及时表达出来，鼓励这种行为，还要邀请他给大家做分享，让大家学习借鉴。\u003c/p>\u003cp>3、赞赏与感谢一定要在公共场合进行，最好让团队里的其他人，在听完分享后，对其学习到的行为进行总结与赞美，牵引大家多发言。比如当小林分享过后，可以询问小王：你觉得小林在这个过程中做对了哪些？有什么特别之处？等等\u003c/p>\u003cp>更值得注意的是，教练型管理者不仅在与我对他人积极的反馈，而在于牵引大家互相之间都能有积极的反馈，团队才能一起发展。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1763978913000,"updated_at":1764123223000,"ria":true},{"id":19387,"topic":"积极性反馈AAA技术","learn_goal":"","remark":"《教练型管理者》是落地教练技术的实用指南！书中核心的“积极性反馈技术（AAA法则）”——恰当及时、真诚一致、具体准确，直击传统管理“鼓励空洞、激励无效”的痛点。","level":"TF1-1","duration":13,"status":30,"type":0,"chaishujia":{"username":"吾心光明","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>开场：\u003c/p>\u003cp> 【发拆页】\u003c/p>\u003cp> 【自我介绍】大家好、我是李延进，坐标长沙，我曾是一位有过20年的创业者，企业高管，也是一名终身学习者。\u003c/p>\u003cp> 【拆书帮介绍】\u003c/p>\u003cp> 我在朋友圈发我参加训练营的毕业证书的时候，就有朋友问我，拆书帮是干啥的？现在我来给大家介绍一下：\u003c/p>\u003cp>我与拆书帮结缘，今年3月份，源于一本拆书帮创始人赵周老师的书《这样读书就够了》，拆书帮是一群爱阅读、爱学习、爱成长的成人社群组织，也是一家非营利性自组织，其使命就是帮助更多的学习爱好者成为学习促进者、拆书家。\u003c/p>\u003cp> 那么拆书法是什么呢？\u003c/p>\u003cp>拆书法是一种适合成年人的学习方法，拆书法主要分为以个人学习的三张便签拆书法和组织学习的RIA学习法。\u003c/p>\u003cp>拆书法强调以自己为中心，以提升能力，解决问题为目标的成人学习法，而不是以知识为中心的学习，要把知识学习关联自己的经验以及具体应用到工作生活中去，所以做为一个成年人，如果想通过读书成长自己，改变自己，那就从拆书这种方法学习。\u003c/p>","ratings_count":1,"texts":[{"id":23754,"quote":"\u003cp> R 原文片段：\u003c/p>\u003cp> 那现在就由我来带领大家拆解一下今天的片段。《积极性反馈技术-AAA》， 片断来源是《教练型管理者》这一书，该书有绩能教练创始人金慧英和资深教练俞清所著。\u003c/p>\u003cp>下面我们花2分钟时间看一下原文片段，看完后抬头示意我一下。\u003c/p>\u003cp> 《积极性反馈技术-AAA》P096-097\u003c/p>\u003cp> 那么，我们究竟该如何进行有效的积极性反馈呢？如果此刻让你回想一下你最有印象的一位老师并表扬他，那么你会如何表扬呢？很多人是如此表扬的：\u003c/p>\u003cp> ■老师，您的课讲得特别棒！\u003c/p>\u003cp> ■老师，您特别专业！\u003c/p>\u003cp> ■老师，您的课逻辑性特强！\u003c/p>\u003cp> ■老师，您的课幽默、风趣，全程没有尿点！\u003c/p>\u003cp> ■您是我见过的最优秀的老师，没有之一，下次我还要上您的课！\u003c/p>\u003cp> 如果你是这位老师，在听到这样的反馈后会有什么样的感受？第一感觉肯定很开心，还挺兴奋的。因为这些话用的都是溢美之词，你听到后当然开心。但是，冷静下来，你不知道他说你“讲得特别棒”，到底棒在哪里。你也不知道他说你“专业”，到底专业在哪里。你甚至慢慢会感觉到“幽默、风趣”应该是每位讲师的基本素质，感觉“全程没有尿点”有点儿夸张，感觉“下次我还要上您的课”好像是应付。想到这里，你的开心、兴奋会瞬间消失，感觉大家只是在恭维你，给你面子而已。\u003c/p>\u003cp> 假设有一位学员给了你这样的一段表扬信：\u003c/p>\u003cp>亲爱的老师，您提前40分钟来到我们的培训室。在课程中，为了照顾到我们全场80位学员，您不停地走到每个小组前。从您生动的肢体语言和神态上，我就能够感受到您对教学的投入程度。课间休息时，您却没有休息，还将每组问题逐一归类和分析；课间练习时，您既能引导大家活跃思考，又能及时把握方向防止大家跑偏，还能在交流问题的过程中快速发现问题并给出专业的指导。只有对自己的课程有绝对的信心且对学员抱有很高的期望才能如此专注。您的勤勉和敬业令我由衷感叹！正因为您忘我的付出，我们的课堂氛围才能如此活跃，80位学员才能收获满满的落地的管理实操工具。今日，您的言传身教令我获益良多，不光是知识上的收益，也包括专业度、勤勉和应变的启迪，再次感谢您的付出。\u003c/p>\u003cp> 看完这段表扬信后，你的内心应该是满满的感动。我相信这份感动并不只是因为这封表扬信的字数多，更是因为学员对老师细节的关注、认可和感激。你的内心肯定油然升起一股使命感：为了不辜负这样的反馈，我要用尽全力更加服务好这批学员。这就是积极性反馈的价值，不仅可以激发对方的内在动力和意愿度，还可以强化该行为的持续性。\u003c/p>\u003cp>\u003cstrong> 总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。不难看出，上述学员的反馈完全符合这3个要素。\u003c/strong>\u003c/p>","explains":"\u003cp>I拆书家讲解引导：\u003c/p>\u003cp> 好了，大家都看完拆页了。\u003c/p>\u003cp> 【WHAT】\u003c/p>\u003cp> 你在日常工作生活中，是不是有遇到以下场景：\u003c/p>\u003cp> “朋友帮了我一个大忙，我如何表达感谢呢？并让他能感受到我的真诚”。\u003c/p>\u003cp> “委派下属的任务完成得非常好”我该如何表达我的欣赏呢？并让他能够持续保持呢？”\u003c/p>\u003cp> .................\u003c/p>\u003cp> 答案：运用积极性反馈AAA技术： 第一个A（Act）:描述行为和事实；第二个A（Actor）:是阐述影响及评价；第三个A(Appreciation):是表示欣赏和感谢\u003c/p>\u003cp> 【WHY】\u003c/p>\u003cp> 1、学习者平时习惯怎么做？\u003c/p>\u003cp>学习者在给予积极反馈时,常常会笼统概括,关注结果,忽视过程,例如:你真棒!,干的不错!等.\u003c/p>\u003cp> 2、习惯做法的坏处？\u003c/p>\u003cp> 激励效果差，对方不知道好在哪里,无法重复该优秀行为,感觉表扬只是客套和敷衍.\u003c/p>\u003cp> 3、书中做法的好处？\u003c/p>\u003cp> 通过明确指出具体有效行为,并针对有效行为予以肯定和赞赏,能够激发其有效行为重复发生.\u003c/p>\u003cp> 【HOW】\u003c/p>\u003cp> 有效的积极性反馈AAA技术包含三个要素：\u003c/p>\u003cp> 1、描述行为和事实（Act），句式为：“我看到你在______（具体场景）中（具体动作 1。。。。”）；\u003c/p>\u003cp> 我看到你“主动记录客户提的 3 个核心需求”“每天提前半小时梳理工作进度”\u003c/p>\u003cp> 2、阐述影响及评价（Actor），句式为：______（相关人 / 事，如客户/同事/家人）______（具体结果 ），\u003c/p>\u003cp> 如 “客户后续没再反复确认时间，沟通效率高了很多”“团队成员每天都能明确自己的任务优先级”；\u003c/p>\u003cp> 3、表示欣赏和感谢（Appreciation）。\u003c/p>\u003cp> 你这份______（行为背后的特质）真的很打动人，不仅______（呼应 Actor 中的影响 ），也让我觉得______（自身感受），太感谢啦！\u003c/p>\u003cp> 您“对细节的关注”，不仅“帮我们减少了沟通内耗”，也让我觉得“和你合作特别安心”，太感谢啦！\u003c/p>\u003cp> 您“为团队着想的主动”，不仅“让项目推进更顺畅”，也让我觉得“从你身上学到了做事的严谨”，太感谢啦！\u003c/p>\u003cp> 【WHERE】\u003c/p>\u003cp>\u003cstrong> 什么场景适用？适合用来\u003c/strong> \u003cstrong>“放大好行为、传递真认可”，比如\u003c/strong>\u003c/p>\u003cp> 1、下属完成项目、同事协助工作、跨部门配合顺利等，需要肯定对方付出时；\u003c/p>\u003cp> 2、朋友帮你解决困难、伴侣主动分担家务、家人记得你的小喜好等；\u003c/p>\u003cp> 3、收到优质服务（如设计师改稿、销售耐心解答）、合作伙伴高效配合等\u003c/p>\u003cp>\u003cstrong> 什么场景不适用？\u003c/strong>遇到 “紧急、严肃” 的场景，直接聚焦的反馈就好，比如：\u003c/p>\u003cp> 1、项目马上要截止，下属却犯了低级错误；会议中出现数据错误，需要立刻修正；\u003c/p>\u003cp> 2、员工多次迟到且态度敷衍；合作方反复违约，需要严肃沟通。\u003c/p>","interaction":"\u003cp>A学习者拆为己用：\u003c/p>\u003cp> \u003cstrong>【A1联系具体经验】\u003c/strong>\u003c/p>\u003cp> 故事：\u003c/p>\u003cp> 做为一名主管，经常性对下属工作进行反馈，做的好的要表扬，做的不好的要指正，就在2025年9月1日上午一位下属小A一进入我办公室就说：领导，我8月份做的还不错吧，我的绩效是不是可以得满分呀，我说：小A你上个月确实做的很好，业绩很高，一定为你嘉奖，等着我的好消息，就这样对话就结束了。\u003c/p>\u003cp>反思：\u003c/p>\u003cp> 接下来在遇到表扬下属时，我不再只对结果做了反馈，也没有反馈具体哪里做的好，实际上对下属没有什么激励促进作用，看完这个片段后，下次再表扬员工的时候，我可以这么做：首先重点去聚焦过程及具体行为，然后针对有效行为来进行积极肯定和表扬，让下属真正了解自己被领导肯定的地方，并激励其继续重复有效行为。\u003c/p>\u003cp> \u003cstrong>【A2具体应用】\u003c/strong>\u003c/p>\u003cp> 1、场景：邀请小A来办公室，运用积极性反馈AAA技术来进行表扬及邀请其做为本月分享之星在台上分享。\u003c/p>\u003cp> 2、时间：2025年9月12日\u003c/p>\u003cp> 3、目标：我计划在2015年9月12日与小A的约谈中，完整运用积极性反馈AAA技术，以表扬其上月业绩并成功获得其接受“本月分享之星”邀请的明确承 诺\u003c/p>\u003cp>4、行动计划：\u003c/p>\u003cp> 9月15日是公司每月例行月度复盘及表彰会，决定给小A颁发月度业绩冠军荣誉证书及奖金并计划安排台上进行分享，我计划在12日约谈小A，用积极性AAA反馈技术来反馈，具体如下：\u003c/p>\u003cp>小A，你上个月业绩确实做的很好，上个月我看到你每天不是在埋头电话邀约客户，就是在接待咨询客户，另外我也看到了你还建立了“客户银行本”，每天客户跟进记录都有更新，能够感受到你的用心，业绩高是你努力付出的结果，最重要的你不仅为公司达成月度目标做了很大贡献，而且还带动了整个团队的你追我赶的士气，公司计划推荐你做本月分享之星在9月15日复盘会上进行分享，把你的有效的工作经验和方法分享给大家，帮助更多的小伙伴成长，小A我很欣赏你，继续加油！\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp> 最后总结一下今天的拆书，今天我们共同学习了《积极性反馈技术-AAA）这一片段，AAA反馈技术具体结构是\u003cstrong>：一是\u003c/strong>描述行为和事实；二是阐述影响及评价；三是表示欣赏和感谢。\u003c/p>\u003cp> 所以，积极性反馈一定要聚焦具体的行为和事实，通过准确的行为和事实描述表示认可。\u003c/p>\u003cp> 我今天的分享就到此结束了，希望这个片段会对各位小伙伴有帮助，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1761382832000,"updated_at":1761577261000,"ria":true},{"id":19296,"topic":"积极的反馈技术","learn_goal":"","remark":"积极的反馈术是一种通过描述具体行为、阐述积极影响，并真诚表达欣赏来强化正确行为的方法。它能激发人的潜能，提高他人做事的及积极性，促进良好的人际关系的发展。\n","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"迎春","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【开场】0.5分钟\u003c/strong>\u003c/p>\u003cp>拆书帮的各位伙伴，大家好！\u003c/p>\u003cp>今天我要进行TF1-1的过级，感谢各位伙伴到场支持。\u003c/p>\u003cp>\u003cstrong>【自我介绍及拆书主题】1分钟\u003c/strong>\u003c/p>\u003cp>本次拆书的主题是积极的反馈技术，时间13分钟。\u003c/p>\u003cp>首先做下自我介绍。我叫禚迎春。禚是一个特殊的姓氏，据考证我们是姜子牙的后代，迎春寓意拥抱春天，永远充满生机与希望，特别契合我的性格。\u003c/p>\u003cp>我的3个标签是：\u003c/p>\u003cp>1.一名小学语文老师和班主任，致力于点燃孩子对母语的热爱，成为他们成长路上的引路人。\u003c/p>\u003cp>2.一位两个男孩的妈妈，通过持续学习，以身作则，成为孩子们终身学习的榜样。\u003c/p>\u003cp>3.一位书法爱好者，我是青岛市书法协会会员，通过研习书法，体悟汉字之美，并将这份感悟融入教学与生活。\u003c/p>\u003cp>\u003cstrong>【介绍拆书法和拆书帮】2分钟\u003c/strong>\u003c/p>\u003cp>在开始今天的拆书之前，我先介绍一下拆书法和拆书帮。\u003c/p>\u003cp>拆书，不同于学院式的知识性学习，而是以学习者为中心，以提升个人能力和解决问题为目标。通过拆书，把知识运用到生活和工作中，用所学解决问题，改变行为，真正做到让知识为我所用。拆书分为个人学习的拆书和组织学习的拆书；个人学习是便签法，让人读一本书就能达到参加同主题培训的效果；组织学习是一位拆书家拿一本书加工厂一场现场学习，引导组织一群人把知识拆为己用。所以，这种方法，对个人和组织，都是非常高效的。\u003c/p>\u003cp>拆书帮是基于“拆书法”的学习者社群，由全国各地非盈利性的分舵组成。拆书帮的核心使命是帮助更多的学习爱好者掌握并实践拆书法，最终成长为能引导他人学习的拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":23650,"quote":"\u003cp>\u003cstrong>【图书介绍】0.5分钟\u003c/strong>\u003c/p>\u003cp>积极的反馈技术，片段来自《教练型管理者》一书，这本书的核心是指导管理者从传统的命令式控制模式，转变为通过培养和激发下属来提升团队绩效的教练角色。\u003c/p>\u003cp>\u003cstrong>【R阅读拆页】2分钟\u003c/strong>\u003c/p>\u003cp>下面请大家用2分钟阅读原文片段，读完的伙伴请举手示意我。教练型管理的积极性反馈技术——AAA\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。\u003c/p>\u003cp>积极性反馈的注意要点如下：\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地评判。\u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给与评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。\u003c/p>","explains":"\u003cp>\u003cstrong> 【I拆书家讲解引导】1分钟（诠释、清晰、准确、致用）\u003c/strong>\u003c/p>\u003cp> 大多数小伙伴都已经完成阅读了，下面我来简单介绍一下我对拆页的理解。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>积极的反馈术是一种通过描述具体行为、阐述积极影响，并真诚表达欣赏来强化正确行为的方法。描述行为和事实、阐述影响及评价、表示欣赏和感谢这3个要素，缺一不可。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>积极反馈术能激发对方的成就感，赋能对方，激发人的潜能，促进良好的人际关系，提高对方做事的积极性和热情。 对我们的生活和工作对有极大的助力。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>积极反馈可以这样做：\u003c/p>\u003cp> 1. 仔细观察，具体客观地描述对方的行为和事实。\u003c/p>\u003cp> 2. 点明行为和事实对个人，团队等带来的影响，也可给出评价。\u003c/p>\u003cp> 3. 真诚地向对方表达欣赏和感谢之情。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>积极反馈技术适用于对员工工作成果的肯定、家庭中/学校中对孩子良好行为的鼓励、朋友之间互相支持鼓励等。\u003c/p>\u003cp>它也有不适应的场景，比如说对方犯严重错误需要批评纠正时，不适合用积极反馈术，而应采取恰当的批评方式指出问题。 \u003c/p>","interaction":"\u003cp>\u003cstrong>【A学习者拆为己用】3分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1便签】1分钟（鲜活、故事、对应、反思）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>经验：\u003c/strong>上周末，我家老大主动制定了一份学习和玩耍的时间表。当我检查他执行情况时，只是简单说了句“还不错，时间规划很清晰”。孩子做了这么多，我的反馈却如此简单，他没有得到想要的积极反馈。\u003c/p>\u003cp>\u003cstrong>反思：\u003c/strong>与积极的反馈技术相比，我只是简单评判，没有描述孩子具体做了什么行为，比如他每天按时完成作业、主动减少了玩游戏的时间这些事实，也没有说明这样做对他自身学习进步、养成自律习惯的影响，更没有表达我对他主动进行时间管理这件事的欣赏和感谢。 \u003c/p>\u003cp>\u003cstrong>【A2便签】2分钟（目标、行动、关联、可控）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>未来一周，当孩子在时间管理上出现按计划执行等良好行为时，运用积极反馈技术完成至少3次具体反馈。每次反馈要包含行为事实描述、影响评价、欣赏感谢三个要素，此时也注意这些积极反馈要在孩子出现行为后的24小时内完成。 \u003c/p>\u003cp>\u003cstrong>行动：\u003c/strong>具体做法：\u003c/p>\u003cp> 1. 描述行为和事实。观察记录，每日留意孩子在时间管理上的行为，如按时或提前完成任务等，用手机备忘录简单记录具体行为。在发现孩子良好行为后的24小时内，清晰地向孩子说出记录的具体行为事实。\u003c/p>\u003cp> 2. 阐述影响和评价。结合行为说明对孩子的影响，如“这样不仅让你的作业完成得又快又好，学习效率提高了，还养成了自律的好习惯，以后不管是学习还是做其他事情，这个习惯都会让你更出色”。\u003c/p>\u003cp> 3. 表达感谢欣赏：明确说出“妈妈很欣赏你主动管理时间的样子，谢谢你愿意努力养成让自己终身受益的好习惯”。\u003c/p>\u003cp> 完成以上三个步骤后，建议再进行复盘确认：每天睡前简单回顾是否完成反馈，一周结束后统计反馈次数是否达标。\u003c/p>\u003cp>\u003cstrong>【结束语】0.5分钟\u003c/strong>\u003c/p>\u003cp>各位伙伴，今天我们一起共同学习了“积极的反馈技术·”我们可以通过描述行为和事实、阐述影响及评价、表示欣赏和感谢这三个步骤赋能他人，提高对方做事的积极性和热情。今天的分享到此结束，希望大家有所收获，也非常感谢大家的陪伴，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1757132222000,"updated_at":1757573402000,"ria":true},{"id":14172,"topic":"晋级","learn_goal":"","remark":"拆书晋级","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"冬日阳光","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>开场：\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>请问观察家老师拿到记录表、准备表和拆页了么？\u003c/p>\u003cp>请问各位小伙伴都拿到我的拆页了么？好，现在正式开始今天的晋级。\u003c/p>\u003cp>我首先来做个自我介绍，我是一名来自一线的教师，我的名字是张丽。名字中的丽字，则是美丽的意思。这里更多的是指向心灵美吧。美在心灵，能够为他人着想，不计较个人得失。还觉得自己美在到现在对好多事情都保有一份好奇，放空自己，去尝试、摸索、挑战，用空杯接纳的状态，去收获成长。还美在读书，无论是在工作的地方，在家里，我都喜欢去静静地去读一本书，沉浸其中，平和和喜悦便随之而来；而且想要更好地助人达己的话，自己要有一江水的状态，而一江水的获得，最好的途径就是读书。我想有了不断读书的累积，好奇接纳的状态，在不久的将来会成为夜空中的星星，照亮自己也照亮别人，成为照亮夜空的那一抹星光就是我的目标和期盼。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>今天是我第一次参加拆书帮晋级的日子，首先给小伙伴们解释一下什么是【拆书法】，拆书的拆并不是拆散的意思，而是强调把书本里的知识转化为学习者的能力。\u003c/p>\u003cp>其核心的工具就是运用RIA三张便签去阅读，当读到最触动自己内心的片段，我们就可以停下来思考这个片段的内容，再联系我们过去的经历，去思考我们未来的目标和行动。\u003c/p>\u003cp>拆书法，它强调了以学习者为中心，而不是以知识为中心，其目的是帮助我们成人提升思维，提升解决问题的能力。它让我们深度理解知识的基础上，去催化我们的行动，更好地去帮助我们实现知行合一。\u003c/p>\u003cp>【拆书帮】是拆书法学习爱好者的社群，表现为各地的拆书帮分舵也叫拆书帮俱乐部。拆书帮分舵是非营利性组织，其使命是帮助更多学习爱好者成长为拆书家。在拆书帮社群里学习成长，更是站在更高一层的维度，把学到的知识拆为己用，全面提升自己解决问题的能力。拆书帮以书会友，帮助我们践行，促进我们成长，是一个温暖的组织。\u003c/p>","ratings_count":2,"texts":[{"id":18185,"quote":"\u003cp>关于拆书帮就介绍到这里，现在步入主题，请大家花2分钟时间看下我发给大家的拆页，\u003c/p>\u003cp>拆页片段来自 W2-D1：结构--AAA 拆解片段来自《教练型管理者》\u003c/p>\u003cp>【R：阅读原文片段】\u003c/p>\u003cp> 教练型管理的积极性反馈技术——AAA\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。\u003c/p>\u003cp> 这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。\u003c/p>\u003cp>积极性反馈的注意要点如下：\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地评判。\u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给与评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。\u003c/p>","explains":"\u003cp> 好，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>【WHAT】：这个拆页讲述了如何用积极反馈去激发别人潜能的方法。\u003c/p>\u003cp>【WHY】通常来讲，我们在给别人反馈时，常常用标签和评判来伤害对方，没有聚焦别人的行为和事实，常常招来别人的反感，使想要谈的事情变得异常的艰难。运用了这种积极反馈技术，既表达自己的真诚，又能成功激发别人的潜能，从而去促进一些有意义事情的生成或持续。\u003c/p>\u003cp>【HOW】：\u003c/p>\u003cp>这种积极反馈分为三个步骤：\u003c/p>\u003cp> 1.说事实。把自己看到的事实说出来，做到客观不加评判。\u003c/p>\u003cp>2.释影响。阐释这一事实带来的积极影响，并尽其所能的去扩大影响。从而激发别人的潜能。\u003c/p>\u003cp>3.言感谢。最后对对方的行为表于由衷的欣赏和感谢。\u003c/p>\u003cp>【WHERE】：这种积极反馈的方法适用于家人，朋友以及职场的沟通，适用于任何有效陪伴赋能的场合。不适用于一对多的场景。\u003c/p>","interaction":"\u003cp>看完拆页的内容，我立即联想到发生在我身上的一个经历（故事）：\u003cbr>【时间】前两天【地点】家里【人物】我和老公\u003c/p>\u003cp>【事件】起因：老公下班回家，拿起手机看，过一会还在看。\u003c/p>\u003cp>【经过】我便会走过去，跟他交流：“你一天到晚都玩手机，你也不陪一下娃娃。”“吗哟，我不上班，就陪你们嘛。”或者这样回应，：“才刚拿到，就一天到晚了”语气极其的厌烦。\u003c/p>\u003cp>【结果】这样开场后，就交流不下去了。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>以上的反馈交流就没有去描述对方的客观事实，一开始就招致对方的反感，又怎么能谈的下去呢？什么是一天，从早到晚才是，其实别人就仅仅一会儿或者没有半小时，如果一开始就摆出客观的事实不加评判，那么自己的反馈必将带来积极的效果。\u003c/p>\u003cp>以后我怎样应用（目标与行动）\u003c/p>\u003cp>【目标】这个月还剩下二十多天了，在这二十几天里，我将运用这种积极反馈的方法，和老公沟通，尝试营造和谐的家庭关系。\u003c/p>\u003cp>【我的行动】\u003c/p>\u003cp>这个月剩下的二十多天里，我都会当一个观察者，当我发现老公优点的时候，我就用这AAA积极反馈的方法跟他进行沟通。计划是每两天用一次,这是最低的保底要求。当然生活中的随机性比较大，有时候发现的话也可以随机给他讲。\u003c/p>\u003cp>1.说事实。把自己看到的事实说出来，做到客观不加评判。\u003c/p>\u003cp>如：一天老公做了一桌子的菜，坐下来，我就可以这样说：“老公，你做了五菜一汤，三荤两素，好丰盛啊！” \u003c/p>\u003cp>2.释影响。阐释这一事实带来的积极影响，并尽其所能的去扩大影响，真正激发别人的潜能。\u003c/p>\u003cp>如：我会接着说：“你做的这些菜会让我们干掉两碗饭，凉拌鸡好吃，肥肠也特别软糯，不仅我喜欢，大宝，小宝也都喜欢吃，实在是太香了。”\u003c/p>\u003cp>3.言感谢。最后对对方的行为表于由衷的欣赏和感谢。\u003c/p>\u003cp>我就会接着说：“特别感谢你哈，为我们做了那么多好吃的。”\u003c/p>\u003cp>当这样和老公交流反馈的时候，他也会特别有成就感，家里也会更有爱了。这一月我将持续用这样的方法与他进行沟通，让家人都感到有爱在流动，去努力营造和谐的家庭关系。\u003c/p>\u003cp>好的，今天，咱们一起学习了教练型管理的积极反馈的方法，希望大家能在生活中多去运用，多用，我们的生活将会变得更加美好。好的，今天，我的晋级讲解就到这里，请各位老师，各位小伙伴给出我的苹果和洋葱，谢谢。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1663080796000,"updated_at":1665215170000,"ria":true},{"id":14165,"topic":"教练型管理","learn_goal":"","remark":"拆书晋级","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"无问西东","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>请问观察家老师拿到记录表、准备表和拆页了么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请问各位小伙伴都拿到我的拆页了么？好，现在正式开始今天的晋级。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>自我介绍\u003c/strong>：大家好，我是今天的晋级者游芳。目前在成都读大三，自己比较喜欢到处旅游到处玩，喜欢探索新奇新鲜的事物。我也是一位学习者，路漫漫其修远兮，未来的路还很长，很高兴在这样一个年纪就遇见优秀的你们，我会慢慢努力的。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>根据现在的实际情况，我们就自成一组进行讨论，等会儿会让大家进行讨论分享的。\u003c/p>","ratings_count":1,"texts":[{"id":18177,"quote":"\u003cp>\u003cstrong>下面请大家花2分钟的时间阅读拆页，读完后在评论区打一波666。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R：阅读原文片段】\u003c/strong>\u003c/p>\u003cp>拆解片段来自《教练型管理者》\u003c/p>\u003cp>\u003cstrong>教练型管理的积极性反馈技术——AAA\u003c/strong>\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。\u003c/p>\u003cp>这3个要素缺一不可，我们简称为AAA反馈技术\u003c/p>\u003cp> 积极性反馈的注意要点如下：\u003c/p>\u003cp> 首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地评判。 其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给与评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。\u003c/p>","explains":"\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>今天给大家分享的拆页选自《教练型管理者》，作者俞清、金慧英\u003c/p>\u003cp>\u003cstrong>Feature：特征\u003c/strong> 他们两人倾心合力相著，都是名校毕业，也是名企工作，两人是具备管理、咨询、教练实际经验的企业管理者和教练。豆瓣评分8.4分和得到的推荐，据说拉卡拉企业创始人也非常推荐这本书。\u003c/p>\u003cp>\u003cstrong>Advantage：优势\u003c/strong> 关于管理类的书籍很多，与同类书籍相比较，这本书是从教练型管理者的角度出发，视角独特，如果你想在短时间里成为一名优秀的教练型管理者，那么本书就是你很好的选择。\u003c/p>\u003cp>\u003cstrong>Benefit2：拆页价值 \u003c/strong>今天带来的这个拆页是关于用教练型管理的积极性反馈技术，学习完，你能掌握三个步骤，让你轻松应对你和员工或生活工作中需要进行反馈的场景。\u003c/p>\u003cp>\u003cstrong>内容重述\u003c/strong>\u003c/p>\u003cp>\u003cstrong>好，我看到大家已经看完拆页了。接下来，我分享一下自己的理解和体会。\u003c/strong>\u003c/p>\u003cp>【WHAT】根据3A教练型积极反馈术我又称之为事反常，对他人的行为作出积极的反馈。\u003c/p>\u003cp>【WHY】我们对别人的反馈其实就很简单粗暴，挫伤积极性，应用3A反馈术能客观积极的对事实真相进行评价，产生积极的反馈效果。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>1、事就是对事实进行客观描述。昨天晚上十点了，妹妹在书桌写作业。\u003c/p>\u003cp>2、反就是针对事实进行反馈。这段时间你的学习非常的认真努力，我和妈妈都为你感到高兴\u003c/p>\u003cp>3、常与偿谐音。有给予、回报、愿望之意。对他人做的事情给予肯定，给予支持和鼓励，表以达感谢和愿景以及回馈礼物。希望你继续保持学习的势头，我和妈妈都是你的后勤保障。\u003c/p>\u003cp>【WHERE】where在书中主要是针对企业家管理者对下属进行有效的积极的正面反馈，可以应用于工作中生活中对别人的行为进行反馈。不适用于日常和熟人之间的闲聊。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（拆书家提问设计）\u003c/strong> 刚刚我们学习了在向他人进行反馈的“事反常三字法”，那么请每个小伙伴都回想一下自己过往有没有类似的在工作中向同事或者生活中向家人朋友老师进行反馈时导致不良后果或者不好影响的经历呢？这个环节我会给大家两分钟的时间思考，我将请代表各用1分钟的时间在小组里分享，方便开麦的小伙伴就开麦回答，不方便的小伙伴就把自己的分享打在聊天区里面。PPT上的这个案列，大家想不出来的话可以参考一下。\u003c/p>\u003cp>好，时间到，下面我们请这位伙伴进行分享，大家欢迎。\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）\u003c/strong>学习者经验分享\u003c/p>\u003cp>A1徐伟\u003c/p>\u003cp>去年年底，我在山东的上家公司做项目经理的时候，因项目用设备制作进度滞后，有位项目团队成员多次去外地督促设备生产进度，对项目帮助很大。\u003cbr>当时我作为项目经理，在月度考核的时候，给他发了一笔项目奖金，但没有进行积极反馈。\u003cbr>现在回头看，奖金的激励效果可能有限，当时如果用AAA积极反馈，在团队中公开表扬，描述出差行为，阐述项目进度加快，进而药品上市提前，造福中国广大病人的积极影响，表示感谢，并颁发项目奖金。\u003cbr>这样给整个团队带来的赋能效果会更好，也可以给后面的工作带来更大帮助\u003c/p>\u003cp>好，非常感谢这位小伙伴的分享。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>接下来，请你想要一下自己将未来的两个星期以内，在什么样场景下，你要如何做，做什么事，达到什么样的目标，在做的过程中运用今天讲到的事反常（描述事实、积极反馈，给予回馈）三个步骤。注意这个目标不是喊口号，而是可衡量可观测的可达到的。现在给大家3分钟的时间，把行动规划写到我们的聊天区。\u003c/p>\u003cp>\u003cstrong>看到有的小伙伴在聊天区已经写了，由于时间原因，没写完的小伙伴可以等会结束后接续再写，发到我的微信上。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）：\u003c/strong>学习者应用\u003c/p>\u003cp>1、孙毅\u003cbr>今晚儿子再玩乐高时，跟他说:儿子,你把乐高作品和颗粒散落了一地，不仅看着乱，而且爸爸妈妈路过时很容易踢坏。你把他收到旁边的桌子上可以吗?等儿子收的时候，说:谢谢宝贝,你行动力好棒,妈妈陪你一起收!\u003cbr>2、徐伟\u003cbr>原定9月16日，我们公司有一个设备招标，我将作为评标人参加，可以用这种方式，给组织招标的同事进行积极反馈。\u003cbr>3、张丽\u003cbr>未来一周用这种积极反馈的方法,给孩子反馈，建立好的亲子关系\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>现在我们就总结一下，今天我们一起学习了\u003cstrong>教练型管理的积极性反馈技术及事反常三步法，希望能够应用到我们的生活中。\u003c/strong>我的TF1-2晋级就到这里，感谢大家的参与。请大家将苹果和洋葱发送到聊天区。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1663056198000,"updated_at":1665214738000,"ria":true},{"id":13995,"topic":"如何使用积极性反馈与建设性反馈，提升管理能力。","learn_goal":"","remark":"你想成为教练型管理者吗？不论对方做得好，还是不好，你都能使用正确的反馈技术提升你的管理能力。那么今天的《教练型管理者》课程，值得你来学习。只需要花不到1小时的时间，你就可以让自已朝一名优秀教练型管理者又前进了一步。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"韩军华","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>【开场介绍/分组】\u003c/strong>\u003c/p>\u003cp>Hello,大家好，我是韩军华，是今天TF2-4拆书家，用三个标签介绍我自已，第一我是一名运动爱好者，第二我是一名亲情守护者，第三我是一名拆书法的追随者。\u003c/p>\u003cp>因为今天会有讨论的环节，我们现在先进行分组,主要分成3组：\u003c/p>\u003cp>其中樊老师、张军老师，张兮吾老师为1组； 唐老师、倪老师、丁老师为1组； 李老师、丹丹老师、驰驰老师为1组。\u003c/p>\u003cp>\u003cstrong>【FAB图书介绍】\u003c/strong>\u003c/p>\u003cp>今晚所拆的书是2019年6月由中信出版社出版的《教练型管理者》\u003c/p>\u003cp>\u003cstrong>F特征：\u003c/strong>\u003c/p>\u003cp>本书作者俞清：普华永道员工发展教练，作者金慧英，绩能教练院长，他们俩人联合所作《教练型管理者》，是一本企业管理类书籍，是一门新的管理技术，让管理者运用教练的方式激励员工，让员工发挥创意，找出解决之道。\u003c/p>\u003cp>\u003cstrong>A优势：\u003c/strong>\u003c/p>\u003cp>该书豆瓣评分达到8.3分，与同类书籍相比，内容结构严谨、讲解风格简明、工具方法实用和情境案例生动，可操作性强，能够让读者在短时间内成为一名优秀的教练型管理者。\u003c/p>\u003cp>\u003cstrong>B1利益：\u003c/strong>\u003c/p>\u003cp>在日常工作中，当您兴高采烈分享你的管理方法，而你的下属却反应冷淡？当您一心想把绩效搞上去，可是员工仍然事不关己、高高挂起？等等，面对这些窘境，如何破冰，如何激励、如何引起共鸣，本书通过深度倾听，有力提问、有效反馈等众多方法，一一帮助大家解决这些问题。\u003c/p>\u003cp>\u003cstrong>B2利益：\u003c/strong>\u003c/p>\u003cp>今天我们所要学的2个拆页，一是积极性反馈技术，简称：“积极性反馈”，二是建设性反馈技术，简称：“建设性反馈”。\u003c/p>\u003cp>积极性反馈可帮助我们在面对他人良好的行为表现时，言之有理、赞之有据，肯定他人，强化他人，使其再接再励；\u003c/p>\u003cp>建设性反馈可帮助我们在面对他人行为不佳时，指导他人，帮助他人及时改进不足。\u003c/p>\u003cp>两个拆页互为补充，相互促进，可交替使用。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>今晚的学习目标是：\u003c/p>\u003cp>拆页1的学习目标是当遇到他人的行为正确且结果有效的时候，在座的各位能使用积极性反馈，给予他人肯定赞扬，增强信心和动力；\u003c/p>\u003cp>拆页2的学习目标是当遇到他人的行为错误导致结果不好的时候，在座的各位能使用建设性反馈，给予他人指导与帮助，改正错误行为。\u003c/p>\u003cp>现在请大家阅读我刚才分发给大家的拆页1，给大家1-2分钟，读完请举手示意一下。\u003c/p>","ratings_count":3,"texts":[{"id":17998,"quote":"\u003cp>\u003cstrong>拆页1：积极性反馈技术——AAA\u003c/strong> \u003cstrong>（来源于俞清\u003c/strong> \u003cstrong>金慧英《教练型管理者》P117-P118）\u003c/strong> \u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：\u003c/p>\u003cp>\u003cstrong>一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。\u003c/strong>这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。不难看出，上述学员的反馈完全符合这3个要素。\u003c/p>\u003cp>积极性反馈的注意要点如下。 \u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单的评判。 \u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给予评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。 \u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。 \u003c/p>\u003cp>举例： \u003cstrong>■描述行为和事实。\u003c/strong>纪凡，上周一你主动向部门经理请教销售电话的话术，每天按时完成50个电话拜访，还按公司要求整理出有效客户的档案，并且详细备注了特定客户的需求以及你个人的建议。 \u003c/p>\u003cp>\u003cstrong>■阐述影响及评价。\u003c/strong>这样的工作方式，不仅会加快你本人的销售技能的提升，也为后续销售部门的其他同事上门拜访客户提供了有力的保障，为团队绩效目标的达成做出了卓越的贡献。我从中也能够感受你是特别有责任心的人。 \u003c/p>\u003cp>\u003cstrong>■表示欣赏和感谢。\u003c/strong>你对工作认真负责的态度为其他新同事树立了榜样。我非常欣赏你，谢谢你做出的表率和贡献。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>好，我看到大家都读完了，这段拆页讲了什么呢？这段拆页告诉我们在工作管理中如何通过“说行为、说影响、说感谢”进行有效的积极性反馈，激励他人，感谢他人。 \u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>那么，说起积极性反馈，我们通常是怎么做的呢？\u003c/p>\u003cp>比如当我们听完他人培训后，感觉说得非常好，但究竟好在哪里？轮到自已给反馈意见时又说不清楚；又比如你兴致勃勃地完成了一项工作，希望得到领导的赏识，领导却认为这是份内的事情，没啥好表扬的，只字不提。前者是给予别人反馈，说你讲得好，就是好，陷入泛泛而谈，但是好在哪里，始终说不清，道不明，反馈有效性大打折扣；后者是希望得到别人的积极性反馈，而别人不给，难免会失望，消极，情绪低落。\u003c/p>\u003cp>不论前者还是后者，都没有使用积极性反馈，不能更好地强化行动者的行为意愿，使行动者更有动力再接再励。\u003c/p>\u003cp>\u003cstrong>【失败案例】\u003c/strong>\u003c/p>\u003cp> 说到此，我举一个自已的失败事例，由于工作的原因，一年365天，我300多天都在江苏工作，很少回到浙江总部上班，即使偶尔回去，也只是停留2-3天，每次回去，我发现我的办公桌椅都是干干净净的，我同事小王说，小张每天打扫时都会帮我打扫，从不计较，拥有这样的一个同事，我内心感激，但我每次话到嘴边，吐出来只有两个字“谢谢”。\u003c/p>\u003cp>这种礼貌性的“谢谢”难免过于平淡，打扫一次，这样说“谢谢”，没什么，两次、三次，说“谢谢”，也没啥，可是连续几个月，甚至一年都这么做，用“谢谢”两个字，是不是轻了？是不是容易让人产生误解：“热脸贴你的冷屁股了？”\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>说到这，让我们先回到拆页1，看看拆页1是如何运用有效的积极性反馈呢？\u003c/p>\u003cp>以下简称为：“积极性反馈三步法”。\u003c/p>\u003cp>第一、说行为：\u003c/p>\u003cp>(1) 只说观察到的行为与事实，不带任何主观评价与判断； \u003c/p>\u003cp>(2) 只说行为与事实本身，除此之外，无需多讲。\u003c/p>\u003cp>第二、说影响：\u003c/p>\u003cp>（1）说出行为和事实将会带来什么样的积极影响，并给予肯定评价。\u003c/p>\u003cp>（2）评价不仅要说个人的，也要说团队的或者整体的积极影响。\u003c/p>\u003cp>第三、说感谢：\u003c/p>\u003cp>（1）指出上述行为与事实给自已带来的美好感受； \u003c/p>\u003cp>（2）针对上述行为与事实表达自已的欣赏与谢意。 \u003c/p>\u003cp>\u003cstrong>【加工成正面案例】\u003c/strong>\u003c/p>\u003cp> 若一切可以重来，运用今天所学积极性反馈三步法，将以上案例，加工成正面案例，我可以这样做：\u003c/p>\u003cp>第一、说行为：小张，每次回来，我都看到我的办公桌椅都是干干净净的，听同事说，你每天上班的时候，都会帮我打扫一遍。\u003c/p>\u003cp>第二、说影响：你这样的工作方式，勤快、热心，不仅大家喜欢你，我也喜欢你。\u003c/p>\u003cp>第三、说感谢：这种乐于助人而不斤斤计较的工作态度，我很欣赏，谢谢你小张，和你一起共事，真好！\u003c/p>\u003cp>\u003cstrong>【预防性讲解】\u003c/strong>\u003c/p>\u003cp>有些伙伴可能会说，员工表现得好，我们直接说声“谢谢”或者说声“你做得不错”，这样不就够了吗？还要说那么多吗？通常的做法也许这样就可以了，但这种礼貌性谢意，往往难以给对方留下深刻的印像，无法让对方感受到“我这样做，值！”，而使用积极性反馈，表达真诚的谢意，能让对方感受到“我所做的一切，你看得见，你欣赏我的重视感，”“士为知已者死，女为悦者容”，这种认同感，才是最易打动人心的，这种认同感，才是强化行为意愿更好的动力。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>以上积极性反馈，不仅仅适用于工作场景，其它方面如长辈对晚辈，父母对子女，老师对学生等方面，只要对方做出了对的行为，需要给出积极反馈时，都可以使用，当然，如果对方做事的方式有偏差，态度不端正，就不适合了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验（显像提问发表）】\u003c/strong>\u003c/p>\u003cp>分享到这里，大家回想一下，过去的1个月内有没有遇到过这样的情景：\u003c/p>\u003cp>比如：当你回到家里，发现自家的孩子把家里打扫得干干净净，而你却认为孩子在家没啥事帮大人做点事情，应该的，却不知为孩子一下午的付出表达真诚的谢意？\u003c/p>\u003cp>现在给大家1分钟时间，一起来回想一下，可以把你们想到的场景内容写在便签纸上，然后小组内分享。稍后我会邀请一位小伙伴现场分享。这里需要提醒大家注意的是：\u003c/p>\u003cp>只讲当时发生了什么就可以，不需要说其它的。\u003c/p>\u003cp>经过1分钟的小组讨论，丹丹老师分享自已的个人案例如下：\u003c/p>\u003cp>上周六，常州龙城分舵拆书帮搞活动，丹丹老师带自已儿子来参加，期间，孩子特别调皮，动来动去，我怕孩子会影响活动顺利进行，一直狠狠地训斥孩子，要求孩子不许说话、不许影响别人，但是孩子仍然管不住自已，吵闹，这时，樊老师就给丹丹老师孩子买了一个特别好吃的蛋糕，孩子吃着蛋糕，就去一边玩去了，再也不吵闹了。\u003c/p>\u003cp>\u003cstrong>【A1+反思加工经验】\u003c/strong>\u003c/p>\u003cp>感谢丹阳老师的精彩分享，若一切可以再来，运用我们今天所学的方法，我们又会怎么做呢？\u003c/p>\u003cp>这里我继续给大家2分钟时间，大家可以根据运用积极性反馈三步法来表达感激之情，2分钟后，我将请一个小伙伴来分享。\u003c/p>\u003cp>2分钟后，我再次邀请丹丹老师分享自已的做法如下：\u003c/p>\u003cp>第一、说行为：樊老师非常细心地观察着我的孩子，买了一块蛋糕，又大又圆，孩子都比较喜欢的那一种； \u003c/p>\u003cp>第二、说影响：孩子拿了蛋糕之后，再也不吵，也不动来动去，没有孩子的吵闹声音，整个活动现场，井然有序地进行着，我也非常开心；\u003c/p>\u003cp>第三、说感谢：通过这样的方法，我的孩子不再打扰我参加拆书帮活动，非常感谢樊老师，让我开心地完成周六的拆书帮的活动。\u003c/p>\u003cp>让我们再次用热烈的掌声感谢丹丹老师的精彩分享，丹丹老师刚才使用积极性反馈三步法“说行为、说影响、说感谢”表达了对樊老师的谢意，日后坚持使用，效果肯定也会越来越好。\u003c/p>\u003cp>现在让我们回顾一下，我们今晚所学的第一个拆页：\u003c/p>\u003cp>“积极性反馈三步法”：第一、说行为，第二、说影响，第三、说感谢。\u003c/p>\u003cp>\u003cstrong> 以上就是我第一个拆页的分享，当别人表现好的时候，我们要用积极性反馈，锦上添花；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果对方表现不好的时候怎么办呢，那我们就用今天的第二个拆页（建设性反馈），\u003c/strong>\u003c/p>\u003cp>\u003cstrong>正所谓：“良药苦口利于病，忠言逆耳利于行”，使用建设性反馈改进不足的地方。\u003c/strong>\u003c/p>\u003cp>让我们先来看看第二拆页的学习目标是什么？\u003c/p>\u003cp>拆页2（建设性反馈）的学习目标是当遇到他人的行为错误导致结果不好的时候，学习者能使用建设性反馈，给予他人帮助，指导和修正错误行为。\u003c/p>\u003cp>现在给大家1-2分钟，阅读我刚才分发给大家的拆页2，读完的伙伴请举手示意一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":17999,"quote":"\u003cp>拆页2：建设性反馈技术——AID （来源于俞清 金慧英《教练型管理者》P120-P121）\u003c/p>\u003cp>有 效 的 建 设 性 反 馈 由 3 个 要 素 构 成 ： \u003c/p>\u003cp>\u003cstrong>一\u003c/strong> \u003cstrong>是描述行为和事实（Act）；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>二\u003c/strong> \u003cstrong>是阐述影响及后果（Impact）；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>三\u003c/strong> \u003cstrong>是指明期待的行为和结果（Desired outcome）\u003c/strong>。\u003c/p>\u003cp>这3个要素缺一不可，我们简称为AID反馈技术，如图5-3所示\u003c/p>\u003cp>建设性反馈的流程首先是描述行为和事实，然后阐述这些行为带来的影响及后果，最后指明期待的行为和结果。建设性反馈的注意要点如下。 \u003c/p>\u003cp>\u003cstrong>首先，行为和事实的描述应具体、客观和真实。\u003c/strong>我们在反馈时不仅需要顾及行为的结果，更要关注行为过程本身，因为过程会产生必然的结果。我们在描述行为时一定要注意观察，我们要观察人的具体行为，而不是对人本身进行评判。 \u003c/p>\u003cp>\u003cstrong>其次，我们在阐述影响及后果的时候，不仅要描述这些行为对集体和团队的影响及后果，更要描述这些行为对下属的影响及后果。这与人性的某个特点相关。\u003c/strong>\u003c/p>\u003cp>假设你因为迟到了并错过一个非常重要的销售电话，从而使公司错过了一笔大单。这时，经理A是这样对你反馈的：“李主管，因为你今早晚进公司1个小时，客户打了5个电话都没有找到你本人，所以决定与竞争对手合作了。这给我们公司带来了重大的损失。”经理B是这样对你反馈的：“李主管，因为你今早晚进公司1个小时，客户打了5个电话都没有找到你本人，所以决定与竞争对手合作了。这不仅给我们公司带来了重大的损失，也影响了你个人的绩效，明明到手的两万元的销售提成没有了。”哪一个反馈对你更有触动？答案肯定是后者，因为跟自己的利益直接相关。因此，在阐述影响及后果的时候，更要描述对下属的影响及后果，这样才能真正引起对方重视。 \u003c/p>\u003cp>\u003cstrong>最后，期待的行为和结果也同样必须具体、明确和可行，并且需要正向表达。\u003c/strong>所表达的期待是下属今后需要修正的行为，所以为了下属正确落实行动，期待的行为和结果必须足够具体、明确和可行。我们经常会碰到在下属完成了某项工作之后，结果却跟管理者的预期有很大的差距。当管理者向他提出困惑时，对方的回答大部分是：“噢，我不知道你有那样的要求。”很多员工的绩效结果与管理者的预期有差距，这与工作要求不明确直接相关。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>好，我看到大家都读完了，拆页2分享了一个什么内容呢？在座的各位可不可以用自已的一句话来进行总结一下？讲讲我们今天的这个拆页的\u003cstrong>WHAT是什么？（简单互动）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>其中张老师回应说：“如何做到建设性反馈？”，话音刚落，唐老师接话说“让良药不再苦口，让忠言变得顺耳。”\u003c/strong>唐老师的分析非常精彩，所以我们今天拆页的\u003cstrong>WHAT是\u003c/strong>我们在日常生活工作中碰到对方的行为不对时，通过使用“讲行为、讲后果、讲要求”等有效的建设性反馈，给予他人指导和期望，帮助他人改善错误的行为。 \u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp> 当我们发现别人的行为不对时，比如有人在生产车间吸烟，我们一般情况下会怎么做呢？\u003c/p>\u003cp>我们通常会说这个地方不准吸烟，却很少说“这个地方吸烟会对其本人有什么直接的伤害以及不良的后果”，如果我们不用建设性反馈，吸烟的人，下次可能还会在车间继续吸烟，甚至还会躲起来吸，根本不让你瞧见，因为做错事情的人并没有意识到自已的利益会受损，只是认为你不让他吸，没有直击他的痛点，做事没有改善的意愿，如果我们使用建设性反馈，吸烟的人会意识到自已的利益损失很大，后果也很严重，错误行为因为建设性反馈就容易得到改正。\u003c/p>\u003cp>比如我们告诉吸烟者一旦被抓到，不仅会罚款500元，而且还会被开除工作，如果吸烟引起火灾等严重后果，还会追究刑事责任，甚至会坐牢，如最近常州小河就有这种事情发生，一个月两起，员工吸烟失火，烧掉了两个厂房，如此一来，就容易杜绝这类事件发生。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp> 现在，让我们先回到拆页2，看看拆页2是如何进行有效的建设性反馈呢？以下简称为：“建设性反馈三步法”。\u003c/p>\u003cp>第一、讲行为：\u003c/p>\u003cp>（1）不带任何主观地评价与判断，讲述行为和事实要具体、客观和真实； \u003c/p>\u003cp>（2）重点讲述行为和事实产生的过程与结果。\u003c/p>\u003cp>第二、讲后果：\u003c/p>\u003cp>（1）讲出这些行为对集体和团队带来的负面影响及后果\u003c/p>\u003cp>（2）重点讲述这些行为对本人带来的直接利益损失及后果。\u003c/p>\u003cp>第三、讲要求：\u003c/p>\u003cp>（1）要正向表达需要改正的行为和结果是什么； \u003c/p>\u003cp>（2）要求改正的行为和结果要具体、明确和可行。\u003c/p>\u003cp> \u003cstrong>【意译原书案例】\u003c/strong>\u003c/p>\u003cp>拆页中的原文案例是公司领导关于下属迟到的建设性反馈案例，让我们运用一下，意译原书案例，看看其它的工作场景，是不是也可以运用？\u003c/p>\u003cp>比如：\u003c/p>\u003cp>卖房子，上个月，我去看望我的宁波朋友小李，正好碰到他接待一个名字叫张百万的客户，张百万穿着很土，说话外地口音重，坐在沙发上，抽着一根10元一包的“泰山”牌香烟，我朋友小李认为张百万“人不如名”，于是他就随手招来新来的同事小林，说：”小林啊，这可是百万大哥，你刚来，别说哥不给你机会，你要好好把握一下。我有点事，出去一下“。于是我朋友小李开溜了，没想到这位张百万当天下午就一次性认购了3套房。\u003c/p>\u003cp>这时，售房部王经理找到我的朋友说：“小李啊，你早上接待的那个客户，太牛了，你认为对方不会买，所以你把这个客户让给了小林，没想到吧，兄弟，小林因为你这个客户直接买了3套房，刚来一个星期，老板就让他直接转正了。”\u003c/p>\u003cp>王经理刚走没一会儿，孙经理也找到我的朋友说：“老李啊，我跟你说，上午来的那个张百万，真没想到啊，妥妥的，土豪啊，一口气买了3套房，600万了，眼睛都不眨一下，那个张百万跟领导说你不愿意接待他，说我们服务有待提高啊，本来这个百万单子是给你的，算算提成，老李啊，整整6万块啊，想想都激动啊！哎，可惜了，到嘴的鸭子飞了、没了。”\u003c/p>\u003cp>\u003cstrong>以上哪一个反馈对我朋友触动更大呢？是第一种说法还是第二种说法？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在座的老师回答说是第二种。因为第二种说法直接伤了我朋友小李的心了，\u003c/strong>所以晚上我们几个朋友就开始安慰小李受伤的心灵，约他去KTV K歌，他上来就点了一首：“为什么受伤的总时我”，那嘶哑的声音，那落寞的神情，深深地把我们几个老少爷们搞得眼眶都红了，现在想想6万块，对于一个打工者来说，杀伤力不是一般的大啊，而是非常巨大啊！......\u003c/p>\u003cp>\u003cstrong>【预防性讲解】\u003c/strong>\u003c/p>\u003cp> 有人会说，使用建设性反馈三步法，讲话的顺序可不可以打乱？比如先讲要求，再讲行为与后果，是不是效果一样？\u003c/p>\u003cp>如果这样讲，似乎没毛病，当你向对方提要求的时候，对方可能本能地就会反感，认为你在找茬，或者对方已经在为损失而伤心落泪的时候，你一张口讲要求，对方可能就会认为你落进下石，往伤口上撒盐、不近人情，根本听不进去，反而事与愿违。\u003c/p>\u003cp>而先讲行为，再讲后果、再讲要求，一步一步地讲清事情的前因后果，客观、具体，不添油也不加醋，容易让对方逐步接受是自已的不良的行为导致了不良的后果，连累了主管，也连累了公司，而主管代表公司对自已提些改善的要求，也在情理之中，这种反馈的方式就容易让人接受、容易让人自我反省，从而主动改正不良的行为。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>所以，使用建设性反馈，不论是领导对员工还是父母对子女，老师对学生，甚至同事之间，朋友之间，如果对方的行为有偏差，态度偏激，问题并不严重的时候，你想指正对方，希望对方改正，就可以使用建设性反馈，如果对方问题很严重，如行为已经违法，或者对方表现很优秀，做得比你还好，这两种情况，那么建设性反馈就不适合使用。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3：场景演练】\u003c/strong>\u003c/p>\u003cp>我们刚刚学习了建设性反馈。现在一起做一个演练，请大家认真听一下要演练的场景：\u003c/p>\u003cp>销售部王经理同销售员小李一起去客户那里进行项目介绍，当王经理与小李来到客户会议室，打开电脑，准备进行项目介绍时，王经理发现让小李拷贝的项目资料是最初的版本，并不是根据客户要求调整的最终版本，客户不满意，认为王经理公司根本不重视彼此的合作，直接跟另外一家公司签约了。\u003c/p>\u003cp>如果我们来到这个场景，运用刚才所学的建设性反馈三步法，王经理应该如何跟小李说呢？\u003c/p>\u003cp>现在我们按照刚开始的分组，在组内进行讨论和角色扮演，一个人扮演王经理，另一个人来扮演小李，组内演练的时间为5分钟，稍后我会至少邀请一组伙伴来表演一下，大家在讨论的时候可以参考我刚刚发给大家的这个表格。\u003c/p>\u003cp>好，5分钟到，哪组伙伴愿意扮演一下如何使用建设性反馈呢？\u003c/p>\u003cp>其中樊老师、张军老师两位老师举手示意，小组分享如下：\u003c/p>\u003cp>樊老师扮演王经理、张老师扮演小李。\u003c/p>\u003cp>小李说：“经理，实在对不起，这都是我的错。”\u003c/p>\u003cp>王经理说：“小李，今天你带来的资料是最初的版本，并没有带来按照客户的要求修改之后的最终版本（讲行为），现在客户很不满意，未来有可能彻底跟我们终止合作，给公司带来巨大的损失，从而也会影响你的个人绩效，还会影响你的升职与加薪（讲后果），我希望在这件事情上你能够吸取教训，未来在遇到类似的情况，要反复确认所带的资料，做到细致认真。（讲要求）”\u003c/p>\u003cp>小李说：“好的，王经理。”\u003c/p>\u003cp>\u003cstrong>【点评与总结】\u003c/strong>\u003c/p>\u003cp>让我们用热烈的掌声来谢谢樊老师、张军老师的精彩演练，通过王经理与小李的案例，让我们进一步了解了建设性反馈三步法的实际运用，希望大家以后经常使用。\u003c/p>\u003cp>\u003cstrong>【A2：分步催化应用-1】\u003c/strong>\u003c/p>\u003cp>分享到这里，接下来，在座的各位伙伴们，对建设性反馈有所了解了，在接下来的工作中，你可能会碰到需要运用建设性反馈的场景\u003c/p>\u003cp>比如：公司承接了某项目的设计开发任务，客户要求30天内必须完成，部门将这个项目交给了小李与小张共同完成，小张任组长，小李因为老婆生孩子要照顾，自知无法有效配合小张的工作进度，就让小张跟领导请示，换一个人做，小张认为这个任务若完成，奖金不会少，为了照顾小李，就没有上报，导致任务没有如期完成，客户很不满意，要求支付违约金。\u003c/p>\u003cp>又比如，公司安排小王去客户那里谈合作的事情，谈判进度不理想，一度陷入僵局，小王认为没有戏了，订了第二天返程的车票，准备打道回府，晚上一个人无聊，就去酒巴喝酒，喝得酩酊大醉，第二天早上客户要求再谈一次，这次接见小王的是张副总，张副总一连串的问了小王好几个问题，小王因为昨晚醉酒，状态很不好，招架不住张副总的提问，张副总认为小王不专业，最终没有达成双方的合作。 \u003c/p>\u003cp>\u003cstrong>设想一下，未来一周内，你会不会遇到类似的情景呢？\u003c/strong> \u003c/p>\u003cp>在此给大家4分钟时间，大家可以把想到的场景内容写在便签纸上,要求场景内容包含时间、地点、人物、事件等各要素，稍后我会邀请一位小伙伴现场分享，这里需要提醒大家注意的是：\u003c/p>\u003cp>只讲你想到的那个场景就好，不需要具体说会怎样去做。\u003c/p>\u003cp>好，4分钟到，哪位伙伴愿意用2分钟时间来分享一下自已想到的场景呢？\u003c/p>\u003cp>其中邀请驰驰老师分享场景如下：\u003c/p>\u003cp>\u003cstrong>驰驰老师设想明天来到妹妹的房间，看着妹妹玩手机，很投入很专注的样子，旁边放着一本心经，心想：“小妹，老玩手机，怎么行？”于是和小妹约定：每天抄写心经2张。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2：分步催化应用-2】\u003c/strong>\u003c/p>\u003cp>非常好的案例，非常感谢驰驰老师的分享，那我们现在就运用建设性反馈三步法，对\u003cstrong>接下来一周内遇到\u003c/strong>类似于驰驰老师讲的场景，或者每组自已挑选一个\u003cstrong>可能碰到的\u003c/strong>场景加工一下，运用今天所学的，现在我继续给大家5分钟时间，在小组内分享讨论一下，看看如何运用今天学习的“讲行为、讲后果、讲要求”建设性反馈？\u003c/p>\u003cp>5分钟后，我将再次邀请伙伴来分享。好，时间到，哪位伙伴愿意用2分钟时间来分享一下自已的运用呢？\u003c/p>\u003cp>\u003cstrong>我们再次邀请驰驰老师分享如下：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步，讲行为：小妹，这一周我看到你都在玩手机，即使吃饭，你都舍不得放下手机；\u003c/strong> \u003c/p>\u003cp>\u003cstrong>第二步，讲后果：小妹，老玩手机，影响视力，你不是说你不想戴眼镜吗？玩手机，最伤眼了。\u003c/strong> \u003c/p>\u003cp>\u003cstrong>第三步，讲要求：小妹，我要没收你的手机，除非你答应我每天抄写心经2张，我就让你每天玩一小时。\u003c/strong>\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>非常感谢驰驰老师的分享，说到这里，今天的两个拆页就学习结束了，在此，让我们先回顾一下今天学习的内容，第一我们学习的是积极性反馈技术，第二我们学习的是建设性反馈技术。\u003c/p>\u003cp>当遇到他人做得好的时候，我们要用什么？积极性反馈技术； \u003c/p>\u003cp>当遇到他人表现不好的时候，我们要用什么？建设性反馈技术。\u003c/p>\u003cp>两个方法，交替使用，不仅可以改善人际关系，还可以提升大家的管理能力，不仅让在座的各位成为一名好的管理者，而且将来还会成为一名优秀的教练。\u003c/p>\u003cp>希望大家常用，多用，“赠人玫瑰，手有余香”。\u003c/p>\u003cp>谢谢大家，我今天的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1660840618000,"updated_at":1661491323000,"ria":true},{"id":13900,"topic":"如何使用积极性反馈与建设性反馈，提升管理能力。","learn_goal":"","remark":"你想成为教练型管理者吗？不论对方做得好，还是不好，你都能使用正确的反馈技术提升你的管理能力。那么今天的《教练型管理者》课程，值得你来学习。只需要花不到1小时的时间，你就可以让自已朝一名优秀教练型管理者又前进了一步。","level":"TF2-4","duration":60,"status":19,"type":0,"chaishujia":{"username":"韩军华","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>【开场介绍/分组】\u003c/strong>\u003c/p>\u003cp>Hello,大家好，我是韩军华，是今天TF2-4拆书家。\u003c/p>\u003cp>用三个标签介绍我自已，第一我是一名运动爱好者，第二我是一名亲情守护者，第三我是一名拆书法的追随者。\u003c/p>\u003cp>因为今天会有讨论的环节，为了方便讨论，我们现在先进行分组,主要分成3 组：\u003c/p>\u003cp>其中樊老师、丁老师为1组，张老师、唐老师为1组； 李老师、宋老师为1组，主要分成3组。\u003c/p>\u003cp>\u003cstrong>【FAB图书介绍】\u003c/strong>\u003c/p>\u003cp>今晚所拆的书来源于俞清 、金慧英联合所作《教练型管理者》，2019年06月由中信出版社出版。\u003c/p>\u003cp>\u003cstrong>F特征：\u003c/strong>\u003c/p>\u003cp>本书作者俞清：中国注册会计师、浙江大学管理学硕士、普华永道员工发展教练； \u003c/p>\u003cp>作者金慧英，绩能教练®创始人、院长，国家高级人力资源管理师、美国宇航局4D卓越团队认证教练，他们俩人联合所作《教练型管理者》，是一本企业管理类书籍，两位作者一致认为：“一名优秀的管理者就是一名好的教练”。\u003c/p>\u003cp>\u003cstrong>A优势：\u003c/strong>\u003c/p>\u003cp>该书豆瓣评分达到8.3分，与同类书籍相比，内容丰富，可操作性强，该书强调“授人以鱼不如授人以渔”，采用严谨的内容结构、简明的讲解风格、实用的工具方法和生动的情境案例，让读者能够在较短的时间内成为一名优秀的教练型管理者。\u003c/p>\u003cp>\u003cstrong>B1利益：\u003c/strong>\u003c/p>\u003cp>在我们日常工作中，当您热情高涨，分享你的主张与管理方法，而你的下属却反应冷淡？你会不会很纳闷？您一心想把绩效搞上去，可是员工仍然我行我素，事不关己的样子？你会不会很难受？\u003c/p>\u003cp>面对这些问题，如何激励、如何批评，如何引起共鸣，如何让心往一处想，劲往一处使，本书通过深度倾听，有力提问、有效反馈等众多方法，都可以一一帮助我们解决以上我们所关心的各种问题。\u003c/p>\u003cp>\u003cstrong>B2利益：\u003c/strong>\u003c/p>\u003cp>今天我们所要学的2个拆页，是本书中非常有效的管理方法，拆页1是积极性反馈技术，拆页2是建设性反馈技术。\u003c/p>\u003cp>拆页1（积极性反馈技术）可以帮助我们在面对他人良好的行为表现时，言之有理、赞之有据，给予别人积极的正面回应，不仅要肯定他人的行为与做法，还要强化别人的动机，使其再接再励；\u003c/p>\u003cp>拆页2（建设性反馈技术）可以帮助我们在面对他人行为不佳时，给予别人建设性指导与修正，帮助他人及时改进自已的不足。\u003c/p>\u003cp>拆页1与拆页2互为补充，一正一反，相互促进，催人反省，也催人奋进。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>今晚的学习目标是：\u003c/p>\u003cp>拆页1（积极性反馈技术）的学习目标主要是当遇到他人的行为正确且结果有效的时候，学习者能使用正向反馈，给予他人肯定的赞扬，强化对的行为，增强信心和动力；\u003c/p>\u003cp>拆页2（建设性反馈技术）的学习目标是当遇到他人的行为错误导致结果不好的时候，学习者能使用建设性反馈，给予他人帮助，指导和修正错误行为。\u003c/p>\u003cp>现在请大家跟我一起来践行拆书法，请阅读我刚才分发给大家的拆页1，给大家2分钟，读完的伙伴请举手示意一下。 \u003c/p>","ratings_count":1,"texts":[{"id":17910,"quote":"\u003cp>\u003cstrong>拆页1：积极性反馈技术——AAA\u003c/strong> \u003cstrong>（来源于俞清\u003c/strong> \u003cstrong>金慧英《教练型管理者》P117-P118）\u003c/strong> \u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：\u003c/p>\u003cp>一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。不难看出，上述学员的反馈完全符合这3个要素。\u003c/p>\u003cp>积极性反馈的注意要点如下。 \u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单的评判。 \u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给予评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。 \u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。 \u003c/p>\u003cp>举例： ■描述行为和事实。纪凡，上周一你主动向部门经理请教销售电话的话术，每天按时完成50个电话拜访，还按公司要求整理出有效客户的档案，并且详细备注了特定客户的需求以及你个人的建议。 \u003c/p>\u003cp>■阐述影响及评价。这样的工作方式，不仅会加快你本人的销售技能的提升，也为后续销售部门的其他同事上门拜访客户提供了有力的保障，为团队绩效目标的达成做出了卓越的贡献。我从中也能够感受你是特别有责任心的人。 \u003c/p>\u003cp>■表示欣赏和感谢。你对工作认真负责的态度为其他新同事树立了榜样。我非常欣赏你，谢谢你做出的表率和贡献。\u003c/p>","explains":"\u003cp>\u003cstrong>【是什么】\u003c/strong>\u003c/p>\u003cp>好，我看到大家都读完了，这段拆页讲述了什么内容？\u003c/p>\u003cp>这段拆页告诉我们在工作管理中如何通过“讲行为、说影响、谈感谢”进行有效的积极性反馈及积极性反馈需要注意的一些事项，比如讲行为要注意客观，具体，说影响不仅要说个人，也要兼顾团队和整体，谈感谢，也不要忘记表示欣赏。 \u003c/p>\u003cp>\u003cstrong>【为什么】\u003c/strong>\u003c/p>\u003cp> 那么，说起积极性反馈，日常工作中，我们会经常碰到，我们通常的做法会怎样的呢？当我们听完他人演讲或者培训后，感觉说得非常好，非常到位，但究竟好在哪里？怎样才算是到位？轮到自已给反馈意见时有时又说不清楚，又比如我们兴致勃勃地完成了一项工作，希望得到领导或者老板的赏识，领导或者老板却认为这是我们份内的事情，没有什么好表扬的，从而只字不提、表情平淡。\u003c/p>\u003cp>前者是我们需要给予别人反馈，不知如何有效的进行正面反馈，难免陷入泛泛而谈，说你就是讲得好，但是好在哪里，一般也说不清楚，反馈有效性就大打折扣；\u003c/p>\u003cp>后者是我们希望得到别人有效的反馈，而别人没给，难免会弱化自已行为动作的积极性。\u003c/p>\u003cp>不论前者还是后者，都不能更好地强化他人行为的意愿，使演讲者更愿意讲下去，使做事者更有动力做下去。\u003c/p>\u003cp>\u003cstrong>【失败案例】\u003c/strong>\u003c/p>\u003cp> 说到此，我说一个自已的事例，由于工作的原因，一年365天，我300多天都在江苏工作，很少回到浙江总部上班，即使偶尔回去，也只是停留2-3天，每次推开我的办公室，我的办公桌椅都是干干净净的，我跟同事小张说，我回来自已打扫也一样的，不用每次这么麻烦。我同事小张说每天给我打扫也只是顺手的事情，虽然他说得轻描淡写，但是长期坚持下来，也是很不容易的，拥有这样的一个同事，我内心感激，但我每次话到嘴边，吐出来只有两个字“谢谢”。\u003c/p>\u003cp>这种礼貌性的“谢谢”难免会让人觉得“我这样做是不是有点多此一举”，或者“我这样做，是不是有点讨好你的感觉”，从而产生不必要的误解，好的同事关系有时侯容易产生疏远。\u003c/p>\u003cp>\u003cstrong>【怎么做】\u003c/strong>\u003c/p>\u003cp>说到这，让我们先回到拆页1，看看拆页1是如何教我们运用有效的积极性反馈呢？\u003c/p>\u003cp>有效的积极性反馈主要包含3点，简称：“积极性反馈三步法”。\u003c/p>\u003cp>第一、讲行为：\u003c/p>\u003cp>(1) 不带任何主观地评价与判断，只讲观察到的行为与事实； \u003c/p>\u003cp>(2) 要客观、具体描述行为与事实本身。\u003c/p>\u003cp>第二、说影响：\u003c/p>\u003cp>（1）说出行为和事实将会带来什么样的积极影响，并针对相应影响给予肯定的评价。\u003c/p>\u003cp>（2）评价不仅要说个人的，也要说给团队或者社会带来的积极影响。\u003c/p>\u003cp>第三、谈感谢：\u003c/p>\u003cp>（1）指出上述行为与事实给自已带来的美好感受； \u003c/p>\u003cp>（2）针对上述行为与事实表达自已的欣赏与感激。 \u003c/p>\u003cp>\u003cstrong>【加工成正面案例】\u003c/strong>\u003c/p>\u003cp> 若一切可以重来，运用今天学习的积极性反馈，关于同事帮我打扫办公室一事，我可以这样做：\u003c/p>\u003cp>第一、讲行为：小张，从年头数到年尾，我回公司的次数，全年不到10次，每次回来，我都看到我的办公桌椅都是干干净净的，我听其他同事说，你每天上班的时候，也都会帮我把办公桌椅打扫一下，仿佛我每天都会来公司一样。\u003c/p>\u003cp>第二、说影响：你这样的工作方式，勤快而又热心，不仅让你快速融入了我们这个团队，结交了更多的同事与朋友，而且也让整个部门，甚至整个公司形成了一个“人人为我、我为人人”的良好氛围，我也从中感受到了你的真诚、努力与责任心。\u003c/p>\u003cp>第三、谈感谢：你热于助人而不斤斤计较，令我非常欣赏，能够和你共事，我感到很高兴，很幸福，非常感谢你为我所做的点点滴滴。我相信，在公司未来的发展中，你会像金子一样闪闪发光，熠熠生辉，谢谢你小张。\u003c/p>\u003cp>\u003cstrong>【预防性讲解】\u003c/strong>\u003c/p>\u003cp>有些学员可能会说，如果员工表现得好，我们直接说声“谢谢”或者说声“你做得不错”等类似的话，这样不就够了吗？还要说那么多吗？我们通常的做法也许是这样的，但这样的表达，更像是礼貌性的，淡如水的君子谢意，往往难以给对方留下深刻的印像，对方很难感受到你的真诚，对方没有获得更好的内在体验，就无法更好地强化其行为意愿，不利于对方继续保持良好的行为。\u003c/p>\u003cp> \u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>以上积极性反馈，不仅仅适用于我们刚刚讲解的工作场景，在家庭生活，亲子教育以及成人教育等方面，如长辈对晚辈，父母对子女，老师对学生，只要对方做出了对的行为，需要给出正向反馈时，我们就可以使用，当然，如果对方做事的方式有偏差，或者态度不端正，有待改善的时候，就不适合了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验（显像提问发表）】\u003c/strong>\u003c/p>\u003cp>分享到这里，大家回想一下，过去的1个月内有没有遇到过这样的情景：\u003c/p>\u003cp>比如：当你在酒店吃饭，结帐的时候，服务员告诉你“隔壁包箱的朋友帮你买过单了”，而你来到朋友面前只知道说“使不得，使不得，怎么能让你付钱呢？”却不知如何表示感谢？\u003c/p>\u003cp>当你回到家里，发现自家的孩子帮家里乱七八糟的书房打扫得干干净净，收拾的有条有理，而你却认为孩子在家没什么事，就应该帮大人做点事情，却不知为孩子一下午的付出表达真诚的谢意与肯定？\u003c/p>\u003cp>现在给大家1分钟时间，一起来回想一下。可以把你们想到的场景内容写在便签纸上，然后小组内分享。\u003c/p>\u003cp>稍后我会邀请一位小伙伴现场分享。这里需要提醒大家注意的是：\u003c/p>\u003cp>只讲当时发生了什么就可以，不需要说其它的。\u003c/p>\u003cp>经过1分钟的小组讨论，学习者分享案例。\u003c/p>\u003cp>其中，樊老师分享的案例如下：\u003c/p>\u003cp>昨天晚上，樊老师盘点各门店房屋交易业绩情况，其中一个店长一个月做了6万元中介费，而新来的两个店员，每人各做了6000多元中介费，店长看到这个业绩，没有表扬新来的员工，反而批评说：“你们怎么只能做6000多元业绩？”但在行业中，新人刚来一个月，就能做到6000元业绩属于非常优秀了。\u003c/p>\u003cp>另外宋老师，分享自已的案例如下：\u003c/p>\u003cp>宋老师说，前不久，公司有一个同事因为生了二宝给大家发了喜糖，喜糖不仅包装精美，而且里面有很多好吃的，当他把喜糖发给我的时候，我当时只说了声“谢谢”，其它什么也没有说，今天学了积极性反馈，感觉当时那种表达，过于简单了。\u003c/p>\u003cp>\u003cstrong>【A1+反思加工经验】\u003c/strong>\u003c/p>\u003cp>感谢樊老师与宋老师的精彩分享，若一切可以再来，让我们再一次面对这样的类似情况，运用我们今天所学的方法，我们又会怎么做呢？\u003c/p>\u003cp>这里我继续给大家3分钟时间，大家可以根据运用积极性反馈来表达你们的感激之情，3分钟后，我将请一个小伙伴来分享。\u003c/p>\u003cp>3分钟后，其中李老师分享自已的做法如下：\u003c/p>\u003cp>首先李老师跟我们简单介绍了事情的来龙去脉，说是她的女儿数学考试考了100分，之前因为各种粗心，都没有考过100分，那天特别高兴，兴致勃勃地打电话跟她讲，当时她只是淡淡地说了一句，“不错。”然后她孩子很失望，说：“妈妈，你怎么一点也不开心，这种事也不能让你开心？”，其实李老师说她心里其实是很开心的，但是就是没有表达出来。\u003c/p>\u003cp>通过今天的学习，李老师运用今天的积极性反馈三步法，她会这样说：\u003c/p>\u003cp>第一、讲行为：最近发现你学习比以前更加细心、努力、作业错得也很少，这是你这个阶段非常大的一个学习进步； \u003c/p>\u003cp>第二、说影响：只要努力就会有收获，只要细心就不会出错，你能考出好的成绩，妈妈非常开心：“你终于凭着自已的努力与细心考到100分了。”\u003c/p>\u003cp>第三、谈感谢：今天的100分，证明你是一个有能力的孩子，你再也不用认为：哪一个同学比你好，哪一个同学比你优秀，只要你努力，你一样可以做到。你要继续保持下去，妈妈，相信你，谢谢你今天给妈妈的惊喜，这是妈妈今天收到的最好的礼物。\u003c/p>\u003cp>让我们再次用热烈的掌声感谢李老师的精彩分享，李老师给我们分享的是亲子关系，当孩子成绩好，跟妈妈分享喜悦的事情，如果我们下次遇到类似的情况，就可以使用我们今天所学的积极性反馈，效果肯定会很好，所以希望大家再接再励。\u003c/p>\u003cp>现在让我们回顾一下，我们今晚所学的第一个拆页。有效的积极性反馈主要包括：\u003c/p>\u003cp>第一、讲行为：客观、具体地讲述行为与事实本身。\u003c/p>\u003cp>第二、说影响：说出他人的行为和事实给自已带来的良好影响，并给予他人肯定的评价。\u003c/p>\u003cp>第三、谈感谢：针对他人的付出与努力，表达我们自已真诚的欣赏与感谢。\u003c/p>\u003cp>\u003cstrong>以上就是我第一个拆页的分享，当别人表现好的时候，我们要用积极性反馈，锦上添花；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果对方表现不好的时候怎么办呢，那我们就用今天的第二个拆页（建设性反馈），雪中送碳。我们先来看看第二拆页的学习目标是什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆页2（建设性反馈）的学习目标是当遇到他人的行为错误导致结果不好的时候，学习者能使用建设性反馈，给予他人帮助，指导和修正错误行为。\u003c/strong>\u003c/p>\u003cp>现在给大家2分钟，阅读我刚才分发给大家的拆页2，读完的伙伴请举手示意一下。 \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":17911,"quote":"\u003cp>拆页2：建设性反馈技术——AID （来源于俞清 金慧英《教练型管理者》P120-P121）\u003c/p>\u003cp>有 效 的 建 设 性 反 馈 由 3 个 要 素 构 成 ： \u003c/p>\u003cp>一 是描述行为和事实（Act）；\u003c/p>\u003cp>二 是阐述影响及后果（Impact）；\u003c/p>\u003cp>三 是指明期待的行为和结果（Desired outcome）。\u003c/p>\u003cp>这3个要素缺一不可，我们简称为AID反馈技术，如图5-3所示\u003c/p>\u003cp>建设性反馈的流程首先是描述行为和事实，然后阐述这些行为带来的影响及后果，最后指明期待的行为和结果。建设性反馈的注意要点如下。 \u003c/p>\u003cp>首先，行为和事实的描述应具体、客观和真实。我们在反馈时不仅需要顾及行为的结果，更要关注行为过程本身，因为过程会产生必然的结果。我们在描述行为时一定要注意观察，我们要观察人的具体行为，而不是对人本身进行评判。 \u003c/p>\u003cp>其次，我们在阐述影响及后果的时候，不仅要描述这些行为对集体和团队的影响及后果，更要描述这些行为对下属的影响及后果。这与人性的某个特点相关。\u003c/p>\u003cp>假设你因为迟到了并错过一个非常重要的销售电话，从而使公司错过了一笔大单。这时，经理A是这样对你反馈的：“李主管，因为你今早晚进公司1个小时，客户打了5个电话都没有找到你本人，所以决定与竞争对手合作了。这给我们公司带来了重大的损失。”经理B是这样对你反馈的：“李主管，因为你今早晚进公司1个小时，客户打了5个电话都没有找到你本人，所以决定与竞争对手合作了。这不仅给我们公司带来了重大的损失，也影响了你个人的绩效，明明到手的两万元的销售提成没有了。”哪一个反馈对你更有触动？答案肯定是后者，因为跟自己的利益直接相关。因此，在阐述影响及后果的时候，更要描述对下属的影响及后果，这样才能真正引起对方重视。 \u003c/p>\u003cp>最后，期待的行为和结果也同样必须具体、明确和可行，并且需要正向表达。所表达的期待是下属今后需要修正的行为，所以为了下属正确落实行动，期待的行为和结果必须足够具体、明确和可行。我们经常会碰到在下属完成了某项工作之后，结果却跟管理者的预期有很大的差距。当管理者向他提出困惑时，对方的回答大部分是：“噢，我不知道你有那样的要求。”很多员工的绩效结果与管理者的预期有差距，这与工作要求不明确直接相关。\u003c/p>","explains":"\u003cp>\u003cstrong>【是什么】\u003c/strong>\u003c/p>\u003cp>好，我看到大家都读完了，拆页2分享了一个什么内容呢？我们在日常生活工作中碰到对方的行为不对时，通过使用“讲行为、说利益、谈要求”等有效的建设性反馈，给予他人指导和期望，帮助他人改善错误的行为。 \u003c/p>\u003cp>\u003cstrong>【为什么】\u003c/strong>\u003c/p>\u003cp> 当我们发现别人的行为不对时，比如有人在生产车间吸烟，我们一般情况下会怎么做呢？\u003c/p>\u003cp>我们通常的做法是说这个地方不准吸烟，却没有提到错误行为对行为者本身有什么直接影响，如果我们不用建设性反馈，做错事情的人没有意识到自已的利益会受损，没有直击他的痛点，做事就没有改善的动机，如果我们使用建设性反馈，做错事情的人会意识自已的利益损失很大，错误行为因为有效反馈就容易得到改正。比如我们告诉吸烟者一旦被抓到，不仅会罚款500元，而且会被开除工作，如果吸烟引起火灾，还会追究刑事责任，自然就容易杜绝吸烟事件发生。\u003c/p>\u003cp>\u003cstrong>【怎么做】\u003c/strong>\u003c/p>\u003cp> 现在，让我们先回到拆页2，看看拆页2是如何进行有效的建设性反馈呢？主要也分成3点，简称为：“建设性反馈三步法”。\u003c/p>\u003cp>第一、讲行为：\u003c/p>\u003cp>（1）不带任何主观地评价与判断，讲述行为和事实要具体、客观和真实； \u003c/p>\u003cp>（2）重点讲述行为和事实产生的过程与结果。\u003c/p>\u003cp>第二、说利益：\u003c/p>\u003cp>（1）说出这些行为对集体和团队带来的负面影响及后果\u003c/p>\u003cp>（2）重点描述这些行为对本人带来的直接利益损失及后果。\u003c/p>\u003cp>第三、谈要求：\u003c/p>\u003cp>（1）要正向表达需要改正的行为和结果； \u003c/p>\u003cp>（2）要求改正的行为和结果要具体、明确和可行。\u003c/p>\u003cp> \u003cstrong>【意译原书案例】\u003c/strong>\u003c/p>\u003cp>拆页中的原文案例是公司领导关于下属迟到的建设性反馈案例，让我们运用一下，看看其它的工作场景，是不是也可以运用？\u003c/p>\u003cp>比如：卖房子，前不久，我去看望我的宁波朋友小李，正好碰到他因为一个叫张大哥的男人穿着很土，说话外地口音重，模糊不清，从而他就让新来的同事小林去接待他，没想到这位张大哥当天下午就一次性买了3套房。\u003c/p>\u003cp>这时，其中一个售房部王经理找到我的朋友说：“小李，你是第一个接待这个客人，但是你认为对方不会买，所以你把这个客户给了小林，没想到小林，因为你这个客户直接买了3套房，刚来一个星期，人事部就接到通知，直接让他转正了。”\u003c/p>\u003cp>王经理刚走没一会儿，孙经理也找到我的朋友说：“小李，你是第一个接待张大哥的，没想到张大哥直接买了3套房，足足花了600万元，你虽然没有说对方什么，但是你不愿意热情接待对方，你不仅给张大哥留下了不好的印像，也给公司带来了不好的影响，更重要的是，明明属于你的6万块提成，没了。”\u003c/p>\u003cp>以上哪一个反馈对我朋友触动更大呢？\u003c/p>\u003cp>答案肯定是后者，我陪他大醉了一场，也哭诉了一场，喝醉的时候他嘴里还念念有词地说：“那可是6万块啊.......”，心情非常的糟糕。\u003c/p>\u003cp>\u003cstrong>【预防性讲解】\u003c/strong>\u003c/p>\u003cp> 有人会说，使用建设性反馈，一讲行为、二说利益、三谈要求，如果我们先谈对对方的要求，再讲行为、再讲利益，不是一样可以达到同样的效果吗？如果这样说，似乎很合情合理，当你向对方提要求的时候，对方可能本能地就会抗拒，认为你在找茬，或者对方已经在为损失而难过的时候，你一开口说要求，对方可能就会认为你不近人情，根本听不进去，反而事与愿违，引起不必要的误解。而先说行为，再说利益、再说要求，一步一步地叙述事情的前因后果，客观而又具体，容易让对方逐步接受是自已不良的行为导致了自已利益受损，也给公司带来负面的影响，而主管对自已提些改善的要求，这种反馈的方式也就容易让人接受、从而主动改正不良的行为。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>所以，使用建设性反馈，不论是对工作还是对家庭，不管是我们成人学习还是育儿育女，如果对方的行为有偏差，态度偏激，问题并不严重的时候，你想指正对方，希望对方改正，就可以使用建设性反馈，如果对方问题很严重，或者对方表现很优秀，这两种极端的表现，那么建设性反馈就不适合使用。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3：场景演练】\u003c/strong>\u003c/p>\u003cp>我们刚刚学习了建设性反馈。现在一起做一个演练，请大家认真听一下要演练的场景：\u003c/p>\u003cp>销售部王经理同销售员小李一起去客户那里进行项目介绍，当王经理与小李来到客户会议室，打开电脑，准备进行项目介绍时，王经理发现让小李拷贝的项目资料是最初的版本，客户不满意，直接跟另外一家公司签约了。\u003c/p>\u003cp>如果我们来到这个场景，运用刚才所学的建设性反馈，王经理应该如何跟小李说呢？\u003c/p>\u003cp>现在我们按照刚开始的分组，在组内进行讨论和角色扮演，一个人扮演王经理，另一个人来扮演小李，组内演练的时间为5分钟，稍后我会邀请一组伙伴来表演一下，大家在讨论的时候可以参考我刚刚发给大家的这个表格。\u003c/p>\u003cp>好，5分钟到，哪组伙伴愿意来扮演一下如何使用建设性反馈呢？\u003c/p>\u003cp>其中樊老师、丁老师两位老师举手示意，小组分享如下：\u003c/p>\u003cp>丁老师扮演王经理、樊老师扮演小李，两人演练如下：\u003c/p>\u003cp>第一、讲行为：\u003c/p>\u003cp>丁老师（王经理）对樊老师（小李）说：“小李，你看看你今天这个事情，居然连版本都搞错了。我们在客户那里打开，我看客户的脸色都变了，认为我们根本不把他的事情放在心上，现场搞得大家都很尴尬，对吧？”\u003c/p>\u003cp>樊老师（小李）点头回应说：“是的，王经理。”\u003c/p>\u003cp>第二、说利益：\u003c/p>\u003cp> 丁老师（王经理）对樊老师（小李）接着说：“小李，在这个问题上显示我们太不严谨，给客户的还是最初的老版本材料，这样一来，客户我们肯定丢掉了，对吧？他也跟别人签了，客户对我们公司留下了一个不好印象。下次我们想再去谈合作，就难上加难了。这样的话，这个月你的奖金基本上就不用考虑了。”\u003c/p>\u003cp>樊老师（小李）默默地低下了头，心情很是沉重。\u003c/p>\u003cp>第三、谈要求：\u003c/p>\u003cp>丁老师（王经理）接着补充道：“作为你的领导，我也尽量地挽回损失，今天这个事情，主要是给我们上了一课，以后再去客户那里的时候，我们需要给客户展现的材料要反复确认，自已要亲自检查一遍，确保无误之后才行，今天这样的事情，再也不能发生。”\u003c/p>\u003cp>樊老师（小李）连忙点头回应：“好，下次一定注意。”。\u003c/p>\u003cp>\u003cstrong>【点评与总结】\u003c/strong>\u003c/p>\u003cp>让我们用热烈的掌声来谢谢丁老师、樊老师的精彩演练，也让我们进一步了解到了建设性反馈过程当中，我们要遵循三个步骤：\u003c/p>\u003cp>一是要讲行为，说这件事情的行为对公司带来的影响，客户丢了；\u003c/p>\u003cp>二是要说利益，利益主要是讲小李你这个月奖金没有了，直击了小李的痛点； \u003c/p>\u003cp>三是要谈要求，要求就是正向表达，希望小李下次给客户展现材料之前要反复确认，自已亲自再检查一遍，杜绝类似的事情再发生。\u003c/p>\u003cp>\u003cstrong>【A2：分步催化应用-1】\u003c/strong>\u003c/p>\u003cp>分享到这里，接下来，在座的各位伙伴们，对建设性反馈有所了解了，在接下来的工作中，你可能会碰到需要运用建设性反馈的场景\u003c/p>\u003cp>为了推行标准化作业管理，公司发布通知，要求员工下周开始每天填写工作日志，有些员工说自已文化水平低，不想写，还有些说我们这些做操作工的，每天加班都忙死了，哪有时间写这个？你没有遇到过这样的情景呢？\u003c/p>\u003cp>又比如公司统一订制了工作服，要求明天上班时统一着装工作服，销售部员工说我们大部分时间会出去跑客户，穿工作服去会不会不适合啊？等等 。\u003c/p>\u003cp>在此给大家2分钟时间，大家可以把想到的场景内容写在便签纸上,要求场景内容包含时间、地点、人物、事件等各要素，稍后我会邀请一位小伙伴现场分享，这里需要提醒大家注意的是：\u003c/p>\u003cp>只讲你设想的那个场景就好，不需要具体说会怎样去做。\u003c/p>\u003cp>好，2分钟到，哪位伙伴愿意用1分钟时间来分享一下自已想到的场景呢？\u003c/p>\u003cp>其中邀请宋老师分享场景如下：\u003c/p>\u003cp>宋老师说她们公司来了一个小伙伴，经常在办公室给家里打电话，每次打电话时间长，一天打好几次，很频繁，而且是当着办公室的同事面打，影响特别不好。\u003c/p>\u003cp>\u003cstrong>【A2：分步催化应用-2】\u003c/strong>\u003c/p>\u003cp>非常好的案例，非常感谢宋老师的分享，那我们现在就运用建设性反馈，对类似于宋老师讲的场景，或者每组自已挑选一个场景加工一下，运用今天所学的建设性反馈三步法，现在我继续给大家5分钟时间，在小组内分享讨论一下，看看如何运用今天学习的“讲行为、说利益、谈要求”建设性反馈？5分钟后，我将再次邀请1位伙伴来分享。\u003c/p>\u003cp>好，时间到，哪位伙伴愿意用1分钟时间来分享一下自已的运用呢？\u003c/p>\u003cp>其中宋老师与丁老师演练了起来，丁老师演的是公司的小伙，由于我们目前进行的是A2（分步催化应用），不是A3场景演练环节，于是，我就再次邀请宋老师，针对现在的学习技能点（A2：分步催化应用-2），进行了个人分享如下：\u003c/p>\u003cp>第一、讲行为：宋老师对其同事说，每天你在办公室里打电话，时间长，还比较频繁，我们听得也很清楚； \u003c/p>\u003cp>第二、说利益：你这样打电话，不仅影响其它同事工作，还会泄露你自已的隐私，同时领导知道了，对你年底加薪评级也不好，到时工资涨不上去或者年底奖金发得少，对你而言，这多亏啊。\u003c/p>\u003cp>第三、谈要求：如果家里有急事，打个电话沟通一下，公司也是认可的，但是打电话的时候，如果感觉时间会比较长，就可以去我们隔壁的会议室打，如果是不重要的事情，可以长话短说，声音小一点，或者让对方微信留言，就不要在上班时间聊。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>分享到这里，宋老师讲完了，我们一起鼓掌，宋老师跟我们分享的这个建设性反馈，是关于员工利用上班时间经常性打私人电话，对自已对同事对公司都造成了一些不好的影响，宋老师经过使用建设性反馈让其同事认识到这样的不良影响，从而减少办公室打电话，不然会影响个人的加薪与奖金发放。这是一个非常适用的案例。\u003c/p>\u003cp>说到这里，今天的两个拆页就学习结束了，在此，让我们先回顾一下今天学习的内容，第一我们学习的是积极性反馈，第二我们学习的是建设性反馈。\u003c/p>\u003cp>积极性反馈主要当遇到他人做得好的时候，我们就用它肯定他人的行为，增强他人的信心和动力；\u003c/p>\u003cp>建设性反馈是当我们遇到他人做得不好的时侯，我们就用它来给予他人指导和期望，改善他人的行为。\u003c/p>\u003cp>两个方法，交替使用，不仅可以促进人与人之间的友好关系，还可以提升大家的实际管理能力。\u003c/p>\u003cp>“赠人玫瑰，手有余香”。最后祝愿大家不仅成为一名好的管理者，而且成为一名优秀的教练。\u003c/p>\u003cp>谢谢大家，我今天的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1659676061000,"updated_at":1659750673000,"ria":true},{"id":13652,"topic":"这样倾听，让人觉得你好懂","learn_goal":"","remark":"学习者能结合“深度倾听三步法”写下故事并找到对方话语背后的真实需求","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"Frank Hung","city":""},"club":{"name":"台北悦读不卡分舵","city":"台北"},"prologue":"\u003ch1>【自我介紹】\u003c/h1>\u003cp>大家好，我是来自台湾台北的洪麒富，目前在华利集团任职鞋类模具业务主任，我的三个标签是：1. 图卡知识设计 2. 英文/越文交流 3. 简报培训 \u003c/p>\u003ch1>【场景介绍法】\u003c/h1>\u003cul>\u003cli>【事件】：（给出贴近学习者的生活经验，有画面）\u003c/li>\u003c/ul>\u003cp>请大家试想一下，当自己想要鼓励身处情绪低落的朋友时，想要安慰对方却又找不到方法，“别想太多”这样安慰的话语反而使对方更加低落。\u003c/p>\u003cul>\u003cli>【提问】:(提问以引发学习者的思考，有思考）\u003c/li>\u003c/ul>\u003cp>想问问小伙伴们有没有曾经朋友情绪低落找你倾诉，可是愈安慰反而让他愈难过呢？\u003c/p>\u003cul>\u003cli>【影响】:(举出糟糕的后果，有痛点）\u003c/li>\u003c/ul>\u003cp>在实际生活上， 如果我们没有方法地去帮助到情绪低落的对方， 除了可能让对方更加难过外，最后自己也会卷进负面情绪的漩涡里。\u003c/p>\u003cul>\u003cli>【解決】:(本书提出的方法能解决以上痛点，有方法）\u003c/li>\u003c/ul>\u003cp>若我们看完《教练型管理者》这本书后，使用书里的“深度倾听” 、“有力提问”、“有效反馈”的赋能技术，可以帮助对方走出情绪低落的状态。\u003c/p>\u003cp>而今天要学习的片段就取自三个赋能技术中的“深度倾听”，通过找到对方的话语背后的真实需求，让人觉得你好懂他。\u003c/p>\u003ch1>【学习目标】\u003c/h1>\u003cp>当今天完成此片段内容后，学习者能：\u003c/p>\u003cp>结合“深度倾听三步法”写下故事剧本并找到对方话语背后的真实需求。\u003c/p>","ratings_count":4,"texts":[{"id":17688,"quote":"\u003cp>【R阅读原书拆页】\u003c/p>\u003cp>[主题]：深度倾听\u003c/p>\u003cp>[片段来源]：《教练型管理者》电子书 P.79\u003c/p>\u003cp>浅层倾听是以回应为目的的倾听。这时倾听者的注意力都在自己身上，即以自我为中心的听。在这种状态下，人们很难把对方的话听进心里，因为比起了解对方的感受和需求，他们更在意的是自己该如何回复对方。\u003c/p>\u003cp>深度倾听是以理解和接纳为目的的倾听。我倾听你是为了更好地理解你、接纳你。在这种状态下，我们就会把注意力放在对方身上，放下自己关于这个情境的所有偏好、评判、看法和建议，以对方为中心，一心一意地体会他人。\u003c/p>","explains":"\u003cp>【分享I便签】 \u003c/p>\u003cp>【What】\u003c/p>\u003cp>大家看完拆页后，原文指出两种不同的倾听，一个是浅层倾听，一个是深度倾听，浅层倾听是以自我为中心的倾听，我们听不到对方真实需求是什么，因为我们在意的是如何回答对方的话语，而深层倾听以对方为中心的倾听，让我们倾听到对方话语背后的真实需求。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>为什么建议使用深度倾听呢？因为深度倾听才能通过对方感受去了解话语背后的需求，只有知道了对方的需求后，才能根据需求来给到适合的反馈，才不会对方想要喝水，而自己硬要塞给对方果汁。\u003c/p>\u003cp>【对比概念，案例折返引出逻辑、步骤】\u003c/p>\u003cp>浅层倾听和深度倾听的差別于是否听到对方的“感受“，下面我举个例子，让大家更了解其中的差别：\u003c/p>\u003cp>1. 朋友最近工作不顺，觉得上级老是针对他，总丢给他很多不属于他的工作，我听完回他说做愈多工作是增加自己的能力啊，能者多劳嘛！ 大家觉得我这是深度倾听还是浅层倾听？\u003c/p>\u003cp>学习者：是浅层倾听\u003c/p>\u003cp>拆书家：很明显这是浅层倾听，朋友都在为工作量大而苦恼了，结果我还说要再多做一点，这就是只根据对方话语来回应的方式，给直接建议而不是倾听对方感受，既没安慰到别人，还让别人更不开心。深层倾听要做到接纳，先安静地听完对方想说的话，单单在那里专注地听朋友说话，其实就起到很大的安慰作用。\u003c/p>\u003cp>2. 你的另一半抱怨你工作太忙都没有时间陪她，觉得很不开心，开始说出你不爱她的气话时，你觉得很受伤，你回说我工作量大又不是我愿意的，我也是千百个不愿意。大家觉得这是深度倾听还是浅层倾听？\u003c/p>\u003cp>学习者：是浅层倾听\u003c/p>\u003cp>拆书家：很明显还是浅层倾听，虽然不是给建议，而是表明自己不得不的状态，但这样的回复并不会让对方感到比较舒服，反而让对方觉得你暗中责怪她不懂事，加深不舒服的感受。\u003c/p>\u003cp>3. (接例2）如果我倾听完对方的话后，点头回应说：“嗯嗯，最近陪伴你的时间确实少了，听起来，你不开心是希望我能更关注你，对吗？”大家觉得这是深度倾听还是浅层倾听？\u003c/p>\u003cp>学习者：是深度倾听\u003c/p>\u003cp>拆书家： 这是深度倾听，首先肯定了对方不开心的原因，也等于肯定了对方的感受，接着尋找向對方不開心的背後需求是什麼，接着向对方试探性地说出自己总结出的不开心的深层需求，确认是否和对方内心的想法是一致的，即使不是对方的需求，也能再继续进行询问下去。\u003c/p>\u003cp>大家都非常棒，准确地理解深度倾听和浅层倾听的回复是怎么样的。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>根据刚才的例子讲解，我们可以总结出深度倾听需要三个步骤：\u003c/p>\u003cp>1. 接纳：先只听不說，好好关注对方的感受和情绪\u003c/p>\u003cp>2. 回应：使用肢体和语言回应说话者，让对方觉得你想继续听\u003c/p>\u003cp>a. 肢体回应：适时点头、自然微笑、目光关注\u003c/p>\u003cp>b. 语言回应：重述对方话语的关键词创造共鸣并根据对方的关键词挖掘对方的需求\u003c/p>\u003cp>3. 求证：通过正向表述的语言向对方确认听到的感受和需求是否和对方内心的想法一致，可以使用“听起来，妳觉得…是吗？”的句式来向对方求证\u003c/p>\u003cp>为了让大家好记忆，大家可以用我的口诀叫“接回球“来记忆这个知识点，让我们继续在上述的例子2中运用“深度倾听三步法”来倾听你的另一半：\u003c/p>\u003cp>1. 接纳：当另一半说你因为工作忙而让她感觉到不爱她时，此时不要急着回话或生气，先安静地关注她的感受和情绪。\u003c/p>\u003cp>2. 回应：适时点头正面肯定另一半的情绪，并通过重述对方的关键词创造共鸣，让对方感受我们正认真倾听，同時內心去想是什麼讓對方產生這樣的感受，例如：嗯嗯，没有陪到你。（内心此时想着没有陪到对方会给对方带来什么需求没被满足）\u003c/p>\u003cp>3. 求证：用正向的语言表述向对方确认感受及需求，例如：听起来，你不开心是希望我能更关注你，对吗？\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>大家一定会想「深度倾听」太困难了，別人说的話自己听起來就不是事实还要耐着性子听完，实在是违反人性，但若不作深度倾听，便无法理解对方的感受和需求，继而让人不想继续对话下去。\u003c/p>\u003cp>【Where】(适用场景)\u003c/p>\u003cp>适用在交流感觉的场景\u003c/p>\u003cp>不适用在需紧急处理突发状况的场景\u003c/p>","interaction":"\u003cp>【A2】未来故事\u003c/p>\u003cp>接下来请大家用5分钟设想一下未来一周在和別人的溝通，可能會遇到哪些情境能用到“深度倾听三步法”呢？\u003c/p>\u003cp>请小伙伴们来编写一个故事，记得故事里要有主题、人物、情景变化（包括起因、经过、结果）且是有对话的剧本，待会我会请一人来分享。\u003c/p>\u003cp>我准备了表格给大家参考，大家可以根据这个表格写下自己的小剧本\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>【回应反馈】\u003c/p>\u003cp>谢谢道翔的分享，非常非常棒，也和大家很好地示范如何使用深度倾听三步法\u003cbr>\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>感谢今天各位小伙伴的陪伴，希望大家都能使用深度倾听去接纳对话者的感受和情绪，不只是听表面的话语，而是听到话语下的深层需求，祝福大家在生活或是职场中都能这样倾听对方，让人觉得你好懂。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1656299370000,"updated_at":1658834871000,"ria":true},{"id":13474,"topic":"赞美时说出具体的行为和事实（既对人也对事），批评时做到对事不对人","learn_goal":"","remark":"优质的赞美，就像每天吃饭一样，大胆积极的给身边的人进行技术赞美，你会发现你会越来越爱自己。\n高效的批评，就像自我修炼一样，不仅要修出自己的内心，还要修出他人对你的态度，过程中需要用心修炼，当你看到他人更多优点时，你的资源会越来越宽广。","level":"TF3-3","duration":70,"status":30,"type":0,"chaishujia":{"username":"驰驰","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>各位伙伴们，大家好，我是王驰驰，欢迎大家来到我的TF3-3拆书现场。用3个标签介绍下我自己：传媒策划师、非遗传承人、常州龙城分舵组织长老。\u003c/p>\u003cp> \u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>为了方便学习，这里我们先做一下分组，从我的左手边开始两两一组，最后则为三人一组。\u003c/p>\u003cp>总的学习目标:\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，在赞美他人的时候，学习者能正确运用积极性反馈技术针对对方的具体行为予以表扬，从而让对方流露出会心的笑容。\u003c/p>\u003cp>同时在批评他人时，学习者能够运用建设性反馈技术三步法，让对方正确认识到自己的错误，做到对事不对人，从而让对方改正错误。\u003c/p>\u003cp>【事件场景】：记得第一次来到拆书帮的线下活动，18年12月24号，当时马文丽老师在分享2-1，听完马老师的分享，感觉太厉害了，无论是现在的感染力还是分享的内容都是非常赞，作为一名新人，主持人当时就邀请我 第一个给马老师反馈，我说马老师分享的这个内容真是太棒了，逻辑性强，现场幽默，风趣，全程都没有尿点，我要是有你这水平那该多好啊。。。当时马老师听了就感觉向恭维的话，不知道的还以为我是专门来拍马屁的呢。尴尬的向我点了下头，表示了感谢。\u003c/p>\u003cp>当时我也感受到了话说的太过，恨不得找个地缝钻进去的感觉。\u003c/p>\u003cp>发现我的反馈是多么的没有力量，从那以后马老师的分享，很少在找我做反馈。\u003c/p>\u003cp>【提问】：你是否也碰到过类似的场景，由于自己积极反馈的方法不当，导致对方理解你的反馈是恭维他呢，还是纯属给他面子呢？\u003c/p>\u003cp>【影响】：很多人觉得积极性反馈就是实话实说，其实成年人的世界里，大家更愿意听到她自己没看见的赞美。有时候赞美不到位，对方会认为你在拍他马屁，长此以往不仅达不到赞美的效果，还会给自己带上恭维和奉承的头衔。\u003c/p>\u003cp>【解决】：今天分享的这本书，是俞清和金慧英老师著作的《教练型管理者》，本书通过大量案例，列举了我们日常工作生活中常用的沟通反馈技巧。\u003c/p>\u003cp>今天我给大家讲解的两个片段，可以帮助我们正确运用积极性反馈和建设性反馈，使你的赞美恰到好处，赢得真心，批评时能更好的做到对事不对人。\u003c/p>\u003cp>学习目标1：在跟随我完成本次RIA现场学习后，在赞美他人的时候，学习者能正确运用积极性反馈技术针对对方的具体行为予以表扬\u003cstrong>，从而让对方流露出会心的笑容。\u003c/strong>\u003c/p>\u003cp>接下来我们拆解第1个片段，请大家花2分钟阅读手中拆页，读完的伙伴举手向我示意一下。\u003c/p>","ratings_count":2,"texts":[{"id":17494,"quote":"\u003cp>那么，我们究竟该如何进行有效的积极性反馈呢？如果此刻让你回想一下你最有印象的一位老师并表扬他，那么你会如何表扬呢？很多人是如此表扬的： \u003c/p>\u003cp>■老师，您的课讲得特别棒！ \u003c/p>\u003cp>■老师，您特别专业！ \u003c/p>\u003cp>■老师，您的课逻辑性特强！ \u003c/p>\u003cp>■老师，您的课幽默、风趣，全程没有尿点！ \u003c/p>\u003cp>■您是我见过的最优秀的老师，没有之一，下次我还要上您的课！\u003c/p>\u003cp>如果你是这位老师，在听到这样的反馈后会有什么样的感受？第一感觉肯定很开心，还挺兴奋的。因为这些话用的都是溢美之词，你听到后当然开心。但是，静下来，你不知道他说你“讲得特别棒”， 到底棒在哪里。你也不知道他说你“专业”，到底专业在哪里。你甚至慢慢会感觉到“幽默、风趣”应该是每位讲师的基本素质，感觉“全程没有尿点”有点儿夸张，感觉“下次我还要上您的课”好像是应付。想到这里，你的开心、兴奋会瞬间消失，感觉大家只是在恭维你，给你面子而已。\u003c/p>\u003cp>假设有一位学员给了你这样的一段表扬信 ： \u003c/p>\u003cp>亲爱的老师，您提前40分钟来到我们的培训室。在课程中，为了照顾到我们全场80位学员，您不停地走到每个小组前。从您生动的肢体语言和神态上，我就能够感受到您对教学的投入程度。课间休息时，您却没有休息，还将每组问题逐一归类和分析；课间练习时，您既能引导大家活跃思考，又能及时把握方向防止大家跑偏，还能在交流问题的过程中快速发现问题并给出专业的指导。只有对自己的课程有绝对的信心且对学员抱有很高的期望才能如此专注。您的勤勉和敬业令我由衷感叹！正因为您忘我的付出，我们的课堂氛围才能如此活跃，80位学员才能收获满满的落地的管理实操工具。今日，您的言传身教令我获益良多，不光是知识上的收益，也包括专业度、勤勉和应变的启迪，再次感谢您的付出。\u003c/p>","explains":"\u003cp>好的，大部分伙伴已经看完了，没看完也没有关系，下面我来讲解一下。\u003c/p>\u003cp>在拆页中，通过2种赞美的形式，带给我们不同的感受。\u003c/p>\u003cp>【举例对比概念】\u003c/p>\u003cp>在沟通过程中，我们非常容易混淆积极性反馈和激励，而这两个表达出来的效果完全不一样。所以，我们有必要区分这两个词语。\u003c/p>\u003cp>那什么是积极性反馈呢？积极性反馈，首先要描述行为和事实，在说明影响及评价，最后表达欣赏和感谢。说到对方的心坎里，让对方高兴，从而促进彼此关系。\u003c/p>\u003cp>那什么是激励呢？激励指的就是通过适当的行为和环境激发他的动力，从而让对方自发的朝着我们所期望的目标采取行动。\u003c/p>\u003cp>为了让大家更好的区分“积极性反馈”和“激励”下面我们通过几个例子来详细对比一个。\u003c/p>\u003cp>\u003cstrong>案例一：\u003c/strong>\u003c/p>\u003cp>你晚上到家，发现老公做了一桌子饭菜。这时你对老公说：老公，你真是太棒啦，你怎么这么厉害，希望每天回家都能吃到你做的饭。\u003c/p>\u003cp>【提问】请问各位这里是积极性反馈还是激励。\u003c/p>\u003cp>【学习者】激励\u003c/p>\u003cp>【分析】是的，这个是激励，老婆通过老公做饭的行为，期望老公朝着做饭的目标再接再厉，这里主要讲的是激发老公做饭的动力，所以这个称为激励。\u003c/p>\u003cp>\u003cstrong>案例二：\u003c/strong>\u003c/p>\u003cp>老板给你安排的工作，你超预期完成。这时老板对你说，小王，这次工作做的很好啊，继续再接再励，下月给你发奖金。\u003c/p>\u003cp>【提问】请问各位这里是积极性反馈还是激励。\u003c/p>\u003cp>【学习者】激励\u003c/p>\u003cp>【分析】是的，这个是激励，老板通过加薪的行为，激励小王继续做好工作的一个动力，期望能继续保持好的工作，因此这里是激励。\u003c/p>\u003cp>\u003cstrong>案例三：\u003c/strong>\u003c/p>\u003cp>老板给你安排的工作，你超预期完成。这时老板对你说，小王，这次工作做的很好啊，没想到你这么快就完成了，听其他同事说，你是用3A反馈法做梳理，其他伙伴都要向你学习哦。因为你的超预期完成，也让其他相关工作提升了效率，你这是不可多得的人才啊，本月奖金奖励一千元。\u003c/p>\u003cp>【提问】请问各位这里是积极性反馈还是激励。\u003c/p>\u003cp>【学习者】积极性反馈\u003c/p>\u003cp>【分析】是的，这个是积极性反馈，这里的老板不仅说出了小王做出的具体行为和事实，还说明了影响，最后还进行了欣赏和加薪。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>通过原文片段和案例，我们会发现积极性反馈是有描述行为和事实，并客观的阐述影响并给出评价，最后表达感谢。而激励是通过鼓励调动积极性，要对方按照我们的逻辑去执行。积极性反馈是站在中正的角度具体的分析，而激励只是站在我的角度进行某件行为的鼓舞。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那我们该如何学习积极性反馈呢？我给大家总结了3个步骤\u003c/p>\u003cp>1. \u003cstrong>描述具体的行为和事实。\u003c/strong>说做的好的一些行为一定要描述具体。 事实要描述客观，就是他本身就存在的优势和亮点。\u003c/p>\u003cp>2.\u003cstrong>阐述影响和评价\u003c/strong> 这件事给你带来了积极正面的影响，并说出自己的正面评价，同时描述的影响要扩大化，要找到影响的群体或者团队，描述的影响越大，对方就会越有成就感。\u003c/p>\u003cp>3.\u003cstrong>表示欣赏和感谢\u003c/strong> 这里就是真心，让对方感觉到你是发自内的欣赏和感谢。比如：对人和做事态度的欣赏。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>为了让大家能够更好的理解积极性反馈的3个步骤，当时给马老师做反馈的还有丁老师，当时听完我都惊呆啦。大家还记得我刚刚给马老师的反馈是什么？\u003c/p>\u003cp>我给马老师的反馈是：马老师讲的内容真是太棒了，逻辑性强，现场幽默，风趣，全程都没有尿点，谢谢马老师，我这个里面只说明了（我的欣赏和感谢），\u003cstrong>这里面我没有用到积极性反馈技术三步法，而当时运用丁老师就是用了积极性反馈技术三步法。\u003c/strong>\u003c/p>\u003cp>我们来听一下丁老师的反馈：\u003c/p>\u003cp>\u003cstrong>第一步：描述行为和事实\u003c/strong> 马老师的分享，可以说内容是准备的非常充分，我们人有一份拆页，以及便利贴，方面我们做记录。\u003c/p>\u003cp>\u003cstrong>第二步：影响和评价\u003c/strong> 在分享过程中，通过眼神和互动，照顾到现场的每一位伙伴，让我们的活动现场异常的火爆。\u003c/p>\u003cp>\u003cstrong>第三步：欣赏和感谢\u003c/strong> 为了方便我们记忆，又给我们总结了关键词，体现了对内容的深挖，马老师的分享无论是从专业度还是现场的应变都是值得称赞的，谢谢马老师的分享！\u003c/p>\u003cp>马老师听完反馈，那个开心的笑容持续了好久，就像突然拥有了500万一样。\u003c/p>\u003cp>马老师：谢谢丁老师，对我的肯定和反馈，学习的路上，我会继续努力前行，不辜负厚爱！\u003c/p>\u003cp>这个里面丁老师通过描述马老师现场的具体行为和事实，给大家带来的影响并做出评价，最后表达了欣赏和感谢。可以说全程非常流畅，给你第一感觉就是太会赞美了，是的，就是这样！完整的运用了积极性反馈技术三步法。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>很多人说我只说欣赏和感谢这不也是反馈吗？是的，不过这只是反馈不是积极性反馈，积极性反馈是一定要聚焦具体的行为和事实，通过准确的行为和事实要表示认可，再到影响评价和欣赏感谢。这三步，缺少一个都不属于积极性反馈。\u003c/p>\u003cp>同时，反馈在谈话中起着非常重要的作用，只有反馈合理、积极，双方的关系更加融洽，才会朝着我们期望的方向发展。\u003c/p>\u003cp>如果我们在对方表现有正向行为时，不使用积极反馈技术，就很难调动对方的积极性，正向行为也不会固化，接近目标的时间就会更漫长，完成度也有可能达不到我们期望的目标。\u003c/p>\u003cp>【适用范围】\u003c/p>\u003cp>积极性反馈技术首先使用了对方做出正向行为或产生积极的影响时做出。适用于具有上下级关系或与他人更好的建立关系。\u003c/p>\u003cp>（常见的做法）但是在现实生活中，我们常见的做法是：看似在回应，但对方感觉不到成就感，无法强化正向行为。\u003c/p>\u003cp>积极性反馈法特别适合当对方做出正确行为时进行及时反馈。同时，它的使用有一定的时效要求，最好是当面进行反馈，如果错过了时间再说的话，效果就会大打折扣。\u003c/p>","interaction":"\u003cp>通过以上的分享，想必大家已经学会了积极性反馈三步法，为了加强运用，我们今天尝试编一个故事。\u003c/p>\u003cp>大家想一想，未来一周内，试想一个需要你积极性反馈的场景，你将如何运用积极性反馈三步来让对方感受到你真心的反馈呢？\u003c/p>\u003cp>比如你部门的小伙伴最近业绩做的非常好，你该怎样赞美他，又比如你今天加班到很晚，刚打开家门，看到（老公或老婆)在等着你，桌子上摆满了你爱吃的，那一刻，你满满的幸福。当然不局限这几个场景。想象一下，你们当时的对话场景是怎样的呢？对方当时的内心是怎样的呢？根据我刚刚分享的案例，你将如何运用积极反馈技术三步法？\u003c/p>\u003cp>过程中要有对话，说明清楚事情时间、人物、地点，事情的起因、经过、结果和当时双方的对话/动作等，把它写下来。\u003c/p>\u003cp>最重要的是你如何将今天讲解积极性反馈三步骤（行为和事实），影响和评价，欣赏和赞美）运用到其中。时间5分钟。5分钟后，我们请小伙伴来给我们分享一下，现在开始！\u003c/p>\u003cp>（4分钟时，提醒大家一下）5分钟后，好的，时间到了，那么下面请丁丹伙伴来给我们分享一下？\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>时间：5月28号\u003c/p>\u003cp>地点：家里书桌前\u003c/p>\u003cp>场景：儿子在校期间表现优异，老师父亲给儿子做反馈\u003c/p>\u003cp>父亲：丁老师 儿子:小丁\u003c/p>\u003cp>事件内容：小丁做完考卷，给小丁做积极性反馈\u003c/p>\u003cp>\u003cstrong> 丁老师：小丁，这周你的语数英保持了一定的学习量和练习量，而且你每天除了做考卷，还坚持每天的英语半小时读写训练。（描述行为和事实）\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 你这么坚持下去，也影响着我的学习改变，我感到你已经明白了如何掌控自己人生的方法，努力一定会有回报。（阐述影响及评价）\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 小丁啊，我觉得，我现在越来越欣赏你啦， 这种对自己人生负责的态度。（表示欣赏和感谢）\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 小丁：能到到老爸这样赞美，内心很开心，很激动（儿子这时候会心一笑，表现的很牛叉的样子）。\u003c/strong>\u003c/p>\u003cp>感谢丁老师的精彩分享，让我们把掌声送给我们的丁老师。从丁老师分享的故事里，我看到他很好的运用了我们今天学习的“积极性反馈三步法”，希望大家也能灵活运用到我们生活中，让对方感受到我们真心的赞美，流露出会心的笑容。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":17495,"quote":"\u003cp>\u003cstrong>过渡：\u003c/strong>\u003c/p>\u003cp>上一个片段我们讲解了积极性反馈三步骤，从而让对方感受到我们反馈的真心。反馈的真心能让对方感受到温暖，我们可能感到表扬人不容易。其实批评人更不容易。因为表扬至少不用担心对方会生气，而批评弄不好会和人起争执。有句话我们都知道：“批评要对事不对人。”关键是怎样才能做到“对事不对人”？接下来进入第2个拆页学习。\u003c/p>\u003cp> \u003cstrong> 学习目标2：\u003c/strong>通过第二个片段的学习，学习者能够运用建设性反馈技术三步法，让对方正确认识到自己的错误，做到对事不对人，从而让对方改正错误。\u003c/p>\u003cp>自测题：\u003c/p>\u003cp>那么，请大家先来做个自测题，在开始学习之前，请大家花一分钟时间做一个简单的测试，（看拆页的反面）以下共5个题目，请与自己平时的行为或态度进行对照，然后给自己打分。1分代表完全不符合，6分代表非常符合，请大家仔细阅读表格里的每句话，根据自己的实际情况来给自己打分。打完分以后请大家计算一下自己获得的总分。\u003c/p>\u003cp>\u003cstrong>【I】 自测题解释\u003c/strong>\u003c/p>\u003cp>我看大部分的小伙伴已经做完了测试题，那么接下来：\u003c/p>\u003cp>25-30分的请举手\u003c/p>\u003cp>15-25分的请举手\u003c/p>\u003cp>25-30 说明你的建设性反馈水平达到了5颗星，在工作和生活中，你是一个善于观察的人，做反馈时能做到对事不对人，遇到问题时，能及时做出中正，客观的反馈。你的能理解他人，更多的站在对方的角度思考问题，清晰的指出你的期待和结果。\u003c/p>\u003cp>15-24说明你的建设性反馈水平指数3颗星，建设性反馈的能力稍显欠缺，可能是在观察和问题总结方面需要做一些小小提升，那么你需要一个可执行课落地的建设性反馈公式。今天的学习也许能让你较系统地收获建设性反馈的方法。\u003c/p>\u003cp>15分以下 说明你的建设性反馈水平指数1颗星。那大家也不用着急，今天你将是最有收获的人。\u003c/p>\u003cp>小伙伴们不用和别人比分数，这个表格只是一个辅助工具用以测量自己当下的状态。\u003c/p>\u003cp>当然这个只是当下粗略的自评测试，并不代表权威。\u003c/p>\u003cp>通过这个测试，我相信大家对建设性反馈都有了初浅的认识，接下来请大家阅读拆页二，请大家用2分钟的时间来进行阅读，阅读完请举手向我示意一下。\u003c/p>\u003cp>原文片段：\u003c/p>\u003cp>通过积极性反馈的学习，我们可能感受到表扬人不容易。其实批评人更不容易。因为表扬至少不用担心对方会生气，批评弄不好会和人起争执，所以我们在批评人的时候总会有些担心，担心对方会难以接受。有句话我们都知道：“批评要做到对事不对人。”关键是怎样才能做到“对事不对人”，这个度很难把握。比如，管理者随口所说的一句“一点儿想法都没有”，这是针对人的，是一种人格化批评，直接伤害了对方的自尊和自信，必然会针造成对方的工作绩效下滑。管理者的一句“这样的报告毫无价值”，虽然不是直接针对人本身的批判，但 \u003c/p>\u003cp>还是会让人特别沮丧。 \u003c/p>\u003cp>为此，还有一种称为“三明治”或“汉堡包”式的批评方法，就是先表扬一下对方（最上面一层），接着把“难听”的话说出来（中间一 层），最后赶紧安抚一下情绪（最下面一层）。但如果一直使用这种模式，那么对方以后就不会听前后的内容了，因为他知道你真正想说的就是中间的内容。\u003c/p>\u003cp>还有很多管理者担心自己会“得罪人”，在工作中忍气吞声地做“老好人”，不断地扮演“救火队长”的角色，不仅把自己累得半死，还拿不到应有的工作绩效。著名企业教练约翰·惠特默（John Whitmore）曾说过：“没有正确的信息反馈，改正就不可能恰到好处。”建设性反馈是非常重要的，可以让员工正视自己的工作问题，改善错误的工作方式，以及提升工作效率。\u003c/p>\u003cp>好的，我看到我们各位伙伴已经读完了。\u003c/p>","explains":"\u003cp>【Why+what】\u003c/p>\u003cp>批评是每个人都经常使用的反馈方式，但要做到一个好的批评却很不容易，我们的批评往往都是带着负面情感、都是直接评判对方、都是强调造成的问题。\u003c/p>\u003cp>这样的批评，结果往往都是会这样：\u003c/p>\u003cp>心理情绪的对立：对方会直接产生反感，听不进去你的批评 \u003c/p>\u003cp>我们明白了“建设性反馈”的重要性，那怎样才叫建设性反馈呢？我们来看几个案例！\u003c/p>\u003cp>1. 李主管今天迟到近半小时，错过了一位重要的客户。经理说他没有一点责任心，是积极性反馈吗？\u003c/p>\u003cp>不是，为什么呢？因为经理没有描述行为和事实，如：今天迟到半小时；这就是具体的行为和事实\u003c/p>\u003cp>2. 李主管今天迟到了半小时，并错过了一个非常重要的销售电话，从而使公司错过了一笔大单。这时经理是这样对你说的：李主管，因为你今早晚进公司半小时，客户打了5个电话都没有找到你，所以决定与竞争对手合作了。\u003c/p>\u003cp>这个是积极性反馈吗?\u003c/p>\u003cp>不是 这里是说明具体的行为和事实，不过没有说明这件事带来的影响和后果 比如：影响公司信誉和带来的损失。 所以不是积极性反馈！\u003c/p>\u003cp>3. 李主管，因为你今早晚进公司半小时，客户打了5个电话都没有找到你，所以决定与竞争对手合作了，这件事给公司带来了重大的损失，也影响了你个人的绩效，明明到手的两万元的销售提成0没有啦，加油吧，期待你的好消息。\u003c/p>\u003cp>这个是建设性反馈吗？不是\u003c/p>\u003cp>说明具体的行为和事实，也说明这件事带来的影响和后果，没有说出期待的行为和结果 比如：期待你的好消息，没有体现具体的行为和结果。\u003c/p>\u003cp>4.李主管，因为你今早晚进公司半小时，客户打了5个电话都没有找到你，所以决定与竞争对手合作了，这件事给公司带来了重大的损失，同时也影响了你个人的绩效，明明到手的两万元的销售提成没有啦，我知道你平时不是这样的， 我相信以你的能力，不会再犯迟到这种错误，期待你能挽回自己的声誉和公司的损失。\u003c/p>\u003cp>这个是建设性反馈吗？是的\u003c/p>\u003cp>这里不仅说明了行为和事实，同时把对他自身的影响和后果也清晰的说明，最后又说了期待和结果。\u003c/p>\u003cp>生活中，很多人就像案例中的经理一样，只说明了错的行为和事实，也没有量化影响和后果，最后的期待和结果也就没有。建设性反馈技术三步法，能帮助我们更好的在工作和生活中进行有效的反馈，做到对事不对人，让对方认识到自己的错误。\u003c/p>\u003cp>我们从反馈的概念和要点出发，归纳出建设性反馈的三个步骤：\u003c/p>\u003cp>【How】\u003c/p>\u003cp>建设性反馈技术三步法\u003c/p>\u003cp>\u003cstrong>第一步，描述行为和事实\u003c/strong>。\u003c/p>\u003cp>就是反馈给对方：他做了什么、说了什么。而不是对人的行为做出评判。比如说“遇到问题首先来问领导怎么办而不是自己先思考”的行为描述，而不是“没有思考能力”的评判。而对行为的评判，会让下属觉得你是在针对他个人，产生抵触心理。\u003c/p>\u003cp>\u003cstrong>第二步，阐述影响及后果\u003c/strong>。\u003c/p>\u003cp>就是反馈给对方：他的行为产生了哪些负面影响和不良后果。在这里我们把这一步细化为两个步骤。第一：说明行为和事实对集体或团队的影响及后果。这是你对下属工作行为和方式不满意的主要原因，通过说明对集体或团队的影响及后果，让下属明白他造成的后果。\u003c/p>\u003cp>第二：说明行为和事实对他个人的影响及后果。只有下属认识到行为和事实对他个人产生不利影响的时候，跟他自己的利益相关时，他才更有触动，更加重视，更愿意改正。\u003c/p>\u003cp>\u003cstrong>第三步，给出期待的行为和结果\u003c/strong>。\u003c/p>\u003cp>就是反馈给对方：希望对方接下来去做什么，我们想得到什么样的最终结果。\u003c/p>\u003cp>最后我们来总结一下这三步：\u003c/p>\u003cp>1.不做评判，不讲自己的主观看法及评价，只描述具体的事实。\u003c/p>\u003cp>2.讲出他的行为会对团队的影响以及他自己本人造成什么样的负面影响。\u003c/p>\u003cp>3.正向表达。要明确告诉对方他要做什么，而不是他不要做什么。\u003c/p>\u003cp>举个简单的例子：你的下属（张助理）因为堵车迟到半小时，错过了升职的机会。如果采用积极性反馈技术该怎么说呢？\u003c/p>\u003cp>张助理，因为你今早迟到了半小时，原定提拔你做项目总监的议案暂时取消了，这件事给公司带来了不好的表率，同时也影响了你的仕途，明明到手的总监位置就这样没了。我知道你平常不是这种作风，我也相信你的能力，下季度我们会根据业绩和综合能力继续选拔，我知道以你的能力，可以做到的，期待你能做好表率，把自己失去的夺回来。\u003c/p>\u003cp>我相信通过这个案例，你会更加清晰建设性反馈技术三步法，同时也能帮助我们更好的在工作和生活中进行有效的反馈，做到对事不对人，让对方认识到自己的错误。\u003c/p>\u003cp>【适用边界】建设性反馈不仅可以运用在工作中，也可以应用在生活里。在生活中，我们想正式的跟重要的他人沟通某个问题，希望对方认识到自己的行为对我们造成影响，希望对方改正或改进时，就可以运用建设性反馈技巧。\u003c/p>\u003cp>建设性反馈技巧，通过描述行为和事实避免沟通变成质问，通过说明影响和后果强化改正意愿，通过指明期待的行为和结果避免对方走向另一个我们不期待的结果。当然与所有沟通一样，建设性反馈技巧的前提也是平等的沟通氛围、客观的沟通表达。\u003c/p>","interaction":"\u003cp>【A3微行动】\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>关于“建设性反馈技术”主题的拆页学习，就先分享到这里。接下来，我们将进入微行动学习。分组还是沿用刚才的分组。\u003c/p>\u003cp>\u003cstrong>1、明确需要解决的问题\u003c/strong>\u003c/p>\u003cp>拆书家：通过刚刚的分享，我们学习了建设性反馈技术三步法，分别是1.描述行为和事实 2。阐述影响和后果 3.指明期待和结果。 关于这3点大家都清楚了吧？\u003c/p>\u003cp>学习者：清楚了\u003c/p>\u003cp>拆书家：结合各位的过往，首先请大家说一下在遇到事情做批评反馈不当的经历，然后请大家说一下一次给他人做建设性反馈比较难处理的场景供大家讨论。\u003c/p>\u003cp>学习者交流：。。。\u003c/p>\u003cp>小组内可以互相分享下，最后投票选出一个你们最有兴趣去解决的场景。给大家3分钟的时间。\u003c/p>\u003cp>现在邀请每组被选出问题的持有者（也就是案主）用1分钟时间介绍下自己的问题，并描述场景和困扰。\u003c/p>\u003cp>学习者交流。。。\u003c/p>\u003cp>拆书家：大家觉得建设性反馈技术里面，哪个步骤或者场景最重要？\u003c/p>\u003cp>学习者：描述行为和事实\u003c/p>\u003cp>拆书家：好的，大家觉得行为和事实比较重要对吧？\u003c/p>\u003cp>学习者：是的\u003c/p>\u003cp>拆书家：既然大家选择了这个问题，那么我们花一点时间来共同探讨和解决一下\u003c/p>\u003cp>\u003cstrong>2、分组讨论问题本质\u003c/strong>\u003c/p>\u003cp>拆书家：刚才大家交流的比较充分，有请两个小组分别派代表来重述一下你以往遇到的“描述行为和事实”不当问题可以吗？\u003c/p>\u003cp>A组郑老师: 老公近半年都没有去跑步了，一直也不去锻炼，针对这种行为我很生气，担心老公的身体健康，让老公远离三高。但老公很抗拒，不想去运动。\u003c/p>\u003cp>B组樊老师：儿子放学回来，作业没有写，就在那边玩游戏，想让儿子先把作业写完，在玩。\u003c/p>\u003cp> 拆书家:两个小组都说出了自己的以往不知道如何说清楚家人和行为的场景。然后郑老师这边的案例比较典型，那么我们就来讨论这个案例。那么请郑老师重述一下案例，然后来明确一下问题。\u003c/p>\u003cp> 【郑老师】让老公去跑步，远离三高，拥有健康的身体。\u003c/p>\u003cp>【回应】好的，那我们现在针对郑老师的案例来讨论。\u003c/p>\u003cp>既然大家都对这个问题感兴趣，我们就尝试帮他一起来现场分析，来帮助郑老师出谋划策地解决一下。\u003c/p>\u003cp>给大家5分钟的时间，请大家用开放性的问题来向郑老师提问，比如：可以问他的最初想法，为什么会问这个问题？当时自己采取的行动是怎样的？是个人影响及后果没有表述清楚，还是没有表达？还是就没有后续了呢。每个人轮流问，一次只问一个问题。（注意：在这个过程中只能提问，不能给答案，不给建议）\u003c/p>\u003cp>张：你老公半年没有运动是看到的，还是怎么得到的？\u003c/p>\u003cp> 郑：生活中观察到的\u003c/p>\u003cp> 樊：这件事的触发点是什么？\u003c/p>\u003cp> 郑 ： 原先带家里老人做检查，都出现过三高。\u003c/p>\u003cp> 李：老公的身体健康，有没有出现过不正常的指标。\u003c/p>\u003cp> 郑 ：老公以前也出现过，后面通过跑步运动，三高降下来了。\u003c/p>\u003cp> 陈：为什么你说完运动这件事，你老公就生气？\u003c/p>\u003cp> 郑：他觉得我管着他了。\u003c/p>\u003cp>\u003cstrong>3、明确问题本质\u003c/strong>\u003c/p>\u003cp>刚才通过大家不断提问与讨论，我们知道困扰郑玲的问题是行为上看到了家里老人三高的情况，以及老公也出现过三高的情况，通过跑步得到了缓解。希望让老公去做跑步这件事。过程中无法正确的描述行为和事实，是站在指责的角度。不知道如何做到对事不对人\u003c/p>\u003cp>拆书家提问：也就是说不是我不知道如何描述行为，而是会带有情绪的职责，只想宣泄情绪，也就是说情绪管理能力不足，大家认同吗？\u003c/p>\u003cp>学习者：认同\u003c/p>\u003cp>\u003cstrong>4、分组讨论问题解决方案\u003c/strong>\u003c/p>\u003cp>接下来的8分钟内，请大家在小组内就这个问题来讨论，每个小组就郑老师的这个行为和事实问题来提供解决方案，如何帮他来解决这个问题，用什么方法或步骤可以做到。这里可以再分为两步：先讨论出解决目标是什么，即这个问题解决到什么样子就算满意了。下面给大家2分钟时间讨论这个问题解决到什么样子就可以了。\u003c/p>\u003cp>学习者讨论\u003c/p>\u003cp>时间到，那么讨论出来的解决目标是\u003c/p>\u003cp>小组A和B：让老公接受健康的理念。\u003c/p>\u003cp>下面我们继续分组讨论如何行动就能达到这个目标。我们可以根据自己的经验找方法，越多越好，越具体越好。各组要有小伙伴将大家讨论出的可行的做法和思路记录在纸上哦。5分钟后，请各组派代表分享一下小组成果。\u003c/p>\u003cp>（学习者讨论）\u003c/p>\u003cp>\u003cstrong>5、讲解成果\u003c/strong>\u003c/p>\u003cp>拆书家：时间到，小伙伴们讨论的非常热烈啊，接下来，请各组选一名代表来分享一下。\u003c/p>\u003cp> 小组A：我们这边的解决方法有：1.首先改变沟通方式控制情绪 2.了解老公的真实需求 3.说明具体的请求。\u003c/p>\u003cp> 小组B：我们的解决方法是：1.掌握当时的情绪 2.体会当时的需要，向老公表达请求 3.给出更多的选择\u003c/p>\u003cp>拆书家：那么我们给郑老师提供的解决问题的方法是以下几点。\u003c/p>\u003cp>1、情绪：改变沟通方式，不要评判，控制好当时情绪\u003c/p>\u003cp>2、需要：了解老公真实的需求，去体会他的内心\u003c/p>\u003cp>3、选择：这个时候表达出请求，给出更多的选择。\u003c/p>\u003cp>通过这3点来说明了让老公接受健康的理念的原因，从而使我们进入正向的描述行为和事实。\u003c/p>\u003cp>拆书家：郑老师觉得这几点可以解决你的问题吗？\u003c/p>\u003cp>学习者：可以。\u003c/p>\u003cp>拆书家：好的，看来我们已经解决郑老师的“描述行为和事实”这个问题了。再次感谢大家的思考和分享，因为时间关系，今天我们的讨论就先到这里，如果大家还有问题，一会结束后，我们可以再交流。\u003c/p>\u003cp>通过微行动，相信大家对建设性反馈技术，有了进一步的理解，接下来，我要给大家布置一个小任务，希望大家去完成。\u003c/p>\u003cp>请大家在稍后的苹果洋葱环节，运用我们今天所学的积极性反馈技术三步法或建设性反馈技术三步法，让我做第一个接受反馈的幸运儿。\u003c/p>\u003cp>请大家10分钟后把反馈的过程以及结果写在便利贴上。\u003c/p>\u003cp>结语：\u003c/p>\u003cp>好，最后总结一下今天学习的内容。当你需要赞美他人，在给他人真心反馈的时候，对方能否感受到。积极性反馈技术是哪三步？1.描述行为和事实  2.阐述影响和评价  3.表示欣赏和感谢。通过这3步真心的表达，让对方感受到。\u003c/p>\u003cp>当他人犯了错误，需要我们去指正的时候，我们学习了建设性反馈技术三步法：1.描述行为和事实  2.阐述影响和后果 3.知名期待的行为和结果 ，通过这三步让我们中正，客观的给予反馈。\u003c/p>\u003cp>希望今天的2个拆页让大家以后都能运用及时赞美，客观批评，让对方不仅感觉到你的真心，还能感受到你对他的期待。\u003c/p>\u003cp>今天我的拆书分享就到此结束，谢谢大家的聆听与陪伴。\u003c/p>\u003cp> 【学习者案例】\u003c/p>\u003cp>积极性反馈\u003c/p>\u003cp>丁老师：驰驰在第一个片段的案例中很形象的照顾到我们每一位伙伴，他有提到第一次来拆书现场给马老师做反馈，这个是关联了我们在做的每一位伙伴，大家都能感同身受（行为和事实）\u003c/p>\u003cp> 在正例的时候，又很好的，点名当时伙伴运用积极性反馈技巧，给我们很大的触动，我觉得很值得我们学习（影响和评价）\u003c/p>\u003cp> 这可以让我们来参加拆书活动的伙伴，都会回想自己第一次来参加活动时做反馈的场景，我觉得这点的运用很值得我们伙伴学习，我觉得这次的运用给我们在座的伙伴，做了很好的表率，一定要以学习者为中心，我觉得此时此刻，让我们把掌声送给驰驰（欣赏和感谢）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1653633729000,"updated_at":1654254844000,"ria":true},{"id":13447,"topic":"TF2-4","learn_goal":"","remark":"2拆页","level":"TF2-4","duration":75,"status":30,"type":0,"chaishujia":{"username":"Amber Shen","city":"北京市"},"club":{"name":"昆明春城分舵","city":"昆明"},"prologue":"\u003cp>大家好，非常感谢各位今天来参加我的TF 2-4 拆书过级。首先，我用三个标签来介绍自己。今天的标签，我会用三张塔罗牌来说明，分别是：宝剑王牌、隐士和五角星侍卫。\u003c/p>\u003cp>【宝剑王牌】意味着开始或计划新的冒险。由于工作的原因之前有几个月没有过级，而现在也是想重新开始我的拆书冒险之旅。\u003c/p>\u003cp>【隐士】代表暂别外在的世界，来唤醒寻找内在的自我。因为疫情原因商店、餐厅很多都关门，大家也各自在家办公，我们暂别了外面的世界，而这也给了我时间去探索自我。\u003c/p>\u003cp>【星币侍卫】意味着努力学习。这个时代我们每个人都很焦虑，都在思考如何去应对未知的不确定性。所以努力让自己变好，提升你的“免疫力”，这不仅是当下给自己提供一种确定性，也是对未来最好的准备。而这就是我的第三个标签，持续学习。\u003c/p>\u003cp>拆页开始之前，想问大家有没有遇到过这种情况，\u003c/p>\u003cp>有时候别人为你做了一件事你深受感动，但是张嘴除了谢谢却什么也说不出来？\u003c/p>\u003cp>你花了几个小时给下属反馈，结果他还是不理解自己未来要怎么做？\u003c/p>\u003cp>可见，反馈这件事在促成一场有效的对话中十分重要，而我们今天的拆页，就和反馈相关。\u003c/p>\u003cp>两个拆页片段选自同一本书《教练型管理者》。\u003c/p>\u003cp>【F特征】（以书为核心满足好奇心：作者+主题类别+内容大概）\u003c/p>\u003cp>这本书由俞清和金慧英共著，讲述了如何把教练技术用在企业管理中。本书的特点就是“简单、实用、有效”，能够服务于各个管理岗位的人。 \u003c/p>\u003cp>【A优势】（用比较建立安全感：公众/专家/拆书家个人比较）\u003c/p>\u003cp>市场上很多关于教练的书都偏重于从理念或工具层面阐述，而《教练型管理者》则更为落地接近我们国内的管理情境，填补了国内该方面书籍的空白。更重要的是，书里介绍技术、方法都来自真实的企业管理实践，经过检验并且仍在被企业使用。\u003c/p>\u003cp>【B利益】（学习者能学到什么引发兴趣：解决痛点、增强能力）\u003c/p>\u003cp>【B1学完本书可获益】\u003c/p>\u003cp>不管你是想在工作或生活中练习倾听、提问还是反馈的技能，这本书都会告诉你如何把技能代入真实情景中运用，简单易上手，但非常有效。\u003c/p>\u003cp>【B2片段1获益】\u003c/p>\u003cp>学完第一个拆页，我们在给别人反馈时可以迅速按照方法给出积极且印象深刻的反馈，促进人际关系 。\u003c/p>\u003cp>【B2片段2获益】\u003c/p>\u003cp>学完第二个拆页，我们能够指出别人的不足，但可以用发展的角度提出有建设性的反馈意见，提升人际影响力。\u003c/p>\u003cp>【总学习目标】\u003c/p>\u003cp>所以我们可以看到，今天的两个拆页，它们是并列关系，面对不同的反馈场景，可以选择相应的方法。\u003c/p>\u003cp>在跟随我完成本次RIA学习后，学习者能够在对话中，运用“3A反馈”和“AID反馈”，促成有效对话，营造良好的人际关系，构建个人影响力。\u003c/p>\u003cp>【拆页一学习目标】\u003c/p>\u003cp>通过学习拆页一，学习者能够运用“3A反馈法”营造积极氛围，真诚且深刻地表扬别人，甚至激励别人。\u003c/p>\u003cp>【拆页二学习目标】 \u003c/p>\u003cp>通过学习拆页二，学习者能够运用“AID反馈法”在现场的情景演练中，给出有建设性的反馈意见。\u003c/p>","ratings_count":2,"texts":[{"id":17464,"quote":"\u003cp>【片段1】3A积极性反馈\u003c/p>\u003cp>《教练型管理者》P202-203\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。 这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。 不难看出，上述学员的反馈完全符合这3个要素。\u003c/p>\u003cp>积极性反馈的注意要点如下。\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单的评判。其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给予评价。 描述或评价的影响不仅是针对个人的，还要针对团队和整体。 我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。最后，表示由衷的欣赏和感谢。\u003c/p>","explains":"\u003cp>【What】\u003c/p>\u003cp>这个片段讲的是当我们需要给出正向的反馈，例如表达感谢时，可以通过积极反馈法给出真诚但非常有力量的回应 。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>【一般做法】\u003c/p>\u003cp>在生活中我们少不了要去赞扬别人或感谢别人，而绝大多数人的做法就是说一句“你真棒”“谢谢”，似乎也不知道用什么其他的方式来表达自己。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>而如果每次都只是用一个简单的词描述自己的反馈，长此以往，别人就会觉得他做的事对你来说并没有很大的意义，对方很有可能认为你甚至都不在意，说句谢谢只是在敷衍，未来又怎么会继续去帮你呢？\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>用一个我的例子来说。\u003c/p>\u003cp>在做上一个项目的时候，我其实并不了解这个行业，而主管非常耐心给我搜集各种资料，有时候还让我看一些视频培养行业敏感度。一个月以前我们很多人聚会一起吃饭，期间我去敬了主管一杯酒，说感谢你一直以来的照顾，他的回答是“I hope so（但愿如此）”。这个回答我一直记在心里，突然意识到，可能这么久以来他以为我没有真心感谢他的付出，应该是觉得比较委屈。当然，尽管我也会经常说感谢，但表达就会很单一。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>把一句单一的“谢谢”转换成有力量的语言，让自己重温对别人的欣赏和感谢之情，同时也让对方更深刻感受到来自你的诚意，这要如何做呢？我们可以把拆页细化成下面的3A步骤：\u003c/p>\u003cp>1. 第一A（Act）：描述行为和事实\u003c/p>\u003cp>1.1 描述行为：客观概述对方所做的事\u003c/p>\u003cp>1.2 细化事实：具体地逐条列出这些行为\u003c/p>\u003cp>2. 第二A（Actor）：阐述影响及评价\u003c/p>\u003cp>2.1 阐述影响：描述这些行为给个人或团体带来的影响\u003c/p>\u003cp>2.2 给予评价：在影响的基础上做出评价\u003c/p>\u003cp>3. 第三A（Appreciation）：表示欣赏和感谢\u003c/p>\u003cp>3.1 表达感受：表明对方这么做给你带来了哪些感受\u003c/p>\u003cp>3.2 提出感谢：最后总结致以你由衷的感谢或欣赏\u003c/p>\u003cp>【反例变正例】\u003c/p>\u003cp>现在可以看到，平时我们的感谢往往是直接跳到最后一步，而忽略了前面的其他步骤。现在回归到我的案例身上，我们代入3A法具体操作一遍。\u003c/p>\u003cp>1. 第一A：描述行为和事实\u003c/p>\u003cp>1.1 描述行为：“过去你经常做一些事帮我熟悉新的行业”\u003c/p>\u003cp>1.2 细化事实：“打印出文字资料让我阅读，找到相关视频资料就赶紧发给我”\u003c/p>\u003cp>2. 第二A：阐述影响及评价\u003c/p>\u003cp>2.1 阐述影响：“正因为你这么做才让我在短时间内很快了解新的行业，而且逐步上手接触更多的工作内容”\u003c/p>\u003cp>2.2 给予评价：“这是一种很无私的职业情怀”\u003c/p>\u003cp>3. 第三A：表示欣赏和感谢\u003c/p>\u003cp>3.1 表达感受：“你让我感受到来自主管的关心，从前期紧张害怕的情绪里走出来”\u003c/p>\u003cp>3.2 提出感谢：“所以我真的很想感谢你一直以来的照顾和培养”\u003c/p>\u003cp>后来我和主管单独喝了一次咖啡，按照上面的方法表达出我的感激之情，主管特别开心，我们也一起感慨了彼此的成长之路。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有人就说我们平时关系好，根本用不着这么复杂地表达谢谢，多矫情，可是大家想这样一个情况，为什么好多人在酒桌上就能放得开，就觉得喝完酒感情深。有的人喝完酒，可能都会抱在一起说着共同经历的事，一起遇到的挫折，对方为你做了什么，最后对彼此的感谢。我相信，那一刻，拉近我们距离的，甚至让你感动哭泣的一定不止是“谢谢”两个字，而是你在描述的那些行为，事实，影响，评价，感受。\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>3A反馈法适用于有意愿改善人际关系，想通过简单易学的方式给别人积极反馈的人。而不适用于不想主动寻求改变与他人关系的人。\u003c/p>","interaction":"\u003cp>【A1】激活经验（显现提问）\u003c/p>\u003cp>接下来请每个人回忆一下在过去的一个月里，你有没有遇到别人为你做了什么事你很感谢，或者是别人做了某件事让你觉得他做得很好你想赞扬一下？\u003c/p>\u003cp>比如：伴侣把积攒几天的衣服洗了，孩子看你辛苦为你递上一杯水，同事主动帮你分担工作任务，父母给你做了一桌喜欢吃的饭菜。\u003c/p>\u003cp>在大家回忆到的这件事里，可以描述那是一个什么样的场景，你遇到了什么人，你当时的感受怎样？你是怎么做的？结果如何？\u003c/p>\u003cp>给大家每人2分钟的时间回想并写下来，然后我会邀请1-2位小伙伴分享。\u003c/p>\u003cp>Frank分享案例：\u003c/p>\u003cp>过去一个月里主管帮了我很大的忙，工作上因为检查产品时不够仔细导致出现了一个问题，最后客人想要投诉，而主管帮我扛了下来，劝说客人最终没有投诉。而我当时只说了一句谢谢。\u003c/p>\u003cp>【A1+】（反思加工）\u003c/p>\u003cp>现在我们继续，假如时间倒流回去到我们当时遇到的那个情况下，你如何通过学习的“3A法”去应对？你会怎么做呢？\u003c/p>\u003cp>再给大家3分钟时间思考，把自己的想法写下来，稍后我同样会邀请小伙伴分享。\u003c/p>\u003cp>Frank分享案例：\u003c/p>\u003cp>步骤如下：\u003c/p>\u003cp>第一步：描述行为\u003c/p>\u003cp>1.1这次的客诉对我们的部门会有影响\u003c/p>\u003cp>1.2协理你主动和客人去沟通\u003c/p>\u003cp>第二步：阐述影响\u003c/p>\u003cp>2.1客诉会影响我们部门的整体业绩\u003c/p>\u003cp>2.2你为了大家的福利一直在不断努力\u003c/p>\u003cp>第三步：做出感谢\u003c/p>\u003cp>3.1你这份替我出头的作为让我感到非常温暖，让我们觉得能信赖\u003c/p>\u003cp>3.2谢谢你一直栽培我们，让我们有更好的空间去发挥！\u003c/p>\u003cp>【回应与反馈】\u003c/p>\u003cp>Frank的分享太棒了，我们一起为他鼓掌好吗？能够主动分享，这本身就是一种值得赞扬的学习态度，而且在短时间内你就能按照操作步骤给出相应的反馈。在你的反馈中，用到了6个小步骤，要注意的是，大前提是协理和你之间的事，所以要围绕你们展开来给反馈。比如前两步中，先概述他为你做了什么（为你摆平工作上出现的一个问题），然后具体列出他做了哪些事（去找客人沟通、找其他部门协商等）；中间的两步中，先说协理做的事对你或团队产生了什么影响，而不是客诉对公司产生了什么影响（协理这么做，让你免掉了被客人投诉的风险，团队业绩也不会受到影响等），然后你来评价一下（协理不仅用职业的角度处理了工作危机，更在工作中照顾下属）；最后的两步描述就很好地遵循了方法。这样会不会更具体些呢？再次谢谢 Frank。\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>所以大家可以看到，有方法的积极性反馈相比于简单的一个词反馈可以给人带来完全不同的感受。那我们说，表扬别人有方法了，如果对方做得不是很好，你想提出批评，这样的反馈该怎么做呢？这就要到我们的第二个拆页—提出建设性反馈。\u003c/p>\u003cp>第二个拆页的学习目标是：学习者能够运用“AID反馈法”在现场的情景演练中，给出有建设性的反馈意见。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":17465,"quote":"\u003cp>【片段2】AID建设性反馈\u003c/p>\u003cp>《教练型管理者》P209-P210\u003c/p>\u003cp>假设你因为迟到了并错过一个非常重要的销售电话，从而使公司错过了一笔大单。这时，经理A是这样对你反馈的：“李主管，因为你今早晚进公司1个小时，客户打了5个电话都没有找到你本人，所以决定与竞争对手合作了。这给我们公司带来了重大的损失。”经理B是这样对你反馈的：“李主管，因为你今早晚进公司1个小时，客户打了5个电话都没有找到你本人，所以决定与竞争对手合作了。这不仅给我们公司带来了重大的损失，也影响了你个人的绩效，明明到手的两万元的销售提成没有了。”哪一个反馈对你更有触动？答案肯定是后者，因为跟自己的利益直接相关。因此，在阐述影响及后果的时候，更要描述对下属的影响及后果，这样才能真正引起对方重视。\u003c/p>\u003cp>最后，期待的行为和结果也同样必须具体、明确和可行，并且需要正向表达。所表达的期待是下属今后需要修正的行为，所以为了下属正确落实行动，期待的行为和结果必须足够具体、明确和可行。我们经常会碰到在下属完成了某项工作之后，结果却跟管理者的预期有很大的差距。当管理者向他提出困惑时，对方的回答大部分是：“噢，我不知道你有那样的要求。”很多员工的绩效结果与管理者的预期有差距，这与工作要求不明确直接相关。\u003c/p>","explains":"\u003cp>【What】\u003c/p>\u003cp>这个拆页讲的是当对方做出不恰当的行为并造成负面影响时，我们可以通过建设性反馈的方法表明自己批评的态度，同时指明对方以后如何改正的要求。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>原文中的案例用在了工作上，那生活中会是什么场景呢，让我们把它代入到生活中来看。\u003c/p>\u003cp>假设你因为总奔波于出差而没有用足够的时间陪伴家人，从而造成家庭关系紧张。这时，你的爱人是这么说的：“因为你平时回来晚，周末也要出差，我们的亲子活动你都没有参加过，这让我们很难过。”你的孩子是这么说的：“爸爸/妈妈因为你平时回来晚，周末也要出差，你没有参加过我们的亲子活动让我们很难过，更重要的是，你让我失去了对你的信任和爱戴。”哪一个反馈对你更有触动呢？答案肯定是孩子的反馈，因为和你有直接关系。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>【一般做法】\u003c/p>\u003cp>通常情况下，在一个人做得不好的时候，我们可能会像原文中的经理A或者是我列举的生活案例中的爱人给出反馈，强调对方做的事给我们或者别人带来了什么消极影响，却并没有把这个人做的这件事和他的利益直接联系起来。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>如果我们没有给到很妥帖的建设性反馈，没有让对方感到这件事的严重性，很有可能他并不会引起重视，日后还会犯同样的问题。\u003c/p>\u003cp>【How】细化步骤\u003c/p>\u003cp>如何给出建设性反馈呢？可以使用AID法。\u003c/p>\u003cp>AID和3A一样，同样取自三个英文单词的首字母，Act, Impact, Desired outcome。而Aid这个单词本身的意思是帮助，为了辅助记忆，我们可以把它理解成能够帮助别人的反馈，也就是这里提到的建设性反馈。\u003c/p>\u003cp>1. 描述行为（Act）\u003c/p>\u003cp>说出对方所做的具体行为和事实\u003c/p>\u003cp>2. 阐述影响（Impact）\u003c/p>\u003cp>阐述这些行为给别人尤其是\u003cstrong>给他自身利益\u003c/strong>带来了哪些消极影响\u003c/p>\u003cp>3. 期待结果（Desired outcome）\u003c/p>\u003cp>具体、明确、正向地表达希望对方未来达成的结果\u003c/p>\u003cp>【反例变正例】\u003c/p>\u003cp>比如用我们刚才的生活案例来试一下如何使用这个方法：\u003c/p>\u003cp>1. 描述行为\u003c/p>\u003cp>“你平时回来晚，周末也要出差，我们的亲子活动你都没有参加过。”\u003c/p>\u003cp>2. 阐述影响\u003c/p>\u003cp>“这让我们都感到很难过，更重要的是，你让我失去了对你的信任和爱戴。”\u003c/p>\u003cp>3. 期待结果\u003c/p>\u003cp>“我希望每天下班你能抽出一个小时陪伴家人，周末用半天或一天的时间和我们参加一项活动。”\u003c/p>\u003cp>这样的反馈是不是既表达了批评也给出对方很明确可行的要求了呢？\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>这个方法可以用在不满他人做的事情而你想找到方法告诉他们如何改正的情况。\u003c/p>","interaction":"\u003cp>【A3角色扮演】\u003c/p>\u003cp>好，我们刚刚学习了AID反馈法，为了更好的学以致用，让我们通过下面的场景做一次角色扮演。\u003c/p>\u003cp>【具体场景】\u003c/p>\u003cp>公司一位重要的客户要来开项目合作进度会议，领导让你和同事小A一起完成本次的接待和汇报演讲。你和小A私下分配了彼此的任务，你为自己的任务列出了清单逐步去完成。可是在客户到达的当天，小A的状况频出，忘记预约会议室，又忘记检查演讲PPT中的错别字等等，让客户对这次会议感觉非常不好。这时，你该如何去给小A反馈呢？\u003c/p>\u003cp>【清晰指令】\u003c/p>\u003cp>现在请大家在这个场景下，分别扮演你和小A的角色， 应用我们刚才学的AID法给小A进行反馈 。给大家6分钟讨论时间，稍后我们让一组来分享。\u003c/p>\u003cp>学习者分享案例：\u003c/p>\u003cp>瑛子（旁白）、范范姐（小A）、Frank（我/小B）\u003c/p>\u003cp>瑛子：会议已经结束了，小A和小B来到了会议室的另一边，他们对刚才的状况要进行复盘。\u003c/p>\u003cp>小A：今天太烦了，客户脸色很不好走了\u003c/p>\u003cp>小B：我有注意到你忘记预约会议室，而且PPT上也出现了错别字，我们的经理气到脸都红了，你有看到吗？\u003c/p>\u003cp>小A：当时因为比较赶，确实忘记预约了，本来想着要预约，结果忙了别的事就忘记了。\u003c/p>\u003cp>小B：客人的满意度应该是很低的，你看客人脸这么黑。这样子会造成公司的形象很不好，此外可能会造成你的个人考核受影响，你觉得这次你的考核会怎么样呢？\u003c/p>\u003cp>小A：肯定完蛋了，看到客人的脸都黑得跟锅底一样，他都不想看我了。\u003c/p>\u003cp>小B：的确看到了老大们非常生气。那这样小A，以后做这种大型会议的时候，我们可以提前彩排，把PPT错字或者预约会议室这种事都放到彩排里面。这样未来我们工作上配合的时候可以更顺畅。\u003c/p>\u003cp>小A：好的好的，以后我们可以这样。很不好意思，这次也连累你了。\u003c/p>\u003cp>小B：好，我们未来一起加油。\u003c/p>\u003cp>【回应与反馈】\u003c/p>\u003cp>太棒了大家！这三个角色真的是各有各的特色：范范姐是绝对的积极分子，不仅自己组织协调，安排角色，而且还能根据场景制造出新的旁白角色；瑛子姐这个旁白非常专业，action之后就立即进入场景，用你的天籁之音开始播报；Frank是教练级别的，描述行为的时候用到了很多细节描述，让小A更加感觉这种气氛，方法运用非常恰当。\u003c/p>\u003cp>【A2分步催化1】\u003c/p>\u003cp>大家学习能力太强了。刚才大家是在我给出的情景中进行角色扮演，那现在我们从自身出发，想想未来。\u003c/p>\u003cp>请设想一下，在未来的一周里，你可能会遇到什么样的场景，遇到谁，在哪，这个人可能做什么事会让你不爽，让你想批评他。比如孩子的作业完成不好，伴侣在某件事上没有照顾你的情绪，下属没按你的要求完成工作，等等…我给大家3分钟左右的时间把这个场景写下来，稍后请小伙伴分享。\u003c/p>\u003cp>瑛子分享：\u003c/p>\u003cp>朋友住院住了一个多星期，下周我和朋友打算一起去住院朋友的家里帮忙打扫卫生、整理屋子。有可能我们下次去帮忙的时候，我另一个朋友可能会在没有征得住院朋友同意的时候，就把她的东西扔掉，我在这种情况下会感到生气，会带着情绪和她讲话。\u003c/p>\u003cp>朝丽分享：\u003c/p>\u003cp>下周我会做储备盘点，我知道我们的损耗会很大，就在想怎么要去和他们谈这个事，所以我下周可能会很生气，和他们说话时也会带着愤怒和怨气，直接就说“你们是怎么搞的，一下子就损失几万块钱”。\u003c/p>\u003cp>【A2分步催化2】\u003c/p>\u003cp>感谢学习者的分享，的确在生活中和工作中我们都会面对不同需要反馈的场景。\u003c/p>\u003cp>好，那接下来，请各位联系刚才设想出未来一周会发生的场景，先自己构思你计划怎么做，然后和大家一起讨论你的规划。当别人做出让你不满意的事情，你如何运用AID反馈法，希望达成什么结果呢？\u003c/p>\u003cp>这次给大家稍微长一点的时间去讨论，6分钟后讨论结束我们还是邀请小伙伴来分享。\u003c/p>\u003cp>朝丽分享：\u003c/p>\u003cp>未来一周里（时间），我会因为库存盘点耗损很大想要批评店员（场景）。我会先告诉她们这次的耗损情况严重以及她们在盘点中出现的问题行为（描述行为）；然后列出严重的耗损会影响店长的年薪，引起我对她们的不信任、也会影响她们自己的奖金（阐述对别人尤其是对她们自己的影响）；最后告诉店员为避免耗损我希望她们未来具体需要去遵守的几条规定（期待结果）。\u003c/p>\u003cp>【回应与反馈】\u003c/p>\u003cp>朝丽在自己未来可能遇到的场景中明确设定了如何按照AID反馈法实际操作，我相信这样给店员反馈的你一定会收获满满。谢谢朝丽，掌声送给你。\u003c/p>\u003cp>【强有力的结语】\u003c/p>\u003cp>我们再来回顾一下今天的两种反馈方式——3A积极性反馈和AID建设性反馈。3A积极性反馈要求我们不只是单纯说句“谢谢”“你真棒”，而是让我们不加评判的描述行为、阐述带来的影响和你的评价、最后表达你的感受和给予感谢。而AID建设性反馈让我们不要一味指责，相反，我们要描述对方的行为、阐述它为别人尤其是他个人带来的影响、最后明确表达你期望对方未来做出哪些具体改变。\u003c/p>\u003cp>最后希望大家在不同场景下运用相应的两种反馈方式，促进人际关系，提升个人影响力。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1653237242000,"updated_at":1653834745000,"ria":true},{"id":13205,"topic":"积极反馈正向激励之“3A积极反馈法”","learn_goal":"","remark":"在管理成长型组织、成长型团队、具备成长潜质员工时，如何对他们有效的正向激励是每个管理者都要面临的问题。今天介绍一种“3A积极反馈法”通过策略的设计来实现上述目的一种方法。它包含“描述事实”、“阐述影响”、“表示感谢”三部分。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"西边懂佛","city":"宝鸡市"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"\u003cp>拆书帮的各位小伙伴们，大家下午好！我是今天的拆书家董兴华，很高兴加入到拆书帮，结识这么多的小伙伴。我想用三个标签来介绍一下自己：\u003c/p>\u003cp>第一个标签：我是名工程师，从事石油钻井设备的计算机视觉智能研发工作。\u003c/p>\u003cp>第二个标签：我是名正在读博的宝爸，我希望通过自己的努力给孩子做个好榜样，并给自己的工作带来点改变。\u003c/p>\u003cp>第三个标签：我是新手拆书家。参加完拆书训练营，希望大家在现场能给我更多反馈，这样才能帮助我提高，所以请知无不言言无不尽，我都虚心接受，希望早日成为三级拆书家。\u003c/p>\u003cp>我的TF1-1内容如下：\u003c/p>","ratings_count":1,"texts":[{"id":17195,"quote":null,"explains":"\u003cp>技能点：选书与选拆页 &amp; 请学习者阅读拆页\u003c/p>\u003cp>今天我分享的是“3A积极反馈法”摘自《教练型管理者》。刚才我已经把原文拆页发给大家了，请大家花分一钟时间阅读一下（重点是加黑部分）。读完之后请大家举手示意我一下。\u003c/p>\u003cp>技能点：当众表达便签\u003c/p>\u003cp>1.what：在管理成长型组织、成长型团队、具备成长潜质员工时，如何对他们有效的正向激励是每个管理者都要面临的问题。今天介绍一种“3A积极反馈法”通过策略的设计来实现上述目的一种方法。它包含“描述事实”、“阐述影响”、“表示感谢”三部分。。。\u003c/p>\u003cp>2.why:传统的企业管理模式都是“管理者”与“被管理者”的关系，但是在复杂多变的今天，这种关系的界定不利于企业的成长，需要针对不同的组织类型，有针对性的产生新的管理模式。管理者以帮助下属成长作为首要任务的管理方式称为教练式管理;以运用教练技术帮助下属通过学习获得成长作为第一要义的管理者就是教练型管理者。当教练型管理者产生时，传统的&quot;管理者&quot;与&quot;被管理者&quot;的关系转变成新型的&quot;教练&quot;与&quot;学员&quot;的关系。这种关系的转变带来激励策略的调整。\u003c/p>\u003cp>根据“马斯洛的需要层次理论”，如果针对这类对象基本的需求无法被满足，就会影响其成长，进而给个人和团队带来负面影响。\u003c/p>\u003cp>3.how：这种激励策略可以一种套路的形式呈现，便于大家掌握，在这归总为三步法\u003c/p>\u003cp>3.1.聚焦事实\u003c/p>\u003cp>如果要实现对事实的真实、客观、具体的反馈，就要关注事实发生的原因-过程-结果。这是“马斯洛的需要层次理论”中的“安全需求”，也就是常说的“我干的工作，领导看得到”。\u003c/p>\u003cp>3.2.影响赋能\u003c/p>\u003cp>通过对事实背后影响的评价有方向性的扩大，包含个人、团队及整体的评价，能促进相关对象荣誉感和成就感的激活，使其产生内在的动力。这是“马斯洛的需要层次理论”中的“自尊的需求”。\u003c/p>\u003cp>3.3.情感升华\u003c/p>\u003cp>作为一个“教练型管理者”，其地位属于强势地位，这时如果对“学员”以适当的方式对其工作表示感谢，对其行为表示欣赏，是对“学员”最大的认可和赞扬，这会激发他们内在驱动力，构建他们的主人翁意识，真正实现最终的“成长”和“独立”。这就实现了“马斯洛的需要层次理论”中从“缺失需求”向“生长需求”的转变，最终实现“自我实现的需求”。\u003c/p>\u003cp>4.where：在管理成长型组织、成长型团队、具备成长潜质员工时，管理者需要用到上述方法。\u003c/p>\u003cp>但是需要注意对事实的描述一定要具体、客观、但不一定要“公正”，因为“教练型管理”是以促进相关对象成长为目的，允许对象有“试错”的过程，所以适当的“倾向性”没有坏处。\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp>下面是我个人经历：\u003c/p>\u003cp>2015年我曾经在大连组建过一个项目团队，共同工作3个月，由于我们是临时组建的团队,团队内人员都是来自各个部门的，都互相不熟悉，工作方式也有很大差异。比如我们团队中的A和B两人的协同工作问题，两个员工对于该谁多干点，该谁少干点存在不同看法(我们的工作是两人成组协同作业，所以对双方界面都是两人自己商量)，老互相埋怨，内卷不断。我当时的做法是开小会，让双方把想法说清楚，然后将原因归到自己身上（比如自己一开始任务分配时，没有注意到大家情绪，是我分配的问题），希望通过这种方式化解双方矛盾，结果事得其反，双方趁这个机会互相挖苦对方，说完导致矛盾进一步激化，谁也容不下谁。\u003c/p>\u003cp>A2:\u003c/p>\u003cp>后来我读了“3A积极反馈法”的内容，突然意识到：针对这类对象，我们首先应关注“马斯洛的需要层次理论”中的“缺失需求”，使其建立足够的情感支撑后才能讨论高级的“生长需求”，不能齐头并进，更不能一刀切。因此在未来一个月内再次涉及这种协作项目的工作分配时，会按照“3A积极反馈法”分为三步来处理：\u003c/p>\u003cp>1.聚焦事实\u003c/p>\u003cp>在后面的团队组建中改变做事方法，对A和B的工作都给予“客观、具体”的评价。当然这种评价带有一定的引导性。反复告诉两人，我们这个团队是以工作量考核个人的，干得多挣得多，让两人从“躲着干”变为“抢着干”。\u003c/p>\u003cp>2.影响赋能\u003c/p>\u003cp>对于对A和B的小问题给与“积极”的引导。我就采用多表扬的模式，在两人在场的私下场合多表扬。暗示：两人在不同工作内容，不同工作时间上都在主动承担工作，为了项目进步付出的努力，都在为对方考虑，并将内容进行具体描述。引导两人从不同角度看待问题，明白团队配合的重要性。\u003c/p>\u003cp>3.情感升华\u003c/p>\u003cp>告诉A和B：他们付出的努力为项目的成功都起到关键的作用。通过这种荣誉感加持的方式增进双方的好感，建立情感支撑，反倒容易促进团队凝聚力的提升，最终实现团队整体的成长。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1648388026000,"updated_at":1649162884000},{"id":12957,"topic":"让你的批评有效果 — AID建设性反馈法","learn_goal":"","remark":"《教练型管理者》这本书。教练型管理是以目标和成果为导向，以发掘员工内在潜力、促进员工良好行动和持续发展为目的的一种管理方法，本书系统化的讲述了一整套完整、全面的教练工具和教练流程。\n\n\n  没人喜欢被批评，但批评别人却是我们常常使用的反馈方式，因此，要做到一个好的批评就很不容易。AID建设性反馈法，就是一个进行有效批评的好方法。它通过描述行为和事实、阐述影响及后果、明确期待和结果这三个方面的有效表达，使我们的批评达到让对方接受并在未来产生新行为的最终效果。","level":"TF2-1","duration":20,"status":19,"type":0,"chaishujia":{"username":"waynezhang","city":""},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【自我介绍及分组】\u003c/strong>\u003c/p>\u003cp>大家好，我是张巍。我的三个标签是：大龄会员、外地会员、未来的三级拆书家。\u003c/p>\u003cp>下面我将进行2-1的拆书，拆页的主题是：\u003cstrong>让你的批评有效果 — AID建设性反馈法\u003c/strong>。预计时间20分钟。\u003c/p>\u003cp>首先，我们进行一下分组：前面这几位同学作为1组，后面这几位同学作为2组。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>本次拆书的学习目标是：在跟随我完成今天的学习之后，学习者：在对他人提出较正式的批评时，能够向对方指出他不佳的行为和事实，以及所造成的负面影响，并明确告知自己希望对方做到的新行为和期待的具体结果。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【F特征】\u003c/strong>\u003c/p>\u003cp>今天的拆页来自于《教练型管理者》这本书。教练型管理是以目标和成果为导向，以发掘员工内在潜力、促进员工良好行动和持续发展为目的的一种管理方法，本书系统化的讲述了一整套完整、全面的教练工具和教练流程。\u003c/p>\u003cp> \u003cstrong>【A优势】\u003c/strong>\u003c/p>\u003cp>这本书的作者是国内长期从事教练管理实践的管理者及培训师。和很多经典的教练管理类书籍相比，这本书易读、易懂、更贴近实战、更容易落地践行。在豆瓣上达到了五星8.6分的高分。\u003c/p>\u003cp> \u003cstrong>【B利益】\u003c/strong>\u003c/p>\u003cp>我刚才介绍这本书时，大家一定注意到了“成果导向、发掘潜力、促进行动“这些词语，是的，教练型管理和我们拆书帮的理念是非常类似的，都是要激发个人意愿、释放团队能量，相信大家读了这本书，不仅能了解教练型管理，更会对我们的拆书学习产生触类旁通、举一反三的帮助。\u003c/p>\u003cp>今天我们学习的是这本书中的第101页，内容是如何对他人进行有效的批评。相信大家学习到如何批评，对自己的工作和生活都会有很大的帮助。\u003c/p>\u003cp>原文很短，下面请大家用1分钟来阅读一下。阅读完的小伙伴们请举手示意。\u003c/p>","ratings_count":2,"texts":[{"id":16939,"quote":"\u003cp>\u003cstrong>【R-原文片段】（562字）\u003c/strong>\u003c/p>\u003cp>通过积极性反馈的学习，我们可能感到表扬人不容易。其实批评人更不容易。因为表扬至少不用担心对方会生气，而批评弄不好会和人起争执。有句话我们都知道：“批评要对事不对人。”关键是怎样才能做到“对事不对人”。\u003c/p>\u003cp>有效的建设性反馈由3个要素构成：一是描述行为和事实（Art）；二是阐述影响及后果（Impact）；三是指明期待的行为和结果（Desiredoutcome）。这三个要素缺一不可，我们简称为AID反馈技术。\u003c/p>\u003cp>建设性反馈的注意要点如下：\u003c/p>\u003cp>首先，行为和事实的描述应具体、客观和真实。我们在反馈时不仅需要顾及行为的结果，更要关注行为过程本身，因为过程会产生必然的结果。我们在描述行为时一定要注意观察，我们要观察人的具体行为，而不是对人本身进行评判。\u003c/p>\u003cp>其次，我们在阐述影响及后果的时候，不仅要描述这些行为对集体和团队的影响及后果，更要描述这些行为对下属的影响及后果。这样才能真正引起对方的重视。\u003c/p>\u003cp>最后，期待的行为和结果也同样必须具体、明确和可行，并且需要正向表达。所表达的期待是下属今后需要修正的行为，所以为了下属正确落实行动，期待的行为和结果必须足够具体、明确和可行。我们经常会碰到在下属完成了某项工作之后，结果却跟管理者的预期有很大的差距。当管理者向他提出困惑时，对方的回答大部分是：“噢，我不知道你有那样的要求。”很多员工的绩效结果与管理者的预期有差距，这与工作要求不明确直接相关。\u003c/p>","explains":"\u003cp>好的，大部分小伙伴已经读完了，下面我来为大家来讲解一下AID反馈法。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>批评是每个人都经常使用的反馈方式，但要做到一个好的批评却很不容易，我们的批评往往都是带着负面情感、都是直接评判对方、都是强调造成的问题。\u003c/p>\u003cp>这样的批评，结果往往都是会这样：\u003c/p>\u003cp>1、心理情绪的对立：对方会直接产生反感，听不进去你的批评\u003c/p>\u003cp>2、改进方向的模糊：对方也不知道接下来具体该做什么。\u003c/p>\u003cp>3、实现结果的困难：因为情绪的对了以及方向的模糊，未来的改善就很困难了。\u003c/p>\u003cp>4、人际关系的下降：因为对方不能接受批评及情绪的对立，导致双方人际关系下降甚至恶化。\u003c/p>\u003cp>\u003cstrong>举个例子：\u003c/strong>\u003c/p>\u003cp>背景是：长老对负责活动拍照的小曹老师提出批评。\u003c/p>\u003cp>具体的对话是：\u003c/p>\u003cp>“小曹老师，给你说个事你别介意啊，本来不想说的，怕打击你的积极性，但事关到咱们分舵的集体工作，还是觉得给你说一下比较好。你前天给我的活动照片实在是没法用，合影没有舵旗，人物表情不是闭眼就是歪嘴，照片还都黑咕隆咚看不清楚。最后我只好找别人PS，修图修了2个多小时才符合总舵的要求。今天你拍照可一定要注意啊。”\u003c/p>\u003cp>小曹听了之后，情绪明显低落了下来，提出自己确实不会拍照，还是找其他技术好的人来担任拍照工作比较合适。结果，长老只好去安抚小曹，让他今天继续拍照。\u003c/p>\u003cp>所以，批评做不好，工作不仅无法得到改善，人际关系反而会更加恶化。而今天我们所学习的AID反馈法，就能很好的避免批评中产生对立情绪，使对方的关注点聚焦在事情上，让批评更容易被接受和认可。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>什么是AID反馈法呢？\u003c/p>\u003cp>AID反馈法是一个进行有效批评的反馈方法。它通过描述行为和事实、阐述影响及后果、明确期待和结果这三个方面的有效表达，使我们的批评达到：让对方接受，并产生新行为的最终效果。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>AID反馈法，包含AID三个方面的反馈。\u003c/p>\u003cp>第一个A是指，描述行为和事实。\u003c/p>\u003cp>就是反馈给对方：他做了什么、说了什么。做好第一个A的关键是：不做评判，不讲自己的主观看法及评价，只描述具体的事实。\u003c/p>\u003cp>第二个I是指，阐述影响及后果。\u003c/p>\u003cp>就是反馈给对方：他的行为产生了哪些负面影响和不良后果。做好第二个I的关键是：讲出他的行为会对他自己本人造成什么样的负面影响。\u003c/p>\u003cp>第三个D是指，给出期待的行为和结果。\u003c/p>\u003cp>就是反馈给对方：希望对方接下来去做什么，我们想得到什么样的最终结果。做好第三个D的关键是：正向表达。要明确告诉对方他要做什么，而不是他不要做什么。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>AID反馈法，特别适合于，当问题比较严重时，做正式的批评谈话来使用。\u003c/p>\u003cp>\u003cstrong>回到上面的例子，我们用AID反馈法来进行一下看看。\u003c/strong>\u003c/p>\u003cp>“小曹，有个事情向你反馈一下，相信你了解之后，对你自己和分舵的工作都会有很大的帮助。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>具体情况是这样的，你前天发给我的10张活动照片，4张合影里都没有舵旗的展示，6张人物近景中的人物都有闭眼或歪嘴的情况，同时10张照片的亮度都比较低，整体都达不到总舵要求的照片标准。\u003c/p>\u003cp>\u003cstrong>【I】\u003c/strong>这些照片如果直接发布的话，总舵一定会觉得我们活动办的不好，更重要的是，会对你能否胜任品宣长老胜任产生疑问，其实我们的活动是非常棒的，你也是非常投入和认真的，如果因为照片没拍好而受到总舵质疑的话，那对咱们分舵、对你可就太可惜了。\u003c/p>\u003cp>不过没关系，上次的10张照片我找人PS了，已经能达到总舵的要求。\u003c/p>\u003cp>\u003cstrong>【D】\u003c/strong>但今天的拍照我们一定要拍好，我总结了三个要点，一是合影要展示舵旗；二是近景照片里人物表情要自然生动；三是照片要明亮清晰。你看看实际操作起来有没有什么困难？“\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1--激活经验，显像提问】\u003c/strong>\u003c/p>\u003cp>听了上面的内容，相信大家已经很清楚的了解了AID反馈法。\u003c/p>\u003cp>下面请大家回想一下，在最近一段时间里，你负面感受最深的一次批评或者被批评的经历。\u003c/p>\u003cp>我们可以回顾一下：\u003c/p>\u003cp>当时你的负面感受具体是什么样的？是愤怒？生气？还是委屈？难过？\u003c/p>\u003cp>当时具体的批评对话是什么样的？\u003c/p>\u003cp>这是什么时候的对话？\u003c/p>\u003cp>请大家回想之后，在小组内和大家分享一下。时间是3分钟。\u003c/p>\u003cp>大家分享的很热烈，下面我们请第二组推选一位小伙伴上来分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>孩子在学校上学的时候，有一次下午有自由活动时间，孩子在操场上玩耍，结果回教室的时间晚了，回到教室就被老师一顿批评，老师说：”***，你怎么现在才回来，大家都回教室了，就你还在操场上玩，每次你都不遵守纪律，学习成绩不好，整天就知道玩，下次再这样就叫家长了！“孩子觉得非常难过，回到家里就说不愿意上学了。\u003c/p>\u003cp>\u003cstrong>【A1+反思加工】\u003c/strong>\u003c/p>\u003cp>谢谢***的分享。让我们体会到了一场难忘的批评。接下来我们来做个练习。\u003c/p>\u003cp>假设你是**老师，今天已经学习到了AID反馈法，在将来又遇到了同样的情况，那么运用你会如何运用AID反馈法进行具体的批评对话？\u003c/p>\u003cp>请大家分小组讨论一下，时间3分钟，讨论之后我们请一位小伙伴和大家分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong> \u003c/p>\u003cp>如果我是老师，遇到同样的情况，我会首先明确本次批评的目的。我的目的是让孩子认识到遵守时间的重要性。\u003c/p>\u003cp>接着，我会使用AID反馈法这么说：\u003c/p>\u003cp>首先是【A描述行为和事实】，***，我看到你刚刚进到教室，今天下午的自由活动时间是1个小时，大家应该16点回到教室，而现在已经16点20了，你已经迟到了20分钟。老师很着急，担心你出意外，正准备出去找你呢。\u003c/p>\u003cp>接着是【I阐述影响及后果】，现在你错过了20分钟的上课，这些课程内容没能听到，晚上来你就要用自己的玩耍时间来自学补上。大家还会觉得你不守时。\u003c/p>\u003cp>最后是【D给出期待的行为和结果】，老师希望你今后能注意好时间，按时回到教室上课，老师相信你一定能做到的，对不对？\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>感谢这位小伙伴的分享！\u003c/p>\u003cp>现在我们一起回顾一下今天的学习内容，AID反馈法，是一个有效进行批评的好方法。它通过描述行为和事实、阐述影响及后果、明确期待和结果这三个方面的有效表达，使我们的批评达到：让对方接受，并产生新行为的最终效果。\u003c/p>\u003cp>今天的拆书到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1642408057000,"updated_at":1643454869000,"ria":true},{"id":12870,"topic":"使用積極性反饋強化他人持續作出正向行為， 使用建設性反饋讓他人行為改善能符合自己的預期，期待學會的你能夠，表揚他人，讓人備感窩心；要求他人，讓人想要配合改善。","learn_goal":"","remark":"在给予他人正向反馈的场景中使用积极性反馈来表扬他人及在設定的場景中使用建設性反饋作出正向要求。","level":"TF2-4","duration":55,"status":30,"type":0,"chaishujia":{"username":"Frank Hung","city":""},"club":{"name":"台北悦读不卡分舵","city":"台北"},"prologue":"\u003cp>【开场+分组】 1分钟\u003c/p>\u003cp>大家好，我是来自台湾台北的洪麒富，目前在华利集团任职鞋类模具业务主任，我的三个标签是：1. 图卡知识设计 2. 英文/越文交流 3. 简报培训\u003c/p>\u003cp>【拆頁一学习目标】\u003c/p>\u003cp>当完成此片段內容後，学习者能：\u003c/p>\u003cp>在给予他人正向反馈的场景中使用积极性反馈来表扬他人。\u003c/p>\u003cp>【拆頁二学习目标】\u003c/p>\u003cp>当完成此片段內容後，学习者能：\u003c/p>\u003cp>在設定的場景中使用建設性反饋作出正向要求。\u003c/p>\u003cp>【图书介绍】1分钟\u003c/p>\u003cp>【Feature特征】：（以书为核心来满足好奇心）（作者+主題類別+內容大概）\u003c/p>\u003cp>今天要介绍的片段内容来自《教练型管理者》这本书，本书作者由俞清和金慧英一同完成，属于企业管理类的书籍，此书基于&quot;一名优秀的管理者就是一名好教练！ &quot;的论点举出传统管理者大多是顾问的角色，代替员工解决问题，而教练管理者用教练技术激励员工，让员工自己找到解决事情的方法。\u003c/p>\u003cp>【Advantage优势】:(用比较建立安全感）（公众比较、专家比较、拆书家个人比较）\u003c/p>\u003cp>本书并非是针对教练专业人士学习的教科书，而是针对服务于在各个管理岗位的管理者，力图表现&quot;简单、实用、有效&quot;，让非教练专业人士也能将教练技术落地在自己的领域中。\u003c/p>\u003cp>【Benefit利益、好处】:(强调学习者能学到什么以引发兴趣）（你/学习者、解决痛点（经历显像）、增强能力（生活工作实际能力））\u003c/p>\u003cp>【B1】（学完本书可得利益）\u003c/p>\u003cp>你有没有曾经自己忙得半死，而下属却又似乎没事做？ 你有没有曾经因为不懂得倾听，只能听对方的话语而不是深层需求？ 你有没有曾经因为不懂得作反馈而让另一方行为不断背离自己的期待？ 此书提供的深度倾听、有力提问、有效反馈可以帮助我们解决上述的难题。\u003c/p>\u003cp>【B2】（学完此片段可得利益 ）\u003c/p>\u003cp>片段一内容是积极性反馈，在于学会给出具体的表扬以强化他人重复地作出正确的行为，另外片段二內容是建設性反饋，在于學會提出讓人願意配合改善的要求，兩者個拆頁屬於互補關係。\u003c/p>\u003cp>等等有分組討論，由於今天人少请大家自成1组，现在请大家阅读原书拆页，读完后可以举手示意或是告诉我你读完了，那我们现在开始\u003c/p>","ratings_count":3,"texts":[{"id":16833,"quote":"\u003cp>【片段主题】：积极性反馈技术AAA\u003c/p>\u003cp>【片段来源】：《教練型管理者》P202-203\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。 这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。 不难看出，上述学员的反馈完全符合这3个要素。\u003c/p>\u003cp>积极性反馈的注意要点如下。\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单的评判。其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给予评价。 描述或评价的影响不仅是针对个人的，还要针对团队和整体。 我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。最后，表示由衷的欣赏和感谢。\u003c/p>","explains":"\u003cp>\u003cstrong>【What】（这是一个什么概念）\u003c/strong>\u003c/p>\u003cp>在给予有效性的积极反馈时一定要具体且不能是简单的评判，这将对个人的正向行为有强化的效果进而扩大对团队的影响。\u003c/p>\u003cp>\u003cstrong>【Why】（为什么要这么做，这么做有什么好处，不这么做有什么坏处）\u003c/strong>\u003c/p>\u003cp>一般做法：\u003c/p>\u003cp>一般人给予正面反馈时通常流于空洞，例如听完演讲觉得很不错，想要给予正面反馈却又说不出是哪里棒，又或者下属完成了一件任务，管理者只认为这是下属的份内之事，而不懂得使用积极性反馈强化其重复正确行为的意愿。\u003c/p>\u003cp>不这么做的坏处：\u003c/p>\u003cp>不懂得使用积极性反馈技术，其反馈无法进一步激发被反馈者的正向行动意愿，反馈的有效性大打折扣。 若是能使用积极性反馈，例如具体说出演讲哪里说得好的地方能强化演讲者下次再次分享的意愿，又或者对下属的正确行为予以表扬强化其正确行为的意愿。\u003c/p>\u003cp>\u003cstrong>【How】（具体怎么做呢）\u003c/strong>\u003c/p>\u003cp>原文的&quot;积极性反馈&quot;不容易落地执行，我把原文的三个大步骤下将每个步骤再细化2个小点后以利学习者使用，细化步骤如下：\u003c/p>\u003cp>1. 描述行为 ：\u003c/p>\u003cp>a. 不带评判：不作简单的评判去区分行为的好坏或是对错\u003c/p>\u003cp>b. 具体描述：将行为用量化的方式呈现，如进行的第10分钟，在演讲时的第2主题...\u003c/p>\u003cp>2. 表达作用：\u003c/p>\u003cp>a. 说明影响：说明事实带来的影响，如演讲的主题带给我什么提升\u003c/p>\u003cp>b. 给予评价：对影响给予评价，如演讲带给自己的提升能产生什么好处\u003c/p>\u003cp>3. 表达感谢：\u003c/p>\u003cp>a. 分享感受：分享行为所带给你的良好感受，如这场演讲让我感到非常振奋人心\u003c/p>\u003cp>b. 总结行为：对此次行为作一个总结，如谢谢你带来这么精彩的讲解\u003c/p>\u003cp>【失败案例】\u003c/p>\u003cp>由于在外地工作，每次回到家，母亲都会在这期间，特别给我准备我爱吃的菜，我总和她说不用特别准备，我们点外卖也可以，不用煮的那么辛苦，忙进忙出的也要2-3小时从买菜、备菜到上桌，但看到一桌我爱吃的菜，其实内心是很感动的，但也是尽量把菜吃光光然后说声真好吃，并没有让母亲知道我因为这些佳餚而得到的心灵抚慰。\u003c/p>\u003cp>【加工正例】\u003c/p>\u003cp>如果当时的我学会积极性反馈，當母亲煮一桌好菜给我吃时，我会这样子表达：\u003c/p>\u003cp>1. 描述行为 ：\u003c/p>\u003cp>a. 不带评判：母亲煮了6菜一汤来欢迎我的到来\u003c/p>\u003cp>b. 具体描述：买菜花了1小时，备菜花了半小时，煮菜花了1.5小时\u003c/p>\u003cp>2. 表达作用：\u003c/p>\u003cp>a. 说明影响：今天的菜色不只是好吃，是日思夜想的好味道\u003c/p>\u003cp>b. 给予评价：这些好味道让我觉得自己很放松像回到儿时的无忧无虑\u003c/p>\u003cp>3. 表达感谢：\u003c/p>\u003cp>a. 分享感受：母亲你煮的菜让我很感动、很开心\u003c/p>\u003cp>b. 总结行为：谢谢母亲你为我做那么多好吃的菜\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>大家一定会想积极性反馈太困难了，感谢就感谢，还要想那么多的步骤，实在是违反人性，但若不进行积极性反馈便无法让对方得到确切的反馈，无法把内心的感谢具体地传达给对方，若使用积极性反馈可以让对方获得成就感并强化其正向行为的动机。\u003c/p>\u003cp>\u003cstrong>【Where】(适用场景)\u003c/strong>\u003c/p>\u003cp>适用于給予他人正向反饋的场景\u003c/p>\u003cp>不适用于建議他人改进的场景\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】(激活过去的经验) \u003c/strong>\u003c/p>\u003cp>【显像提问】\u003c/p>\u003cp>接下来，请大家想一想，在過去一個月有沒有發生因為別人的正向行為讓你感到很開心或是感動，但你並沒有好好地表達出自己的感謝，例如下屬按照計劃出色地完成任務、朋友為你做的貼心小事、小孩做了讓你覺得很窩心的事等等。\u003c/p>\u003cp>请大家在小组内讨论分享，时间为30秒。好了，时间到，下面我们请组内一位小伙伴来分享一下他的故事。\u003c/p>\u003cp>【学习者分享】（失败案例）\u003c/p>\u003cp>Carol：\u003c/p>\u003cp>最近這幾天天氣很冷，昨天老公趁著我外出的時間，把全部的床單、棉被套、枕頭套等全都拆下來清洗、烘的暖呼呼的想讓我晚上可以更好入眠，但等我晚上回來發現被套還沒全乾，需要再烘乾一次，就跟他說其實為什麼要這麼麻煩，怎麼不送去乾洗店洗脫烘一次搞定，不用自已那麼辛苦樓上樓下忙進忙出的。\u003c/p>\u003cp>其實我的內心是感動及被愛的，但卻並沒有說出來讓老公知道我的感謝。\u003c/p>\u003cp>\u003cstrong>【A1+】(反思加工) \u003c/strong>\u003c/p>\u003cp>今天大家学习了積極性反饋技術，若时光倒流再回到同样的案例，该如何运用今天所学到的去給到正面反饋呢，时间为１—２分钟，请大家在小组讨论一下并写下加工自身案例的过程，小组讨论的时候，请每个人都尽量表达自己的想法，待会邀请一位学习者来将我们分享是如何将今日所学的技领运用到之前分享的案例。\u003c/p>\u003cp>利用積極性反饋加工失敗案例：\u003c/p>\u003cp>1. 描述行为 ：\u003c/p>\u003cp>a. 不带评判：不作简单的评判去区分行为的好坏或是对错\u003c/p>\u003cp>b. 具体描述：将行为用量化的方式呈现，如进行的第10分钟，在演讲时的第2主题...\u003c/p>\u003cp>2. 表达作用：\u003c/p>\u003cp>a. 说明影响：说明事实带来的影响，如演讲的主题带给我什么提升\u003c/p>\u003cp>b. 给予评价：对影响给予评价，如演讲带给自己的提升能产生什么好处\u003c/p>\u003cp>3. 表达感谢：\u003c/p>\u003cp>a. 分享感受：分享行为所带给你的良好感受，如这场演讲让我感到非常振奋人心\u003c/p>\u003cp>b. 总结行为：对此次行为作一个总结，如谢谢你带来这么精彩的讲解\u003c/p>\u003cp>\u003cstrong>【学习者分享】（反思加工的案例）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Carol：\u003c/strong>\u003c/p>\u003cp>1. 描述行为 ：\u003c/p>\u003cp>a.不带评判：老公花了3小时洗床单 + 烘干，让我们晚上可以更好入眠。\u003c/p>\u003cp>b.具体描述：洗床单花了1小时，烘干了1.5小时，铺床单花了0.5小时。\u003c/p>\u003cp>2. 表达作用：\u003c/p>\u003cp>a.说明影响：今天的棉被盖起来不仅暖而且还有淡淡的清香，真的好舒服哦。\u003c/p>\u003cp>b.给予评价：这些好味道让真的让我好放松，觉得今晚可以睡个好觉。\u003c/p>\u003cp>3. 表达感谢：\u003c/p>\u003cp>a.分享感受：今天休假还做这么多家事真的让我很感动、很开心。\u003c/p>\u003cp>b.总结行为：老公谢谢你这么辛苦做那么多家事这么宝贝我，来亲一个。\u003c/p>\u003cp>\u003cstrong>【点评与总结】\u003c/strong>\u003c/p>\u003cp>我们一起用掌声感谢CAROL的分享，老公幫忙洗衣後得到這樣積極的反饋，一定可以得到满满的成就感，讓夫妻关系洋溢着满满的幸福呢，現在再我们再回顾一下积极性反馈的步骤：\u003c/p>\u003cp>1. 描述行为 ：\u003c/p>\u003cp>a. 不带评判：不作简单的评判去区分行为的好坏或是对错\u003c/p>\u003cp>b. 具体描述：将行为用量化的方式呈现，如进行的第10分钟，在演讲时的第2主题...\u003c/p>\u003cp>2. 表达作用：\u003c/p>\u003cp>a. 说明影响：说明事实带来的影响，如演讲的主题带给我什么提升\u003c/p>\u003cp>b. 给予评价：对影响给予评价，如演讲带给自己的提升能产生什么好处\u003c/p>\u003cp>3. 表达感谢：\u003c/p>\u003cp>a. 分享感受：分享行为所带给你的良好感受，如这场演讲让我感到非常振奋人心\u003c/p>\u003cp>b. 总结行为：对此次行为作一个总结，如谢谢你带来这么精彩的讲解\u003c/p>\u003cp>在学习了積極性反饋後，我們能強化他人持續做出正向行為的動機，也讓他人可以在做出正向行為後獲得滿滿的成就感，但在另一種情況下，他人的行為對我們造成困擾，而我們必需要求他人作出改善呢？下一個學習片段和上一個片段呈現互補關係，這就進入到我們的片段二：\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":16846,"quote":"\u003cp>【拆頁二学习目标】\u003cbr>当完成此片段內容後，学习者能：\u003c/p>\u003cp> 在設定的場景中使用建設性反饋作出正向要求。\u003cbr>\u003cbr>【R阅读原书拆页】 1分钟\u003c/p>\u003cp>【片段主题】：建設性反饋技術AID\u003c/p>\u003cp>【片段来源】：《教練型管理者》P209-P210\u003c/p>\u003cp>假设你因为迟到了并错过一个非常重要的销售电话，从而使公司错过了一笔大单。这时，经理A是这样对你反馈的：“李主管，因为你今早晚进公司1个小时，客户打了5个电话都没有找到你本人，所以决定与竞争对手合作了。这给我们公司带来了重大的损失。”经理B是这样对你反馈的：“李主管，因为你今早晚进公司1个小时，客户打了5个电话都没有找到你本人，所以决定与竞争对手合作了。这不仅给我们公司带来了重大的损失，也影响了你个人的绩效，明明到手的两万元的销售提成没有了。”哪一个反馈对你更有触动？答案肯定是后者，因为跟自己的利益直接相关。因此，在阐述影响及后果的时候，更要描述对下属的影响及后果，这样才能真正引起对方重视。\u003c/p>\u003cp>最后，期待的行为和结果也同样必须具体、明确和可行，并且需要正向表达。所表达的期待是下属今后需要修正的行为，所以为了下属正确落实行动，期待的行为和结果必须足够具体、明确和可行。我们经常会碰到在下属完成了某项工作之后，结果却跟管理者的预期有很大的差距。当管理者向他提出困惑时，对方的回答大部分是：“噢，我不知道你有那样的要求。”很多员工的绩效结果与管理者的预期有差距，这与工作要求不明确直接相关。\u003c/p>","explains":"\u003cp>【What】（这是一个什么概念）\u003c/p>\u003cp>当对方作出的行为造成自己的困扰时，要作建设性反馈让对方理解错误的行为会影响他自身的利益，接着再正向提出具体的期待行为讓对方明确理解自己想要的方式。\u003c/p>\u003cp>【Why】（为什么要这么做，这么做有什么好处，不这么做有什么坏处）\u003c/p>\u003cp>一般做法：\u003c/p>\u003cp>一般在对方的行为造成自己的困扰时，我们会向对方描述着错误行为造成了什么冲击，却没有提到错误行为对行为者的利益有什么直接影响。\u003c/p>\u003cp>不这么做的坏处：\u003c/p>\u003cp>若不使用建设性反馈技术，行为者会没有改善错误行为的动机，因为对个人利益没有产生任何影响，自然就没有改善的动机，若能使用建设性反馈技术，便能让错误行为因反馈而停止，例如随地丢垃圾会造成环境脏乱，请大家配合不乱丢垃圾共造良好环境，若再加上若被举报者需要被罚款，自然能改善错误行为的发生次数。\u003c/p>\u003cp>【How】（具体怎么做呢）\u003c/p>\u003cp>建设性反馈：\u003c/p>\u003cp>描述行为（Act）：具体的描述对方的错误行为，例如小明这周总共迟到4次\u003c/p>\u003cp>冲击利益（Impact）：说明错误行为冲击到行为者的什么直接利益，例如你的迟到影响了同事要帮你接电话，更严重影响你自己的工作进度。\u003c/p>\u003cp>正向要求（Demand）：指明期待的行为和结果，例如希望你从下周开始提前10分钟到公司。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>原文中的案例是上司下属的关系，但是我們也來試一下生活中如何運用，因為这个方法也同样可以用在家人之间的关系，比如你因为忘记本周的家庭聚餐，结果使大家错过了一场美好的家庭聚会，这时父亲是这样对你说的：「儿子啊，因为你忘记了和大家晚上的聚会，我们打了3电话都没有找到你，所以我们就自己用餐了，这给我们带来很大的失落感。」 母亲是这样说的：「儿子啊 ，因为你忘记了和大家晚上的聚会，我们打了3通电话都没有找到你，所以我们就自己用餐了，这给我们带来很大的失落感，这影响了你的信用，明明我们可以一起拥有一个美好的家庭聚会的。」 哪一个说法会更有感觉？ 答案肯定是母亲说的话，因为和儿子的利益直接相关，所以，在说明后果的时候，更要提到对另一方的直接影响，这才能引起重视。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>大家一定会想建设性反馈太困难了，除了说出自己被影响到什么外还要提到这行为影响了对方的什么利益，然后才做出正向要求，但是若不进行建设性反馈去点出行为会影响对方什么直接利益，这就无法引起对方的重视，进而去完成后续提出的正向要求。\u003c/p>\u003cp>【Where】(适用场景)\u003c/p>\u003cp>适用于在要求他人行為改善的場景\u003c/p>\u003cp>不适用于表揚他人行為的場景\u003c/p>","interaction":"\u003cp>【A3】促动学习者现场演练（场景设计）10分钟\u003c/p>\u003cp>【设定场景】：\u003c/p>\u003cp>在我们学习到了建設性反饋后，现在我们来实际演练一下，请大家先听我给出的场景，待会我们会按照场景进行角色扮演：\u003c/p>\u003cp>你是业务部经理，你有一位同事叫小王，你们相约早上08：00一同出差拜访一位重要客户，公司的出差车08：00准时到了却迟迟不见小王的身影，你打了2通电话他也没有接，你感到有些焦急，担心拜访客户的时间会被延误到，看了看手表已08：10，正打算是不是自己先行坐车离去，小王的身影这才慌慌张张赶到...\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>请大家在小组内，由一人扮演經理，一人扮演小王，然后根据今天学习的&quot;建設性反饋&quot;作练习，可以再看一下知识图卡作回忆哦\u003c/p>\u003cp>建设性反馈：\u003c/p>\u003cp>描述行为（Act）：具体的描述对方的错误行为，例如小明这周总共迟到4次\u003c/p>\u003cp>说明冲击（Impact）：说明错误行为冲击到行为者的什么直接利益，例如你的迟到影响了同事要帮你接电话，更严重影响你自己的工作进度。\u003c/p>\u003cp>正向要求（Demand）：指明期待的行为和结果，例如希望你从下周开始提前10分钟到公司。\u003c/p>\u003cp>请大家先在小组内作角色扮演，结束后我会邀请一組来分享一下，如何运用今天的知识点进行沟通，这个环节有16分钟的时间，其中讨论时间是10分钟，分享的时间是6分钟，如果在讨论过程中有不清楚的地方可以向我示意哦。\u003c/p>\u003cp>那现在请大家在组内开始进行角色扮演吧，好，时间到，我们先请第一组来分享：\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>经理（Carol）：小王，这已经是你本周的第三次迟到了，刚才我拨打拨打了2次电话给你也没人接听。描述行为（Act）\u003c/p>\u003cp>小王（Ivy）：对不起经理，我早上睡过头了，刚在骑车赶路所以没有接听您的电话。\u003c/p>\u003cp>经理（Carol）：前二次的迟到影响了你的出勤记录及造成考核结果不佳，但毕竟影响的范围还不大。\u003c/p>\u003cp>但今天要去拜访的是公司极力争取拿下二亿大单的重要客户，现在因为你的迟到等会上高速公路正好赶上交通尖峰时刻，今天的拜访极有可能会赶不上，拿不下这笔订单业续达不成今年你的分红无望之外，还有可能因为失职而记过惩处！说明冲击（Impact）\u003c/p>\u003cp>小王（Ivy）：啊～我是真的～真的～非常的对不起（快要哭出来了）\u003c/p>\u003cp>经理（Carol）：我真的希望你能严肃正视看待准时上班这件事，改善这个不守时的行为，从下周起一个月内每天提早30分钟到公司来彻底改掉这个陋习。正向要求（Demand）\u003c/p>\u003cp>小王（Ivy）：好的，经理我一定会好好反省改善。\u003c/p>\u003cp>【点评与总结】\u003c/p>\u003cp>让我们用掌声来谢谢CAROL的分享，CAROL扮演的经理给出很好的示范，不只指出事实，更让小王可以深切体会到自己的什么利益会被冲击到，因而深切反省，避免再犯同样的过错 。\u003c/p>\u003cp>【A2】催化应用（分步催化）8分钟\u003c/p>\u003cp>【分步催化1】：（提供抽象情景）\u003c/p>\u003cp>接下来让我们设想一下，以下哪些场景可以使用建設性反饋，例如要求部下改善、要求朋友不要迟到、要求小孩听话、要求家人配合等等。\u003c/p>\u003cp>【分步催化2】：（加工成具体情境）\u003c/p>\u003cp>在“未来一周”当你遇到了上述場景，你覺得有必要作出要求，你想起了“建設性反饋”，请先写下你的目标，同时按步驟作分解，形成一个具体可达到目标的行动计划。\u003c/p>\u003cp>【提醒】\u003c/p>\u003cp>现在给大家5分钟的时间讨论一下然后应用今天所学，稍后请大家根据自己未来会遇到的场景写下自己的计划，之后也会请一位代表跟我们分享一下\u003c/p>\u003cp>这边还要提醒一下大家设定的目标要具体，不能只是决心，要有明确的时限还有可衡量可观测的预期结果，这里提供一个目标格式给大家参考。\u003c/p>\u003cp>目标：写下自己在未来什么时间和什么场景使用“建設性反饋”對他人提出正向要求\u003c/p>\u003cp>描述行为（Act）：具体的描述对方的错误行为，例如小明这周总共迟到4次\u003c/p>\u003cp>说明冲击（Impact）：说明错误行为冲击到行为者的什么直接利益，例如你的迟到影响了同事要帮你接电话，更严重影响你自己的工作进度。\u003c/p>\u003cp>正向要求（Demand）：指明期待的行为和结果，例如希望你从下周开始提前10分钟到公司。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>Carol分享：\u003c/p>\u003cp>1.描述行为（Act）：这星期的发文mail己发现有3个错误的地方了。\u003c/p>\u003cp>2.说明冲击（Impact）：你的发文代表人资部的文书质量，错误的内容影响了同事要帮你接电话\u003c/p>\u003cp>说明更正外，更严重的影响你自己的形象及工作效率。\u003c/p>\u003cp>3.正向要求（Demand）：希望你从现在起对外发文前必需自己先阅读三遍无误后，再由直属主管确认无误后才可以发出，如果一周后还没改善，就罚你请大家喝饮料。\u003c/p>\u003cp>结束语：\u003c/p>\u003cp>感谢今天各位小伙伴的陪伴，希望大家都能使用积极性反馈强化他人持续作出正向行为，使用建设性反馈让他人行为改善能符合自己的预期，期待学会的你能够，表扬他人，让人备感窝心；要求他人，让人想要配合改善。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1640693050000,"updated_at":1642393675000,"ria":true},{"id":12569,"topic":"有效的积极性反馈 — AAA反馈法","learn_goal":"","remark":"《教练型管理者》这本书。是一本讲述如何运用教练型方法进行管理的书籍。这本书在豆瓣上的评分是五星8.6分。教练型管理是以目标与成果为导向，以发掘员工内在潜力、促进员工良好行动和持续发展为目的的一种管理方法。掌握教练型管理方法，不仅能用于团队管理，而且也能够促进自己的成长，在日常工作生活中很好的激发自己及他人的意愿及行动。相比较其它同类书籍，这本书是由国内长期从事教练管理实战的专家编写的，书中的案例都来自于我们国内的实际情况，学习起来容易理解及落地实践。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"waynezhang","city":""},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>【开场】\u003c/p>\u003cp>大家好，我是张巍。我的三个标签是：\u003c/p>\u003cp>第一个标签：可能是五月风第二高龄的会员。\u003c/p>\u003cp>第二个标签：家在外地来青岛出差才能参加活动的五月风会员。\u003c/p>\u003cp>第三个标签：未来的三级拆书家。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>下面我将进行1-2的拆书练级，拆页的主题是：\u003cstrong>有效的积极性反馈 — AAA反馈法\u003c/strong>。预计时间15分钟。\u003c/p>\u003cp>在学习之前，我们先进行一下分组：前面这几位同学作为1组，后面这几位同学作为2组，后面我们会有小组内大家互相分享的环节。\u003c/p>\u003cp>下面我就正式开始带领大家进行拆书学习。\u003c/p>","ratings_count":1,"texts":[{"id":16490,"quote":"\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。这3个要素缺一不可，我们简称为AAA反馈技术。\u003c/p>\u003cp>积极性反馈的注意要点如下：\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地评判。\u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给与评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴们已经读完了，没读完也没关系，下面就由我来为大家来讲解一下AAA反馈法。\u003c/p>\u003cp>\u003cstrong>【I--Why】\u003c/strong>\u003c/p>\u003cp>首先，请大家听一下下面两种表扬，听完之后大家判断一下，哪一种表扬让你感受到了激励。听之前，先讲一下这两段话的背景信息：某个部门领导秦总安排下属同事小牛组织了一场小型的部门团建活动，活动进行的比较成功，结束之后，秦总碰到了小牛，对小牛进行了表扬。\u003c/p>\u003cp>第一种表扬方式：“小牛，今天的团建活动你设计的真不错，上级领导也觉得很好，说后面还会增加我们的预算，真辛苦你啦！明天中午我请你吃饭！”\u003c/p>\u003cp>第二种表扬：“小牛，今天的团建活动，我看到你设计了两个小游戏，这是咱们之前都没有的，参加的小伙伴们脸上都笑盈盈的，领导也专门找我说这种活动形式很好，下次可以给我们更多的团建预算。这次的团建活动你真的很用心，一定要给你一个大大的赞！明天中午我请你吃饭，给你庆功！”\u003c/p>\u003cp>答案是显而易见的，第二种表扬更让人感受到激励。\u003c/p>\u003cp>但日常工作和生活时，我们对他人的表扬往往都是“做的不错、太棒了、真厉害、辛苦你啦“等等这些简单的表扬，对方听了以后的感受，往往就是没什么感受，听多了甚至就像是在走形式。AAA反馈法就能很好的解决这个问题，它能让我们对被反馈者产生积极正面的影响。所谓“女为悦己者容，士为知己者死”某个方面就是AAA反馈法运用成功的最高境界。\u003c/p>\u003cp>\u003cstrong>【I--What】\u003c/strong>\u003c/p>\u003cp>AAA反馈法，是教练型管理中的一个有效积极性反馈的方法，它通过三个步骤的有效表达，满足了人们被欣赏、被认可的心理需求，从而激发强化对方的内在动力，并在自己和对方之间建立起良好的人际关系。\u003c/p>\u003cp>\u003cstrong>【I--How】\u003c/strong>\u003c/p>\u003cp>AAA反馈法有三个A步骤。 \u003c/p>\u003cp>第一个A是描述行为和事实（Act）\u003c/p>\u003cp>指的是：要讲出对方做了哪些具体的行为及事实。讲好第一个A的关键词是：观察、具体、客观。行为的描述要具体，事实的描述要客观，这样的反馈就会有可信度，而要做到具体和客观，就要我们要观察好。\u003c/p>\u003cp>第二个A是阐述影响及评价（Actor）\u003c/p>\u003cp>指的是：阐述出对方的行为和事实对你或他人产生了那些积极正面的影响，并讲出自己的正面评价。讲好第二个A的关键词是：扩大化，意思是我们在讲述这些积极正面的影响时，要尽可能的找出所有能影响到的群体，从个人扩大到团队，甚至更大的范围。描述出的影响越大，对方就会越觉得有成就感。\u003c/p>\u003cp>第三个A是给出赞赏（Appreciation）\u003c/p>\u003cp>指的是：最后，对被反馈者表示欣赏和感谢。做好第三个A关键词是：真心。要让对方感到你是发自内心的欣赏和感谢。\u003c/p>\u003cp>\u003cstrong>【I--Where】\u003c/strong>\u003c/p>\u003cp>AAA反馈法特别适合当对方做出正确行为时进行反馈。同时，它的使用有一定的时效要求，错过了时间再说的话，效果就会大打折扣。\u003c/p>\u003cp>\u003cstrong>【举例说明】\u003c/strong>\u003c/p>\u003cp>下面我们回想一下开头的例子，秦总对小牛的第二种表扬，就完全符合AAA反馈法，我们一起对照看一下。\u003c/p>\u003cp>秦总先说：今天的团建活动，我看到你设计了两个小游戏，这是之前没有的，参加的小伙伴们脸上都笑盈盈的。\u003c/p>\u003cp>这句话是第一个A：描述出了行为和事实。\u003c/p>\u003cp>接着秦总说：领导也专门找我说这种活动形式很好，下次可以给我们更多的团建预算。\u003c/p>\u003cp>这一句是第二个A：阐述影和评价。\u003c/p>\u003cp>最后秦总说：这次的团建你真的很用心，一定要给你一个大大的赞！明天中午我请你吃饭，为你庆功！\u003c/p>\u003cp>这是第三个A：给出赞赏。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1--激活学习者经验】\u003c/strong>\u003c/p>\u003cp>以上，就是我对AAA反馈法的讲解，相信大家已经很清楚的了解到了AAA反馈法。下面，我们用3分钟的时间进行一下小组分享。\u003c/p>\u003cp>首先，请每位同学回想一下：在过去的一个月里，自己关于表扬相关的经历，可以是成功案例，也可以是一个失败的案例。大家想好之后，在自己的小组内进行分享，最后我们我们请1位小伙伴来上台分享一下。\u003c/p>\u003cp>这里提醒一下大家，分享时请按照事件记录六要素来呈现，即：时间、地点、人物、起因、经过、结果。好的，现在就请大家进行小组分享吧。3分钟后我们请一位小伙伴上台来分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>学习者秦同学发言：\u003c/p>\u003cp>这个月月初舵主和我做了入会的面谈，中间有个细节打动了我。后续第二次见面时，我对舵主进行了表扬。回想起来自己的表扬和AAA反馈法，表扬大致如下。\u003c/p>\u003cp>1、舵主在面谈前准备了非常详尽的资料。\u003c/p>\u003cp>2、自己非常认可，并主动给家人讲述了此事，也得到了家人们对舵主认真精神及对拆书帮的认可。\u003c/p>\u003cp>3、自己由衷的感谢舵主为拆书帮公益活动的付出。\u003c/p>\u003cp>谢谢秦同学的分享。通过他的分享，让我们更好的理解了AAA反馈法。\u003c/p>\u003cp>\u003cstrong>【A2--催化学习者应用】\u003c/strong>\u003c/p>\u003cp>我们拆书帮的理念是学以致用，下面就请大家写一下今天拆书学习的应用便签：在未来，自己将如何具体运用AAA反馈法来进行表扬。\u003c/p>\u003cp>有三个注意事项提醒一下大家：\u003c/p>\u003cp>首先，请对照AAA反馈法的三个A来列出你的具体行动计划。\u003c/p>\u003cp>其次，要写出行动计划的具体时间，是本周还是下周，要有明确的时间期限。\u003c/p>\u003cp>第三，这个行动计划要列出明确的目的、要列出可衡量的预期结果。\u003c/p>\u003cp>好的，现在就请大家用3分钟来完成自己的应用便签。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>3分钟时间到了，大家的便签基本都完成了，非常好！\u003c/p>\u003cp>最后，我就用AAA反馈法来表扬一下大家。\u003c/p>\u003cp>刚刚我注意观察了大家的学习，虽然这只是比较简单的一级拆书过级，但在座的每一位小伙伴都非常认真，在听讲时聚精会神，还做了笔记；在独立思考时，便签都写的满满的；在讨论时，都非常踊跃的分享自己的经验；不仅让今天这场拆书学习取得了成功，更彰显了我们五月风会员的高素质，有了在座的各位，相信定能让我们五月风分舵从玄武升级为朱雀、青龙，成为全国最强的分舵！大家都是最棒的！让我们一起为自己鼓掌吧！\u003c/p>\u003cp>今天1-2拆书学习就到此结束了，谢谢大家！\u003cbr> \u003cbr> \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1635344114000,"updated_at":1635605033000,"ria":true},{"id":12105,"topic":"教练型管理者的积极反馈技术  ","learn_goal":"","remark":".","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"邹治","city":"广州市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>大家好，我是邹治，感谢大家参加今天的拆书学习。那么在开始之前，请允许我先用三个标签介绍下自己：第一个标签是不安份的90后青年；\u003c/p>\u003cp>第二个标签是喜欢赚钱的90后；\u003c/p>\u003cp>第三个标签是大叔；\u003c/p>\u003cp>总结一下：我是一位不安分喜欢赚钱的90后大叔。\u003cbr>好的，大家已经认识我了，我们就开始今天的拆书学习吧。首先我们今天的学习分为2步，第一部分我会用\u003c/p>\u003cp>2分钟的时间跟大家介绍拆书帮，以便于让大家知道你参加的是什么。\u003c/p>\u003cp>（一）关于拆书和拆书帮：\u003c/p>\u003cp>提问：大家平时看书过程中会遇到哪些阻碍？（0.5分钟）\u003c/p>\u003cp>好的，谢谢大家！在之前啊，我也跟大家一样学不进去、学了不知道怎么用、害怕自己不能坚持……\u003c/p>\u003cp>但自从掌握一种学习技巧后，觉得原来读书如此简单。怎么做到的呢？——拆书！\u003c/p>\u003cp>可能大家会好奇，什么是拆书呢？（可讲可不讲，看时间）\u003c/p>\u003cp>“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以\u003c/p>\u003cp>知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法:个\u003c/p>\u003cp>人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果;组织学习的应用是一位拆书家拿一本\u003c/p>\u003cp>书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创\u003c/p>\u003cp>造的价值不亚于一位培训师。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群,表现为各地的拆书帮分舵(也叫拆书帮俱乐部)书帮分舵是非营利\u003c/p>\u003cp>青年的组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>（二）拆《教练型管理者》\u003c/p>\u003cp>什么是教练呢？\u003c/p>\u003cp>“教练技术”是通过方向性和策略性的有效问题，激发被教练者向发掘自己的潜能，向外探求更多的可能性，\u003c/p>\u003cp>令被教练者更加快捷、容易的达到目标。\u003c/p>\u003cp>本书综合作者俞清在世界知名企业的教练实践和教学经验，力求用严谨的内容结构、简明的讲解风格、实用的\u003c/p>\u003cp>工具方法和生动的情境案例，让读者能够在较短的时间内成为一名优秀的教练型管理者。\u003c/p>\u003cp>更重要的是，本书介绍的技术、方法和工具都来自真实的企业管理实践，是经过检验的并且正在被先进企业系\u003c/p>\u003cp>统运用的管理实践。只要你做到，你就会看到效果。本书也同样适合有志于成为专职企业教练的读者。\u003c/p>","ratings_count":1,"texts":[{"id":16030,"quote":"\u003cp>教练型管理者的积极反馈技术——AAA\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价\u003c/p>\u003cp>（Actor）；三是表示欣赏和感谢（Appreciation）。\u003c/p>\u003cp>这3个要素缺一不可，我们简称AAA反馈技术，如下图所示：\u003c/p>\u003cp>积极性反馈的注意要点如下：\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地\u003c/p>\u003cp>评判。\u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给与评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这就是一个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。\u003c/p>\u003cp>已经阅读完的小伙伴请举手示意一下，没有阅读完的小伙伴注意再阅读30秒……好的，我们来看看拆页的方法具体是怎么做的。\u003c/p>","explains":"\u003cp>【What】：是什么？\u003c/p>\u003cp>AAA反馈技术是一种非常有效的反馈技术，具体步骤由:\u003c/p>\u003cp>1）描述行为和事实(Act)\u003c/p>\u003cp>2）阐述影响及评价(Actor)\u003c/p>\u003cp>3）表示欣赏和感谢(Appreciation) 3个要素构成\u003c/p>\u003cp>【How】：具体步骤\u003c/p>\u003cp>1）描述行为和事实(Act) ; .\u003c/p>\u003cp>通过观察法，将被观察者的行为和事实输出给观察者确认是否正确，在这个过程中注意不能添加任何自己主观意识的内容，不添加任何色彩。\u003c/p>\u003cp>2）阐述影响及评价(Actor) ; .\u003c/p>\u003cp>影响扩大化:将事件行为和事实无限放大，如果把正向积极影响越扩大化，对方就越觉得有成就感，借此可以激发对方的动力，我们也把它称之为“赋能”。当然了，这个方法不局限于个人，也可以是团队。\u003c/p>\u003cp>3）表示欣赏和感谢(Appreciation)\u003c/p>\u003cp>结尾的时候能够共情,感动身受的对对方表示发自内心的欣赏和感谢，从而再次加深信任，为对方赋能。\u003c/p>\u003cp>【why】：为什么？\u003c/p>\u003cp>由此可见，AAA反馈技术方便简洁，步骤简单，通俗易懂，重反映事实和行为，交流中更容易被对方接受，更利于有效的沟通。\u003c/p>\u003cp>【where】适用场景\u003c/p>\u003cp>AAA技术无论在工作中，还是家庭里，但凡跟别人沟通都可以用的上，其操作方法简洁方便，运用者可以是管理层、也可以是普通小白、还可以是各种身份的人士。\u003c/p>","interaction":"\u003cp>A1部分\u003c/p>\u003cp>结合今天学习到的，我立马想到了2017年在山西太原做商学院负责人的时候因为A君迟到而衍生的一系列事情。\u003c/p>\u003cp>有一次我组织开会A君迟到了，面对他的迟到，我非常生气，于是就随口一句：“怎么又是你迟到啊，你怎么总是迟到！”\u003c/p>\u003cp>当我说完这句话后A君直接当场跟我顶起来了，结果闹的非常不愉快！\u003c/p>\u003cp>所以在学完AAA技术，我觉得自己当时是带着评判去的，描述行为并不中立，因为加了自己主观意识，所以才有了这样的结局呀！\u003c/p>\u003cp>A2部分\u003c/p>\u003cp>以往我在做培训带团队的过程中很少会去表扬我们同事，比如有的同事超额完成培训期望值我也没有去表扬认可他，那么学完AAA技术之后，我觉得12月份再遇见那些同事，我可以这样做：\u003c/p>\u003cp>1）遇见超额完成期望值的同事，我会在结束后第一时间电话庆祝，具体步骤如下：\u003c/p>\u003cp>描述行为和事实：小王，因为你这次的出色表现和付出让总裁对我们培训部刮目相看，产生极大认可。\u003c/p>\u003cp>阐述影响及评价：这一次培训让我们在公司所有部门中出彩夺目，公司领导也会抽出更多的预算补贴到我们培训部，以后在培训的过程中我们更有底气了。\u003c/p>\u003cp>表示欣赏和感谢：这么短的时间内从设计到研发再到面授，我知道你背后一定付出了心酸和汗水，非常感谢你这么负责认，我也相信未来有你的持续努力，我们培训部会越来越好！\u003c/p>\u003cp>针对优秀的同事可以用AAA技巧，那针对那些没完成目标的同事我们又是否可以运用AAA技术呢？\u003c/p>\u003cp>答案是：当然可以！\u003c/p>\u003cp>且听我说：\u003c/p>\u003cp>描述行为和事实：小李，针对这一次的培训虽然没做到领导想要的效果，但是为了做课件，你这段时间是公司每天来的最早，走的最晚的那个，这一切我都是看在眼里的！\u003c/p>\u003cp>阐述影响及评价：因为你这种努力，上进的行为给我们部门树立了一个好的榜样，让很多老员工因为你这种拼搏的精神而触动反思自己。\u003c/p>\u003cp>表示欣赏和感谢：所以我很庆幸在我的部门有你这么一位任劳任怨、负责认同事，我相信假以时日你一定会赢得掌声，也会成为我们培训部的骄傲！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1628736954000,"updated_at":1629175686000,"ria":true},{"id":11803,"topic":"赞美力-积极性反馈技术","learn_goal":"","remark":"拆书家拆书晋级","level":"TF1-1","duration":12,"status":30,"type":0,"chaishujia":{"username":"星辰陈","city":"合肥市"},"club":{"name":"合肥霸都分舵","city":"合肥"},"prologue":"\u003cp>开场：\u003c/p>\u003cp>大家好，我是今天的分享人：陈振兴。我用三个标签来介绍一下我自己，分别是：奶爸、项目管理专家、拆书爱好者。为什么是这三个标签呢，首先，当下刚升级为父亲，目前生活中原有的空闲时间都被娃给占据了，要做好一个爸爸。项目管理专家，是我的目标之一，目前还在努力奋斗着。拆书爱好者，这是一个比较执着而又尴尬的标签。因为接触拆书是14年前，那时还没有分舵，分舵成立后也只是参加几次，一直也没有能来定级，心中一直执着着要成为拆书家，所以今年给自己一个压力和目标，争取实现它。\u003c/p>\u003cp>\u003cstrong>拆书帮介绍\u003c/strong>\u003c/p>\u003cp>下面我为大家介绍拆书、RIA便签读书法和拆书帮。\u003c/p>\u003cp>赵周老师的《这样读书就够了》是拆书帮及拆书法的理论基础。\u003c/p>\u003cp>拆书是一种学习方法，目的是提升学习能力解决实际问题，尤其是适合成人学习。培训学习中有一个法则是721法则，成人学习成长的70%来自实践，只有当所学与实践结合才能带来成长。拆书法，强调，以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的应用。\u003c/p>\u003cp>运用最多的是RIA便签读书法，让人读一本书就能达到参加同主题培训的效果。便签学习法包含3张便签，R便签是书中打动你的某个片段，I便签，用自己的话重述原文；A1便签，联想过去的经历；A2便签，应用规划未来。\u003c/p>\u003cp>在集体学习时，是一位拆书家，拿一本书，加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部），拆书帮分舵是非营利性青年自组织。其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>今天我给大家带来的片段来自于唐渊的《教练型管理者》一书，因为我们是线上定级，所以我把今天拆书帮的原文片段给大家读一下，读完后我们一起来学习。\u003c/p>","ratings_count":1,"texts":[{"id":15746,"quote":"\u003cp>教练型管理的积极性反馈技术——AAA总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。\u003c/p>\u003cp>积极性反馈的注意要点如下：\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地评判。\u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给与评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。\u003c/p>","explains":"\u003cp>好的，那么以上就是今天要学习的原文片段，下面我来讲解一下这个片段。\u003c/p>\u003cp>【What】这个片段告诉我们，在日常生活、尤其是工作中如何通过积极反馈的方式为他人赋能，让他人感觉到行为有价值、有意义。\u003c/p>\u003cp>【Why】我们为什么要积极反馈呢？为了让他人更好的执行和保持良好行为，也是为了促进双方关系进一步维系和发展。基本上没有人做了一件事或表现一个行为后，不希望得到响应。批评的负面反馈会让人退缩，漠视会让人觉得无趣，影响双方互动。\u003c/p>\u003cp>【How】积极反馈的三个步骤。\u003c/p>\u003cp>1 客观描述对方的具体行为和事实。行为是当下真实发生的，客观的描述不加判断。如“昨天你将常用流程文档进行了梳理，设计了一个可以直接调用的模板。”\u003c/p>\u003cp>2 阐述行为和事实所具有的影响及评价。阐述的范围最好扩大到对周边的影响，而非仅是其个人。人的基本心理需求之一有联结，通过与周边产生联系来满足其心理需求，增加其满足感。如“这个模板不仅是你在编制流程文档时可以提高工作效率，也为本部门，甚至是公司其他部门同事提供了一个帮助，他们的工作效率也将因此提升。这个非常有价值，做得不错。”\u003c/p>\u003cp>3 表示由衷的欣赏和感谢。如“xx，你这次的工作方式和思考能以效率提升为切入点，对后期其他工作改进也是不错的启示，请继续保持，再接再厉。此外也替团队感谢你的贡献。”\u003c/p>\u003cp>【Where】在人际交往中，如何让他人愿意、喜欢上做某事，持续的坚持某个行为，那就不断给他积极性反馈。这不仅是在工作中，在夫妻关系、亲子关系中都是可以运用的。只要你觉得对方的行为是正面的、有价值的，就可以去使用。但这个方法不适合在未发生的行为引导上，也不适合你不想其保持的行为上。个人运用中注意要客观真实、真诚表达其影响和感谢。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>好的，那么以上就是今天要学习的原文片段，下面我来讲解一下这个片段。\u003c/p>\u003cp>【What】这个片段告诉我们，在日常生活、尤其是工作中如何通过积极反馈的方式为他人赋能，让他人感觉到行为有价值、有意义。\u003c/p>\u003cp>【Why】我们为什么要积极反馈呢？为了让他人更好的执行和保持良好行为，也是为了促进双方关系进一步维系和发展。基本上没有人做了一件事或表现一个行为后，不希望得到响应。批评的负面反馈会让人退缩，漠视会让人觉得无趣，影响双方互动。\u003c/p>\u003cp>【How】积极反馈的三个步骤。\u003c/p>\u003cp>1 客观描述对方的具体行为和事实。行为是当下真实发生的，客观的描述不加判断。如“昨天你将常用流程文档进行了梳理，设计了一个可以直接调用的模板。”\u003c/p>\u003cp>2 阐述行为和事实所具有的影响及评价。阐述的范围最好扩大到对周边的影响，而非仅是其个人。人的基本心理需求之一有联结，通过与周边产生联系来满足其心理需求，增加其满足感。如“这个模板不仅是你在编制流程文档时可以提高工作效率，也为本部门，甚至是公司其他部门同事提供了一个帮助，他们的工作效率也将因此提升。这个非常有价值，做得不错。”\u003c/p>\u003cp>3 表示由衷的欣赏和感谢。如“xx，你这次的工作方式和思考能以效率提升为切入点，对后期其他工作改进也是不错的启示，请继续保持，再接再厉。此外也替团队感谢你的贡献。”\u003c/p>\u003cp>【Where】在人际交往中，如何让他人愿意、喜欢上做某事，持续的坚持某个行为，那就不断给他积极性反馈。这不仅是在工作中，在夫妻关系、亲子关系中都是可以运用的。只要你觉得对方的行为是正面的、有价值的，就可以去使用。但这个方法不适合在未发生的行为引导上，也不适合你不想其保持的行为上。个人运用中注意要客观真实、真诚表达其影响和感谢。\u003c/p>\u003cp>A2\u003c/p>\u003cp>目标:本周在衣服到货后，再和爱人沟通下，积极反馈这次的行为\u003c/p>\u003cp>行动:\u003c/p>\u003cp>本周衣服到货后，我会对老婆说：“亲爱的，你能在宝宝多次溢奶后想到给他多买几件衣服，来保证他一直有干爽的衣服可穿，避免了他睡的不踏实，湿湿的衣服也可能引起湿疹什么的【客观描述对方的行为和事实】。想的就很周全，让宝宝和我们都避免了很多麻烦，而且买的衣服也不贵，也挺经济适用的，基本上从避免的不良情况，产生的好处都思考到了，棒棒的【阐述行为带来的影响】。谢谢你为家庭的付出【表示由衷的感谢】。”\u003c/p>\u003cp>今天的分享就到这里。希望各位小伙伴在未来的生活和工作中也可以用“积极反馈”的三步方法来解决生活或者工作中需要引导和赋能他人的事情，从中收益。本次拆书到此结束，感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1624528303000,"updated_at":1624583458000,"ria":true},{"id":11777,"topic":"如何进行积极性反馈？","learn_goal":"","remark":"在沟通过程中，如何进行沟才会通呢？如何积极反馈呢？在沟通过程中，如何激发对方的能动性朝积极工作方面发展？如何通过语言沟通，让对方感受得以认可？通过此次学习，你将成为优秀管理者。将学会积极反馈，让对方朝正确的方面发展。","level":"TF2-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"润芽心理","city":"保定市"},"club":{"name":"保定直隶分舵","city":"保定"},"prologue":"\u003cp>各位亲爱的小伙伴们，大家下午好，我是孙立双，一位心理学爱好者，非常开心又跟大家相遇在拆书帮，继续我们的大怪升级，今天我挑战2-1。\u003c/p>\u003cp>首先在开始之前我们先分一下组，坐在我左边4人一组，右边的4人为第二组，还请同一小组的小伙伴抬头相互示意一下，方便接下来大家进行组内讨论和分享。\u003c/p>\u003cp>希望小伙伴们在跟我完成这次RIA现场学习后，能把教练型管理技术不仅能运用于自己的工作，也能迁移到爱人、孩子人日常沟通中，能够避免主观臆断的评价习惯，而是用今天所学的积极反馈技术，达到强化赋能目的。\u003c/p>\u003cp>我今天给大家带来的拆页选自《教练型管理者》第260页。我今天分享的主题是：积极性反馈技术，也称AAA技术。\u003c/p>\u003cp>这本书在大量实践和教学经验的基础上，简明的讲解风格、实用的工具方法和生动的情境案例，让读者能够在较短的时间内熟练掌握优秀管理者的技能。只要你做到，你就会看到效果。\u003c/p>\u003cp>本书则作者金慧英，绩能教练®创始人，拥有多年跨国公司运营管理经验，在教练能力培养等方面有着丰富的理论和实战经验，是企业教练领域的成功实践者。对处于主导地位的个人也有借鉴作用。\u003c/p>\u003cp>在沟通过程中，如何积极反馈呢？在沟通过程中，如何激发对方的能动性朝积极工作方面发展？(这本书的价值)如何通过语言沟通，让对方感受得以认可？（片段的价值）这本书可以找到答案。通过阅读这本书，你将成为优秀管理者。\u003c/p>\u003cp>学习完本片段，你将学会积极反馈，让对方朝正确的方面发展。\u003c/p>","ratings_count":1,"texts":[{"id":15718,"quote":"\u003cp>教练型管理的积极性反馈技术：\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成:一 -是描述行为和事实(Act) ;二是阐述影响及评价(Actor) ;三是表示欣赏和感谢( Appreciation)。\u003c/p>\u003cp>这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。\u003c/p>\u003cp>积极性反馈的注意要点如下:\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地评判。\u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给与评价。描述或评价的影响不仅是人的，还要针对团队和整体。我们越是把这个影响。百贝化，对方越觉得有成就感,这也是一-个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>最后，表示由衷的欣赏和感谢\u003c/p>","explains":"\u003cp>我看到大家基本阅读完了，我用自己的语言和大家分享一下这个片段。\u003c/p>\u003cp>这个片段告诉我们其实回应反馈也是有方法的，按照下面的方法，可以达到有效反馈，真正的激励对方积极行动。这三个步骤是：“描述事实和行为”、“阐述影响和评价”、“表示欣赏和感谢”。\u003c/p>\u003cp>大家都知道，反馈在谈话中中起着非常重要的作用，只有反馈合理、积极，双方的关系更加融洽，才会朝着我们期望的方向发展。\u003c/p>\u003cp>如果我们在对方表现有正向行为时，不使用积极反馈技术，很难调动对方的积极性，正向行为也不会固化，接近目标的时间就会更漫长，完成度也有可能达不到我们的期望目标。\u003c/p>\u003cp>积极性反馈技术首先使用了对方做出正向行为或产生积极的影响时做出。第二适用于具有上下级关系和处于主动地位的人。\u003c/p>\u003cp>（常见的做法）但是在现实生活中，我们常见的做法是：看似在回应，但对方感觉不到成就感，无法强化正向行为。\u003c/p>\u003cp>（举个反例）我举个例子：\u003c/p>\u003cp>前几天，我爱人从娘家带回一些露露饮料，回到家拿一个给了我一瓶，当我感觉比较凉时，就在放到了一边，什么也没有说。随后我爱人自己喝起来喝了，也没说话。\u003c/p>\u003cp>那么，我们该如何正确反馈呢呢？我们来看一下积极反馈的步骤：\u003c/p>\u003cp>1、描述行为和事实。也就是把自己观察到的行为和事实表达出来，需要仔细的观察。\u003c/p>\u003cp>2、阐述影响和评价。基于事实会对我们有什么影响，我们对行为和事实的评价是什么。\u003c/p>\u003cp>3、表示欣赏或感谢。 表达自己的情感态度。\u003c/p>\u003cp>回到刚才的例子，我们反思一下，其实我我没有很好的反馈。\u003c/p>\u003cp>如果运用积极性反馈技术，我应该怎样说呢？我可以这么说：\u003c/p>\u003cp>你刚回来就把露露饮料给我一评，我正好有点渴了，你真是及时雨宋江，你很住乎我，真是个好妻子。\u003c/p>\u003cp>(正反例结果对比)\u003c/p>\u003cp>你看，前后两次不同的反馈，得到的效果一定不同，后者更会激发爱人的正向关心行为。\u003c/p>","interaction":"\u003cp>。拆书家提问设计（逐字稿）\u003c/p>\u003cp>现在，请小伙伴们在脑中搜索一下，就像回放电影中的某个画面一样，回想下最近一次的下属或亲人的正向行为，有没有正确的反馈？\u003c/p>\u003cp>比如说类似的，\u003c/p>\u003cp>周五，一个同事把照毕业照的钱收齐了，微信问校长交给谁？\u003c/p>\u003cp>孩子周六写完了作业，才去打球，我们平时如何说的？\u003c/p>\u003cp>丈夫今天下班回到家的一刻，你们如何沟通的？\u003c/p>\u003cp>请想一想，在小组内交流，时间为1分钟，小组交流结束后，我们请个小伙伴分享。\u003c/p>\u003cp>好的，我看到大家基本讨论完了，现在请小伙伴来跟我们分享一下，\u003c/p>\u003cp>下面请 小伙伴分享，时间为2分钟\u003c/p>\u003cp>学习案例记录\u003c/p>\u003cp>黄姐：看到孩子的成绩，我给他把把学校、市内、省内排名排列了一下，表扬他进步了。\u003c/p>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>刚才黄姐的案例有些积极性性反馈的味道了，很不错了，现在结合今天的方法反思一下，，你如果利用我们的积极性反馈技术，该如何反馈呢？请大家用2分钟的时间写下具体的做法。\u003c/p>\u003cp>好的，我看到大家都写完了，下面请大家在组内分享交流，每个人1分钟，总共给大家2分钟的时间，小组交流结束后，我们请一位小伙伴分享。\u003c/p>\u003cp>请 分享，时间为2分钟。\u003c/p>\u003cp>学习案例记录\u003c/p>\u003cp>王姐：儿子你的二模成绩到了589分，这样你不仅能进入不错的一本大学，还为你弟弟树立了榜样，妈妈很为你高兴，我们今天晚上庆祝一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1624324127000,"updated_at":1624324370000,"ria":true},{"id":11014,"topic":"【郑州轩辕NO.226期】周日主题：“积极性反馈技巧”+“游戏：猜猜你是谁？”","learn_goal":"","remark":"《教练型管理者》综合作者在世界知名企业的教练实践和教学经验，让读者能够在较短的时间内成为一名优秀的教练型管理者。书中介绍了一个很好的方法“积极性反馈技巧”，通过这种表扬方法，在肯定对方行为的同时，激发对方的内在动力和意愿度，强化正确行为的持续性。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"肖利","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp> \u003cstrong>【自我介绍】\u003c/strong>大家好，我是今天的拆书家肖利，首先用三个标签介绍我自己：第一，二级拆书家；第二，7年企业HR；第三，宝妈。\u003cbr> \u003cstrong>【学习目标】\u003c/strong>学完后，能够使用积极性反馈的方法，针对对方的具体行为予以表扬，激发对方的内在动力，强化正确行为。\u003cbr> \u003cstrong>【现场分组】\u003c/strong>为了达到更好的学习效果，我们先进行现场分组，从我右手边开始数2人一组，谢谢大家！\u003cbr> \u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>现场的小伙伴有没有过这样的经历：明明是在表扬对方，但对方并不领情。反而觉得你有可能仅仅是在应付或恭维，甚至是怀疑。\u003cbr> \u003cstrong>【提问】\u003c/strong>如果对方做的好，到底要不要表扬？（学习者回答：要）\u003cbr> \u003cstrong>【影响】\u003c/strong>俗话说“女为悦己者容，士为知己者死”，每个人内心都有被认可的需求，没有及时给予表扬，对方会觉得被“漠视”，积极性和自信心会慢慢下降；但表扬过度或不当，又会让对方觉得假模假样。\u003cbr> \u003cstrong>【解决】\u003c/strong>《教练型管理者》综合作者在世界知名企业的教练实践和教学经验，让读者能够在较短的时间内成为一名优秀的教练型管理者。书中介绍了一个很好的方法“积极性反馈技巧”，通过这种表扬方法，在肯定对方行为的同时，激发对方的内在动力和意愿度，强化正确行为。\u003cbr> \u003c/p>","ratings_count":2,"texts":[{"id":14925,"quote":"\u003cp>下面请大家花一分钟时间做一个简单的测试，看看在表扬这件事上大家的能力大小。你们面前的自测表中有5个题目，请按照1到6分的标准给自己打分，1代表完全不符合，6代表完全符合。请大家阅读自测表，根据自己的实际情况为自己打分，并计算总分。\u003c/p>\u003cp>（表格1）\u003c/p>\u003cp>（询问）请问各位总分分别得了多少分？\u003cbr> 学习者回答：\u003cbr> 屈冠华：26分\u003cbr> 王楠：17分\u003cbr> 孔亚琪：17分\u003cbr> 张霞：20分\u003cbr> 通过这个自测表，大家可以简单地了解自己在表扬时激发对方的内在动力和意愿的能力：分数在25分以上，说明你很善于表扬；得分在10分以下，说明亟需学习表扬的技巧；得分在10-25之间，说明你具有一定的表扬能力，可以更上一层楼，做得更好。\u003cbr> 接下来请大家用2分钟的时间阅读拆页，我们一起学习用“积极性反馈技术”让表扬更得他心，阅读完成后的小伙伴请举手示意我。\u003c/p>\u003cp>\u003cstrong>【片段来源】\u003c/strong>《教练型管理者》P96-97\u003cbr>\u003cstrong>【主题】\u003c/strong>积极性反馈技术\u003cbr>\u003cstrong>【原文】\u003c/strong>\u003cbr> 那么我们究竟该如何进行有效的积极性反馈呢？如果此刻让你回想一下你最有印象的一位老师并表扬他，那么你会如何表扬呢？很多人是如此表扬的：\u003cbr> 老师，您的课讲得特别棒！\u003cbr> 老师，您特别专业！\u003cbr> 老师，您的课逻辑性特强！\u003cbr> 老师，您的课幽默、风趣，全程没有尿点！\u003cbr> “您是我见过的最优秀的老师，没有之一，下次我还要上您的课！\u003cbr> 如果你是这位老师，在听到这样的反馈后会有什么样的感受?第一感觉肯定很开心，还挺兴奋的。因为这些话用的都是溢美之词，你听到后当然开心。但是，冷静下来，你不知道他说你“讲得特别棒”，到底棒在哪里。你也不知道他说你“专业”，到底专业在哪里。你甚至慢慢会感觉到“幽默、风趣”应该是每位讲师的基本素质，感觉“全程没有尿点”有点儿夸张，感觉“下次我还要上您的课”好像是应付。想到这里，你的开心、兴奋会瞬间消失，感觉大家只是在恭维你，给你面子而已。\u003cbr>假设有一位学员给了你这样的一段表扬信：\u003cbr>亲爱的老师，您提前40分钟来到我们的培训室。在课程中，为了照顾到我们全场80位学员，您不停地走到每个小组前。从您生动的肢体语言和神态上，我就能够感受到您对教学的投入程度。课间休息时，您却没有休息，还将每组问题逐一归类和分析；课间练习时，您既能引导大家活跃思考，又能及时把握方向防止大家跑偏，还能在交流问题的过程中快速发现问题并给出专业的指导。只有对自己的课程有绝时的信心且对学员抱有很高的期望才能如此专注。您的勤勉和教业令我由衷感叹！正因为您忘我的付出，我们的课堂氛围才能如此活跃，80位学员才能收获满满的落地的管理实操工具。今日，您的言传身教令我获益良多，不光是知识上的收益，也包括专业度、勤勉和应变的启迪，再次感谢您的付出。\u003cbr>看完这段表扬信后，你的内心应该是满满的感动。我相信这份感动并不只是因为这封表扬信的字数多，更是因为学员对老师细节的关注、认可和感激。你的内心肯定油然升起一股使命感：为了不辜负这样的反馈，我要用尽全力更加服务好这批学员。这就是积极性反馈的价值，不仅可以激发对方的内在动力和意愿度，还可以强化该行为的持续性。\u003cbr> \u003cbr> \u003cbr> \u003c/p>","explains":"\u003cp> 日常生活中我们常见的表扬方式有两种，一种是直接给予评价的表扬，如：你真好、你真棒、你真幽默等；还有一种是积极性反馈的表扬，以具体的行为为依据，给予评价和表扬。\u003cbr> 那么，各位，如果你是老师，更喜欢直接给予评价的表扬还是积极性反馈的表扬？\u003cbr> （学习者回答：积极性反馈）\u003cbr> 拆页中提到的直接给予评价的表扬带来的积极的感受有哪些？\u003cbr> （学习者回答：开心、兴奋）\u003cbr> 直接给予评价的表扬带来的其他的感受有哪些？\u003cbr> （学习者回答：怀疑、夸张、应付、恭维、否认。。。）\u003cbr> 积极性反馈的表扬带来的感受又有哪些？\u003cbr> （学习者回答：感动、使命感、动力、意愿。。。）\u003cbr> 积极性反馈的表扬带来感动的3个主要原因是？\u003cbr> （学习者回答：细节的关注、认可和感激）\u003cbr> \u003cbr> 我们有幸生活在一个全民表扬的时代，经常会有人对你说“你真好”、“你真负责”、“你真棒”。。。但这样的直接给予评价的表扬听多了，也就麻木了，最多一时的兴奋与开心，过后你会觉得这样的表扬没有内涵，有可能只是应付或恭维，听听而已，你不会放在心上。同样，别人也不会。\u003cbr>而积极性反馈因为有具体行为和影响做铺垫，以反馈的方式，被表扬的人感受到表扬人的关注和认可，激发了内在的动力和意愿度，同时因为知道被表扬的具体行为，被表扬人更加相信表扬人的诚意，也更愿意去做被表扬的事。\u003cbr> 那如何做积极性反馈呢？ \u003cbr> 第一步：描述具体的行为。 \u003cbr> 我们以拆页中的表扬信为例，具体行为包括：提前40分钟来到培训室、课间休息时没有休息而是将每组问题归类和分析等；\u003cbr> 第二步：阐述影响或评价。影响指的是被表扬人的行为对表扬人产生的影响，评价指的是表扬人针对被表扬人的行为给予的评价；\u003cbr> 同样，我们以拆页中的表扬信为例，影响指的是：80位学员收获满满的落地的管理实操工具；评价指的是：勤勉、敬业、忘我等。\u003cbr> 第三步：表示欣赏或感谢。\u003cbr> 需要特殊说明的是，这3个步骤并非一成不变，没有必要非得是123，也可以是213。尤其是对于刚学会积极性反馈的人来说，因为习惯了评价，可以按照正常的逻辑先给评价，再描述行为，后给予赞赏或感谢。比如：今天学习场地遇到了特殊情况，没有办法及时开门，胡旭在短短不到10分钟的时间找到这么好的场地，如果用213的评价方式，我们会说：“胡旭，我觉得你的公关能力特别强，你在发现学习场地打不开后，不到10分钟就找到了一个这么合适的场地，让我们这十几个人有这么好的学习环境，非常感谢你为这次拆书帮活动的付出！” \u003cbr>是不是所有的表扬都要用积极性反馈呢？并不是，一些简单的场景，如举手之劳，直接给予评价的表扬，精准快捷，被表扬人心领神会，无须复杂的行为描述和影响阐述，这种场景下应用积极性反馈，反而会让人觉得啰嗦。\u003cbr> \u003cbr> \u003cbr> \u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）： \u003cbr>关于原文片段的讲解就到这里，拆书帮的理念是拆为已用，学了一定要实践，这个知识才真正有用。接下来咱们使用今天学习的内容，做一个演练。请各位听一听我给出的场景和要求：\u003c/p>\u003cp>（场景）今天Lily加班到很晚，拖着疲累的身体打开家门，看到Lucy（可以是父母，也可以是爱人）在等着自己，桌子上摆满了美食，还都是自己爱吃的，那一刻，感受到满满的幸福。\u003cbr>（要求）请大家两人一组，分角色进行演练。一人扮演Lily，一人扮演Lucy。请扮演的Lily的小伙伴运用今天所学的积极性反馈，给予Lucy以反馈及表扬。5分钟后邀请一组小伙伴分享你们的对话，同时其他小伙伴请评判他们是否恰当使用积极性反馈三步骤。\u003cbr> 好的，时间到了，有小伙伴自愿分享的吗？\u003c/p>\u003cp>（表格2）\u003c/p>\u003cp> 学习者案例记录：\u003cbr> Lily扮演者胡旭，Lucy扮演者屈冠华，背景知识Lucy是Lily的父亲。\u003cbr> Lily推门回答家\u003cbr> Lily：哇！爸，今天这么多好吃的！（惊喜）\u003cbr> Lucy：看你最近加班辛苦，给你补补（慈爱的表情）\u003cbr> Lily：我看到一桌子是都是我喜欢吃的菜，这么多（满满的满足感），你今天一定是在家里忙活了好久才准备了这么多，爸爸，你为家里付出这么多，给我这么多的温暖（感动），我觉得心里特别暖特别感动，非常感谢你， 爸爸！\u003cbr> Lucy：（抱一个）\u003cbr>拆书家回应/反馈：\u003cbr>我们看到两位的表演中，有说到具体的行为，满桌子自己爱吃的菜，也阐述了影响和评价，感受到了爸爸对自己的爱护和关心，感受到爸爸对家庭的付出，同时表达了感谢，谢谢爸爸对自己的爱，整个过程中有行为、有评价、有感谢，非常棒。\u003cbr> \u003c/p>\u003cp>拆书家提问设计（逐字稿）： \u003cbr>今天我们一起学习的是一个很实用的技能，我们都知道孰能生巧，所以给大家布置一个小任务：在稍后苹果洋葱环节，请大家给予我一个积极性反馈的苹果，让我做第一个接受大家积极性反馈的幸运儿。\u003cbr>（收集学习者的特定任务）\u003c/p>\u003cp>（手写版）\u003c/p>\u003cp>（口语版）\u003cbr>王楠：看到肖利老师准备了这么多的小表格（表格1和表格2），而且每一个表格间都有联系，感受到了肖利老师对于活动和学习者的重视，谢谢肖利老师。\u003c/p>\u003cp>赵秀梅：第一次来参加拆书帮活动，听肖利老师的分享，看到肖利老师准备了很多的资料（表格1和表格2），感受肖利老师准备的特别充分，感谢肖利老师带来的精彩分享。\u003cbr>\u003c/p>\u003cp>美国历史上第一个年薪过百万美元的管理者叫查尔斯。史考伯，曾经在一次记者发布会上说：“我对业务懂的并不多，我最大的本事是鼓舞员工士气，而鼓舞员工最好的方法是赞赏和鼓励”。希望通过今天的分享与学习，大家都可以用积极性反馈3步法，让自己成为最会鼓舞和表扬他人的人，成人达已，未来可期。\u003cbr> \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1611832037000,"updated_at":1612416324000,"ria":true},{"id":10629,"topic":"未来导向型提问五步法","learn_goal":"","remark":"提升管理者教练能力的实操手册","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"忆C","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>【自我介绍】大家好，我是本次参加拆书家晋级的杜晓娟。用三个标签来介绍自己：阅读、重塑、未来有价值的培训师，代表我的过去现在和未来。今天拆解的书是《 教练型管理者》\u003c/p>\u003cp>【图书介绍】这本书是俞清、金慧英两位实战派老师合著完成。这本书豆瓣评分8.8分，书中介绍了如何成为教练型管理者的具体方法。\u003c/p>\u003cp>有一种管理者叫“万事帮”。下属什么事找到他，二话不说的告诉下属该怎么做或者帮着下属做，但对于企业来说，并不是一件好事。这本书帮助管理者们了解一名优秀的管理者首先应该是一名好教练，书中对教练原则、教练技能、掌握教练流程非常的落地。相比较于其他同类书籍，它介绍的技术、方法和工具都来自真实的企业管理实践，是经过检验的并且正在被先进企业系统运用的管理实践。只要你做到，你就会看到效果。\u003c/p>\u003cp>今天的分享首先，我们要一起了解拆页片段，第二，对内容进行提炼重述，第三，结合自身进行计划运用。\u003c/p>\u003cp>【分组】开始前我们先进行简单的分组，方便交流讨论。（分组完毕）谢谢大家配合\u003c/p>","ratings_count":2,"texts":[{"id":14491,"quote":"\u003cp>接下来进入第一部分内容： \u003c/p>\u003cp>大家请看桌面上的材料，是来自《教练型管理者》第158页，第四章有力提问的片段，请大家用1-2分钟时间阅读，读完后可以举手示意我。\u003c/p>\u003cp>【原文片段】在一次的教练论坛上，一位毕业不到5年但已经掌管5家法人公司的管理者分享了她的成长心得。这位管理者说，她在职场中能够比一般人快速成长，得益于它在工作中遇到困难和挑战时，不断向自己提出未来导向型问题。与总是抱怨、逃离、拒绝的管理者不同，她会把思绪抛向未来问自己。\u003c/p>\u003cp>▍辛苦背后，我到底想成就什么呢？\u003c/p>\u003cp>▍为什么这个成就对我那么重要？\u003c/p>\u003cp>▍如果实现了想要的成就，那么我的人生会有什么样的不同？\u003c/p>\u003cp>▍如果解决了这个困难，那么我有会有什么样的成长？\u003c/p>\u003cp>▍那么，接下来我又该如何正确的面对当前的困难？\u003c/p>\u003cp>未来导向型提问可以让人跳出当下，站在更远的将来，看到更多的希望。当我们看到希望时，我们就再也没有时间抱怨、不满和找借口，取而代之的是充满能量，努力探索并积极行动。\u003c/p>","explains":"\u003cp>好，我看大部分小伙伴都已经读完了。\u003c/p>\u003cp>【what】这个拆页中提到：未来导向型提问。什么是未来导向型提问呢？含有“未来导向”词汇，比如说：梦想、目标、方向等等，它关注未来付出的行动和可行性，帮助我们获得希望的提问。\u003c/p>\u003cp>【why】当一个人面临前行的压力、阻碍时，容易走入批判、否定中，或者判断对错、责任归属等过去的事和负面体验，这是一种判断型心态，这种心态让我们产生一种无力感。所以，用未来导向型提问帮助我们聚焦于未来和下一步行动，转向乐观、正面积极心态。\u003c/p>\u003cp>【How】通过拆页内容，用自己的理解重述知识，总结了五个步骤：\u003c/p>\u003cp>1.问目标：你要想达成什么/改变什么？\u003c/p>\u003cp>2.问原因：我为什么要达成？为什么要改变？ \u003c/p>\u003cp>3.问长期影响。当我实现规划的目标后和现在有什么区别？长期影响是什么？。\u003c/p>\u003cp>4.问短期成长。设想一下，当我解决眼前的阻碍后会获得哪些成长收获。\u003c/p>\u003cp>5.问具体行动。有什么方法去解决阻碍？下一步做什么？\u003c/p>\u003cp>那我自己的例子来具体说明一下。比如，我现在除了正常工作，每天还要坚持看30分钟书、做笔记、输出文章，带孩子，时间严重不够用的同时还在准备拆书晋级，感觉自己在为难自己。通过自己我引导问自己的动机是什么？（我想积累知识、成为拆书家）。为什么要成为拆书家？成为拆书家能提升知识储备，同时锻炼讲授技能，成为更有影响力的人，保持竞争力。成为拆书家对自己有什么长期影响？和现在有什么不同？（我会更自信、更有影响力、有更多的选择机会）。如果克服了阻碍，短期成长有哪些？（自信、时间管理能力、成就感等等）具体该怎么做呢？（早上6点起床，看书写笔记，定好6点的闹钟，按时起床。）\u003c/p>\u003cp>【where】大家看看，未来导向型提问的前三步关注的是远期的，后两步又把我们拉回来，聚焦行动。五个步骤合起来，帮助我们引导自己也好，引导朋友也好，解决大家工作和生活中过不去的阻碍和困难，让生活更有希望。制定行动步骤要注意：一口吃不了大胖子，行动计划要可行。\u003c/p>","interaction":"\u003cp>【A1便签】接下来我们进入第三部分内容。请大家用2分钟的时间回想一下过去的相关经历并写下来，要注意几点：\u003c/p>\u003cp>1.重点关注：经历要和知识点相关，时间、地点、人物、过程尽量完整精炼概括。\u003c/p>\u003cp>2.当时你是怎么想，怎么做的？结果是什么？\u003c/p>\u003cp>3.你认为自己的这段经历是关注过去判断型思考，还是未来导向型思考。有什么感想？\u003c/p>\u003cp>（巡场动作，询问有无疑问）\u003c/p>\u003cp>我看大部分小伙伴已经写完了，接下来请大家用1分钟时间，两两一组，向临近的小组成员彼此分享自己的经历。（巡场动作，观察有无疑问需要解决）\u003c/p>\u003cp>时间到，下面我想邀请一位小伙伴上台用1-2分钟时间分享他的经历，有自愿或者推荐的吗？\u003c/p>\u003cp>【苏小妹的经历分享】去年年底练毛笔字，于是找朋友介绍了一位毛笔字老师开始学习，认为自己一年后应该会有很大的进步。老师要求周六早上8点半开始上课，但是自己因为周一到周五上班早起，周六必须让自己放松，好好睡个懒觉，周日再用来加班。因为时间原因，总认为练毛笔字和自己的生活冲突，没多久就放弃了。回想一下，我自己当初没有想清楚自己练毛笔字的目的是什么？练好了会给我带来什么？我只关注于眼前，没有关注未来。如果我能从关注未来再回到眼前，也许就能明确目的，找到方法。\u003c/p>\u003cp>好，非常感谢这位小伙伴的配合，掌声送给他！\u003c/p>\u003cp>【A2便签】通过刚才的分享，我们用一句话来总结：思考的方向决定行动的方向，不同的行动方向导致不同的结果。那么接下来我们进入动手运用环节了，请大家用2分钟的时间将今天学到的方法进行应用计划，注意事项：\u003c/p>\u003cp>1.解决未来的工作、生活中的场景，要与知识点相关的问题。\u003c/p>\u003cp>2.行动步骤要具体。比如：具体的目标是什么？具体行动是什么？行动对象是谁？什么时候开始？频率多少？\u003c/p>\u003cp>3.可行性。比如目标可做到吗？可以用数据量化吗？\u003c/p>\u003cp>请开始……（写A2便签）\u003c/p>\u003cp>（巡场动作，观察有无疑问需要解决）\u003c/p>\u003cp>【苏小妹案例分享】通过今天的学习，我打算用未来导向型提问来引导我学车这件事。我计划在接下来的1个月的学车过程中，当遇到自己缺少动力动力，又不想去的时候，用5个步骤来清晰自己的目标，引导行动。\u003c/p>\u003cp>当我心里又出现懒惰，又不想去的时候\u003c/p>\u003cp>首先我引导自己想象自己的目标，最终要实现什么（我想学会开车）\u003c/p>\u003cp>接着引导自己想象为什么要许可会开车（因为想出行更方便一些）\u003c/p>\u003cp>引导自己想想改变带来的长期影响（如果我会开车了和现在会有很大区别，我不用站在路边等车来接我，出行的时候也不用蹭着朋友的车，跟着他们去他们的目的地。如果我学会了开车，方向盘掌握在我的手里，我可以决定想去哪里就去哪里。）\u003c/p>\u003cp>引导自己想想短期成长。（如果，我解决了自己的动力不足，自己将变得更有行动力，更快学会开车）\u003c/p>\u003cp>那么，接下来的具体行动是什么呢（给自己贴一张便签在醒目的地方，写上”3个月必须拿到驾照“，提醒自己）\u003c/p>\u003cp>好了，我看到许多小伙伴都写了自己的应用计划。因为时间的关系，不再一一分享。回顾一下今天，我们了解了未来导向型提问的5个步骤，并结合自身分享过去的经历，写下了自己未来的应用行动。今天的内容分享完毕，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1605495490000,"updated_at":1606914150000,"ria":true},{"id":10561,"topic":"积极的反馈技术","learn_goal":"","remark":"拆书家TF1-1","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"张锡梅","city":"昆明市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>大家好，我姓张，名锡梅，张是弓长张，锡是五金之末，金银铜铁锡的锡，梅是梅花的梅。希望我的名字在您脑海中闪现出一枚精工雕刻的锡制梅花胸针，它具有着锡容易延展塑型又不易锈蚀永葆本色的特性，也代表了梅花不畏严寒迎冬怒放的坚毅品质，我把它戴在我的胸口，陪我乘风破浪。希望在拆书学习的路上共同成长。\u003c/p>\u003cp>在开始内容之前先介绍下什么是“拆书帮”。\u003c/p>\u003cp>首先，什么是拆书？\u003c/p>\u003cp>拆书是一种成人用来提升能力、解决问题的学习方法，他强调以学习者为中心，而不是以知识为中心，把知识关联学习者的经验并指导运用。拆书分为个人学习的拆书和组织学习的拆书，个人学习的应用RIA便签法，个人通过复述原文结合激活过往经验和指导下一步行动，通过读一本书就能达到参加同主题培训的效果。组织学习拆书是拆书家将书中片段加工出一场现场学习，引导和促进他人把知识拆为己用。\u003c/p>\u003cp>那么，什么是拆书帮呢？\u003c/p>\u003cp>拆书帮就是基于拆书法的学习爱好者的社群，是公益性的青年自组织，它的使命是帮助更多学习爱好者成为拆书家，在全国的很多个城市都有拆书帮的分舵，也称拆书俱乐部。拆书帮分舵是公益性的青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":2,"texts":[{"id":14416,"quote":"\u003cp>片段主题：积极的反馈技术\u003c/p>\u003cp>片段来源：《教练型管理者》 \u003c/p>\u003cp> 原文片段：\u003c/p>\u003cp>教练型管理的积极性反馈技术——AAA总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。\u003c/p>\u003cp> 积极性反馈的注意要点如下：首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地评判。其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给与评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。最后，表示由衷的欣赏和感谢。\u003c/p>","explains":"\u003cp>AAA反馈技术是一种教练型的积极性反馈技术，是以“描述行为和事实（Act）、阐述影响及评价（Actor）、表示欣赏和感谢（Appreciation）”三要素构成的一种对行为和事实进行积极反馈的技术。\u003c/p>\u003cp>运用AAA反馈技术可以扩大行为和事实的影响，使被反馈人感受到行为产生的积极效果和作用，感到自己被人欣赏、被人感激，获得更多的心理满足和正向鼓励，从而愿意自觉强化和再次从事此种行为、造成此种事实。运用AAA反馈技术的过程也是为被反馈者赋能的过程，能更有效地激发反馈者的潜能。\u003c/p>\u003cp>AAA反馈技术包括3个要素，缺一不可：\u003c/p>\u003cp>Act——观察被反馈人的行为，对行为进行具体而客观的描述，行为所指要有明确针对性，而不是用概略模糊的语言。例如，观察到孩子今天在公交车上有主动给老爷爷让座的行为，反馈时应该明确表述为“你今天在公交车上主动给老爷爷让座的行为”，而不能提出概括为“你今天很有礼貌”，否则，需要被强化行为不能被准确定位。\u003c/p>\u003cp>Actor——阐述行为造成的影响及评价，并将影响扩大化，让被反馈人获得更多的成就感。这里的影响和评价不仅是来自于个人，还要来自于团队和整体。例如上一个例子，可以说“我觉得你是一个懂礼貌、懂谦让的好孩子”，同时，再加上来自于团队和整体的评价“车上的叔叔阿姨们也都用赞赏的目光看着你”，可以进一步强化评判的效果。\u003c/p>\u003cp>Appreciation——由衷地表示欣赏和感激，进行感情的反馈。例如“妈妈很欣赏你的礼貌和谦让”或者“谢谢你让妈妈为你骄傲”。\u003c/p>\u003cp>AAA反馈技术可以用在生活、学习和工作中，用于对正向、积极行为进行激励和强化，但不适用于对负面、消极行为进行批评和否定。\u003c/p>","interaction":"\u003cp>接下来给大家讲一个我的经历。\u003c/p>\u003cp>公司这个月新来了一个很内向的实习生，看到她最近很积极地想融入大家，主动跟大家互动，我表扬她“我发现你最近跟大家相处更融洽了，看得出你在努力融入大家，加油哦！”\u003c/p>\u003cp>结果她听完就跟我笑笑，也没说话。我事后也觉得好象有点敷衍。\u003c/p>\u003cp>对应AAA法，我做到了观察对方的行为，并给出了评价，有一定的反馈作用，却没能表达造成的影响和进行感情的反馈。\u003c/p>\u003cp>如果事前做更多的规划，罗列出流程，对新加入伙伴着重从提升下属学习能力的四个方面进行促进，会更有节奏，也会让对方在自我提升上有更大的帮助。\u003c/p>\u003cp>运用AAA法我可以这么做：\u003c/p>\u003cp>Act：我注意到你昨天午饭时间主动约同事午饭，推荐你去过的餐厅，还主动带路。\u003c/p>\u003cp>Actor：这是非常积极的态度哦。大家也说你其实很热心、很随和，愿意跟你做朋友。\u003c/p>\u003cp>Appreciation：你做得非常棒！相信不久后就能融入大家了，加油哦！\u003c/p>\u003cp>在未来，我将会用SMART原则规划自己对AAA反馈技术的运用。\u003c/p>\u003cp>今天我发现女儿用周末的时间自己把书柜整理得整整齐齐，比起以前乱乱的书柜，有很大进步。等明天早上她醒过来，我就要用AAA反馈技术给她一个积极反馈。\u003c/p>\u003cp>如果她收到反馈后产生了积极效果，下周继续自己整理书柜，我就奖励自己一块巧克力，如果做不到罚自己一周不能喝咖啡。\u003c/p>\u003cp>Act：我发现，你周末的时候自己把书柜擦得干干净净，书本分类很准确，摆放得也非常整齐。\u003c/p>\u003cp>Actor：这样干净整洁的感觉我很喜欢。爸爸和外婆也夸你整理得真好，都说书柜变成了我们家美美的一角。\u003c/p>\u003cp>Appreciation：这个表现非常棒哦，谢谢你，亲爱的宝贝！\u003c/p>\u003cp>今天我为大家分享了AAA正向积极反馈技术，希望大家在日常的工作和生活中积极运用，相信大家也会收到非常好的效果。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1603287023000,"updated_at":1605356641000,"ria":true},{"id":10474,"topic":"积极反馈的技术 ","learn_goal":"","remark":"AAA技术无论在工作中还是家庭里，但凡跟人沟通都可以用的上，其操作方法简洁方便，运用者可以是管理层，也可以是普通小白，还可以是各种身份人士 ","level":"TF1-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"邹治","city":"广州市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>TF1-1拆书预备表-邹治-广州小蛮腰分舵-20200918\u003c/p>\u003cp>大家好，我是邹治，感谢大家参加今天的拆书学习。那么在开始之前，请允许我先用三个标签介绍下自己：\u003c/p>\u003cp>第一个标签是不安份的90后青年;\u003c/p>\u003cp>第二个标签是喜欢赚钱的90后;\u003c/p>\u003cp>第三个标签是大叔.\u003c/p>\u003cp>总结一下：我是一位不安分喜欢赚钱的90后大叔。好了，大家已经认识我了，我们就开始今天的拆书学习吧。\u003c/p>\u003cp>首先我们今天的学习分为2步，第一部分我会用2分钟的时间跟大家介绍拆书帮，以便于让大家知道你参\u003c/p>\u003cp>加的是什么。\u003c/p>\u003cp>（一）关于拆书和拆书帮：\u003c/p>\u003cp>提问：大家平时看书过程中会遇到哪些阻碍？（0.5分钟）\u003c/p>\u003cp>好的，谢谢大家！在之前啊，我也跟大家一样学不进去、学了不知道怎么用、害怕自己不能坚持……\u003c/p>\u003cp>但自从掌握一种学习技巧后，觉得原来读书如此简单。怎么做到的呢？——拆书！\u003c/p>\u003cp>可能大家会好奇，什么是拆书呢？（可讲可不讲，看时间）\u003c/p>\u003cp>“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知\u003c/p>\u003cp>识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法:个人学\u003c/p>\u003cp>习的应用是便签法，让人读一本书就能达到参加同主题培训的效果;组织学习的应用是一位拆书家拿一本书加工\u003c/p>\u003cp>出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价\u003c/p>\u003cp>值不亚于一位培训师。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群,表现为各地的拆书帮分舵(也叫拆书帮俱乐部)书帮分舵是非营利青年\u003c/p>\u003cp>自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>（二）拆《教练型管理者》\u003c/p>\u003cp>什么是教练呢？\u003c/p>\u003cp>“教练技术”是通过方向性和策略性的有效问题，激发被教练者向发掘自己的潜能，向外探求更多的可能性，\u003c/p>\u003cp>令被教练者更加快捷、容易的达到目标。\u003c/p>\u003cp>本书综合作者俞清在世界知名企业的教练实践和教学经验，力求用严谨的内容结构、简明的讲解风格、实用的\u003c/p>\u003cp>工具方法和生动的情境案例，让读者能够在较短的时间内成为一名优秀的教练型管理者。\u003c/p>\u003cp>更重要的是，本书介绍的技术、方法和工具都来自真实的企业管理实践，是经过检验的并且正在被先进企业系\u003c/p>\u003cp>统运用的管理实践。只要你做到，你就会看到效果。本书也同样适合有志于成为专职企业教练的读者。\u003c/p>","ratings_count":2,"texts":[{"id":14323,"quote":"\u003cp>现在请大家先用2分钟阅读一下拆页R便签的部分。\u003c/p>\u003cp>教练型管理者的积极反馈技术——AAA\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：\u003c/p>\u003cp>一是描述行为和事实（Act）；\u003c/p>\u003cp>二是阐述影响及评价（Actor）；\u003c/p>\u003cp>三是表示欣赏和感谢（Appreciation）。\u003c/p>\u003cp>这3个要素缺一不可，我们简称AAA反馈技术，如下图所示：\u003c/p>\u003cp>积极性反馈的注意要点如下：\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单地评判。\u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给与评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这就是一个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。\u003c/p>\u003cp>已经阅读完的小伙伴请举手示意一下，没有阅读完的小伙伴注意再阅读30秒……好的，我们来看看拆页的方法具体是怎么做的。\u003c/p>","explains":"\u003cp>【What】：\u003c/p>\u003cp>AAA反馈技术是一种非常有效的反馈技术，具体步骤由:\u003c/p>\u003cp>1）描述行为和事实(Act)\u003c/p>\u003cp>2）阐述影响及评价(Actor)\u003c/p>\u003cp>3）表示欣赏和感谢(Appreciation) 3个要素构成\u003c/p>\u003cp>【How】：\u003c/p>\u003cp>1）描述行为和事实(Act) ; .\u003c/p>\u003cp>通过观察法，将被观察者的行为和事实输出给观察者确认是否正确，在这个过程中注意不能添加任何自己主观意识的内容，不添加任何色彩。\u003c/p>\u003cp>2）阐述影响及评价(Actor) ; .\u003c/p>\u003cp>影响扩大化:将事件行为和事实无限放大，如果把正向积极影响越扩大化，对方就越觉得有成就感，借此可以激发对方的动力，我们也把它称之为“赋能”。当然了，这个方法不局限于个人，也可以是团队。\u003c/p>\u003cp>3）表示欣赏和感谢(Appreciation)\u003c/p>\u003cp>结尾的时候能够共情,感动身受的对对方表示发自内心的欣赏和感谢，从而再次加深信任，为对方赋能。\u003c/p>\u003cp> 【why】：\u003c/p>\u003cp>由此可见，AAA反馈技术方便简洁，步骤简单，通俗易懂，重反映事实和行为，交流中更容易被对方接受，更利于有效的沟通\u003c/p>\u003cp> 【where】适用场景\u003c/p>\u003cp>AAA技术无论在工作中，还是家庭里，但凡跟别人沟通都可以用的上，其操作方法简洁方便，运用者可以是管理层、也可以是普通小白、还可以是各种身份的人士。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>结合今天学习到的，我立马想到了2017年在山西太原做商学院负责人的时候因为A君迟到而衍生的一系列事情。\u003c/p>\u003cp>有一次我组织开会A君迟到了，面对他的迟到，我非常生气，于是就随口一句：“怎么又是你迟到啊，你怎么总是迟到！”\u003c/p>\u003cp>当我说完这句话后A君直接当场跟我顶起来了，结果闹的非常不愉快！\u003c/p>\u003cp>所以在学完AAA技术，我觉得自己当时是带着评判去的，描述行为并不中立，因为加了自己主观意识，所以才有了这样的结局呀！\u003c/p>\u003cp>A2：\u003c/p>\u003cp>背景：以往我在做培训带团队的过程中很少会去表扬我们同事，比如有的同事超额完成培训期望值我也没有去表扬认可他，那么学完AAA技术之后，我觉得以后再遇见那些同事，我可以这样做：\u003c/p>\u003cp>1）遇见超额完成期望值的同事，我会在结束后第一时间电话庆祝，具体步骤如下：\u003c/p>\u003cp>描述行为和事实：小王，因为你这次的出色表现和付出让总裁对我们培训部刮目相看，产生极大认可。\u003c/p>\u003cp>阐述影响及评价：这一次培训让我们在公司所有部门中出彩夺目，公司领导也会抽出更多的预算补贴到我们培训部，以后在培训的过程中我们更有底气了。\u003c/p>\u003cp>表示欣赏和感谢：这么短的时间内从设计到研发再到面授，我知道你背后一定付出了心酸和汗水，非常感谢你这么负责认，我也相信未来有你的持续努力，我们培训部会越来越好！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1600526689000,"updated_at":1604110590000,"ria":true},{"id":10187,"topic":"积极性反馈-AAA","learn_goal":"","remark":"这本书综合了作者在世界知名企业的教练实践和教学经验，有丰富的情境案例和实用的工具方法，能帮助学习者在较短的时间内成为一名优秀的教练型管理者。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"韩璐","city":"长治"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp> 【自我介绍】\u003c/p>\u003cp>各位小伙伴们，大家好！\u003c/p>\u003cp> 我是韩璐，我是两个孩子的妈妈，也是一名中规中矩的国企职员，大学毕业7年了，时光已经把我慢慢的打磨成了只剩下“宝妈”和“职员”这两个标签的我。生活的琐碎，工作的繁杂，让我感觉到前所未有的无力感和落差感，似乎每天都在寻找丢失了的“自我”。正所谓“山重水复疑无路，柳岸花明又一村” ，今年4月，我与拆书帮完美的邂逅，收获了我的第3个标签：行走在路上的拆书家，让我不再感慨岁月蹉跎，做回了纯粹的自我，让我在面对各种生活中的问题时，都能找到问题解决的蓝本。\u003c/p>\u003cp> 【拆书法和拆书帮介绍】\u003c/p>\u003cp>也许有人会问，拆书帮有什么魅力，让你如此着迷？接下来我给大家介绍一下拆书法和拆书帮。\u003c/p>\u003cp>拆书法是以学习者为导向，通过拆解致用类图书，把书中的知识关联学习者过往经验，并聚焦于解决实际问题的一种成人学习方法论，又叫RIA便签读书法。包括个人学习的拆书法和组织学习的拆书法两种形式。\u003c/p>\u003cp>个人学习的拆书法是学习者个人通过阅读原文片段R，阅读后用自己的话总结出大意并写出I便签，最后根据总结的内容关联自己过往的成功或失败的案例，做出反思；再设想如果在未来某个时段发生类似的事，会怎么做的过程。\u003c/p>\u003cp>组织学习的拆书法是一名拆书家引导学习者现场学习，把知识拆为己用的方法，比如：咱们今天现场的学习，就是组织学习。\u003c/p>\u003cp> 拆书法可以帮助学习者提高学习效能，真正达到学以致用的目的，而拆书家创造的价值不亚于一名培训师。\u003c/p>\u003cp> 拆书帮是基于拆书法的学习爱好者社群，是由座落在我国大江南北的各个正式分舵和筹备分舵组成的，大家现在参加的就是我们长治上党筹备分舵的活动。拆书帮一个公益性青年自组织，是由教育实践家赵周老师于2013年4月在北京创办的，它的使命是帮助更多学习爱好者成长为拆书家。 \u003c/p>","ratings_count":1,"texts":[{"id":14020,"quote":"\u003cp>【过渡】\u003c/p>\u003cp>接下来，就请大家跟我一起感受拆书的魅力吧。今天我带来的片段是“积极性反馈技术——AAA”，选自《教练型管理者》，作者：俞清，金慧英。\u003c/p>\u003cp>【拆书家指令】现在给大家1分钟的时间，请大家阅读我之前发下去的原文片段。\u003c/p>\u003cp>总结一下，有效的积极性反馈一般由3个要素构成：一是描述行为和事实（Act）；二是阐述影响及评价（Actor）；三是表示欣赏和感谢（Appreciation）。这3个要素缺一不可，我们简称为AAA反馈技术，如图5-2所示。不难看出，上述学员的反馈完全符合这3个要素。\u003c/p>\u003cp> 图5-2 AAA反馈技术\u003c/p>\u003cp> 积极性反馈的注意要点如下。\u003c/p>\u003cp>首先，一定要聚焦行为和事实，而且要具体地描述该行为，客观地描述该事实，这就需要观察而不是简单的评判。\u003c/p>\u003cp>其次，阐述这些行为和事实会带来什么样的影响，也可以针对相应影响给予评价。描述或评价的影响不仅是针对个人的，还要针对团队和整体。我们越是把这个影响扩大化，对方越觉得有成就感，这也是一个赋能的过程，这时人的潜能会被真正激发。\u003c/p>\u003cp>最后，表示由衷的欣赏和感谢。\u003c/p>\u003cp> （1分钟后）请看完的小伙伴举手示意我一下，谢谢。\u003c/p>","explains":"\u003cp>看到大家都读完了，接下来我来分享一下我对这个片段的理解。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>当孩子通过自己的努力取得好成绩时，我们给孩子最司空见惯的反馈可能就是“宝贝，你真棒！你真聪明！你好了不起啊！……”然而这种空洞的反馈却是无效的，不利于孩子的成长的。3A积极性反馈方法能帮助我们强化孩子的正确行为，增强孩子的信心和动力，激发正确行为的重复发生，增强孩子的幸福感！\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这个片段告诉我们：3A积极性反馈是一种通过描述对方的行为和事实（Act），阐述该行为带来的影响及对行为结果进行评价（Actor），最后表示欣赏和感谢（Appreciation）的一种用于强化对方的行为及其结果、给他人赋能的评价手段。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那么，如何通过3A积极性反馈来表扬别人呢？\u003c/p>\u003cp>1、描述行为和事实（Act）；\u003c/p>\u003cp>对观察到的行为或事实进行客观的描述。\u003c/p>\u003cp>例子：“宝贝，你今天吃完饭主动把自己用过的碗筷送到厨房了。”\u003c/p>\u003cp>2、阐述影响及评价（Actor）\u003c/p>\u003cp> 进一步阐述此行为对个人及他人带来的影响并对对方进行正向评价。\u003c/p>\u003cp> 例子：“你自己主动收拾碗筷，说明你是一个很有责任心和行动力的宝贝，你做家务的好习惯值得表扬，你的好习惯还影响着妹妹，她也跟着你学会了饭后收拾碗筷的好习惯，你不仅给妹妹树立了好的榜样，而且还节省了妈妈做家务的时间。”\u003c/p>\u003cp>3、表示欣赏和感谢（Appreciation）。\u003c/p>\u003cp> 对对方的行为表示出由衷的感谢。\u003c/p>\u003cp> 例子：“宝贝，谢谢你这么小就能帮妈妈做家务。”\u003c/p>\u003cp>【where】\u003c/p>\u003cp>3A积极性反馈除了适用于家长对孩子的正向评价，还适用于夫妻之间的沟通，或者同事之间对于工作任务的评价，也可用于学校教师对学生作业的评价、教师与教师之间听课后的评价等。\u003c/p>\u003cp>如果你期待强化别人的某种正向行为，想在群体之中树立榜样或标杆也可用此方法。\u003c/p>\u003cp> 3A积极性反馈不适用于对错误行为或者需要进一步整改的行为的评价。\u003c/p>","interaction":"\u003cp>【过渡】\u003c/p>\u003cp> 下面我来分享一个发生在我身上的故事：\u003c/p>\u003cp>【故事】\u003c/p>\u003cp> 2020年4月26日，我老公信心满满的参加了公司举办20进8的歌手大赛的初赛，力争要夺公司前三甲。可谁知，比赛中高手如云，老公并没有如愿。\u003c/p>\u003cp>比赛完回到家他愁眉苦脸地跟我说：“我落选了，得了第9名，比赛的时候太紧张导致忘词了，哎，不过我已经跟评委申请了看能不能破格让我进入复赛。”\u003c/p>\u003cp>他本来期待着我能安慰他几句，激励他的勇于参赛的行为，可我听后说：“你得了多少分？你跟评委沟通了吗？哪方面表现不好扣分了呢？”\u003c/p>\u003cp>老公说：“评委觉得我选的歌不太符合比赛的主题，着装比较随意，还有我忘词了。”\u003c/p>\u003cp>我很不屑的跟他说：“你看看，我当初跟你说换首歌，你不听，早上给你准备了正装，你不穿，得了倒数还好意思再参加？”\u003c/p>\u003cp>我老公当时本来心情就很低落，我这么一说，他直接黑脸了。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp> 当时没有用3A积极性反馈对他进行评价，没有对老公比赛的行为进行客观的描述，而是带有责怪的问他差在哪里。没有对老公的主动跟评委沟通要求进入复赛的行为对他及他们部门的影响进行评价，而只是对他进行冷嘲热讽。没有对老公参加比赛的勇气表示欣赏，对他为家庭的付出表示感谢。最后导致老公很不高兴。\u003c/p>\u003cp> 最后我来分享一下我的具体应用：\u003c/p>\u003cp>【目标】\u003c/p>\u003cp>2020年7月在本次拆书活动结束后运用3A积极性反馈对朋友山佳的无私帮助进行表扬。\u003c/p>\u003cp>【具体行动计划】\u003c/p>\u003cp>1、描述行为和事实（Act）；\u003c/p>\u003cp>山佳姐，今年4月疫情原因，每天出不了门，让我感觉自己整个人的状态都不太好了，跟你在微信上聊天，你总是能及时回复我，并给我出谋划策，还邀请我一起加入拆书帮，一起通过读书陪伴赋能。上个月各种繁忙，导致自己的拆书过级进程搁浅下来，但你总是能在第一时间提醒我：“该开始拆书了。”\u003c/p>\u003cp>2、阐述影响及评价（Actor）；\u003c/p>\u003cp>你的行为激励我快马加鞭的赶上了小伙伴们的步伐，开启了自己的升级打怪之路，让我感觉到了我们分舵的温暖和正能量。\u003c/p>\u003cp>3、表示欣赏和感谢（Appreciation）。\u003c/p>\u003cp>“今天借此机会感谢你对我的无私帮助，我特别欣赏你身上这种无私的、助人为乐的人格魅力。\u003c/p>\u003cp> 【总结】\u003c/p>\u003cp> 刚刚给大家分享了如何运用3A积极性反馈来赞扬对方的技巧，希望对大家有用！\u003c/p>\u003cp> 我的分享到此结束，谢谢大家的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1595914452000,"updated_at":1596293209000,"ria":true},{"id":10171,"topic":"建设性反馈技术-AID","learn_goal":"","remark":"一级拆书家、人力资源从业者、职场宝妈","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"肖利","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>大家好，我是今天的拆书家肖利，首先用三个标签介绍我自己：第一，在拆书帮，我是一级拆书家；第二，在工作中，我是企业HR；第三，在生活中，我是1岁宝宝的妈妈。\u003cbr>\u003cstrong>【学习目标】\u003c/strong>大家在跟随我完成本次RIA现场学习后，就能够在遇到下属的工作方式或工作行为让你不满意时，运用建设性反馈技术，让下属正视自己的工作问题，并且知道改正的正确方向。\u003c/p>\u003cp>\u003cstrong>【现场分组】\u003c/strong>在分享之前，我们进行现场分组，从我右手边开始数2人一组，谢谢大家！\u003c/p>\u003cp>\u003cstrong>【F特征】\u003c/strong>今天我带拆的片段来自《教练型管理者》，本书综合作者在世界知名企业的教练实践和教学经验，介绍的技术、方法和工具都来自真实的企业管理实践，为企业管理者提供了一套完整、全面的教练工具和流程。\u003cbr>\u003cstrong>【A优势】\u003c/strong>教练技术经典书籍《高绩效教练》、《引导型教练》等均偏重于从理念层面阐述教练行业的发展，难以落地或接近国内管理情景。本书选取了作者在教练对话中的很多片段，更加符合中国国情和中国企业的生存背景。\u003cbr>\u003cstrong>【B1利益】\u003c/strong>谷歌的氧气计划提炼出了10项优秀管理者行为标准，排在第一位的就是成为一名好教练。本书能够让读者能在最短的时间内，成为一名合格的教练型管理者。\u003cbr>\u003cstrong>【B2利益】\u003c/strong>管理者指出下属工作的不足时，有时下属觉得不是他的问题，是你在给他穿小鞋；有时他改了，但根本不是你想要的结果。今天这个片段可以帮助解决这个问题。\u003c/p>","ratings_count":1,"texts":[{"id":14004,"quote":"\u003cp> 请大家用2分钟的时间阅读原文片段，阅读完成后的小伙伴请举手示意我。\u003cbr> \u003cstrong>【片段来源】\u003c/strong>《教练型管理者》P99-101\u003cbr> \u003cstrong>【主题】\u003c/strong>建设性反馈技术-AID\u003cbr> \u003cstrong>【原文】\u003c/strong>\u003cbr> 通过积极性反馈的学习，我们可能感受到表扬人不容易。其实批评人更不容易。因为表扬至少不用担心对方会生气，批评弄不好会和人起争执，所以我们在批评人的时候总会有些担心，担心对方会难以接受。有句话我们都知道：“批评要做到对事不对人。”关键是怎样才能做到“对事不对人”，这个度很难把握。比如，管理者随口所说的一句“一点儿想法都没有”，这是针对人的，是一种人格化批评，直接伤害了对方的自尊和自信，必然会造成对方的工作绩效下滑。管理者的一句“这样的提告毫无价值”，虽然不是直接针对人本身的批评，但还是会让人特别沮丧。\u003cbr> 为此，还有一种称为“三明治”或“汉堡包”式的批评方法，就是先表扬一下对方（最上面一层），接着把“难听”的话说出来（中的一层），最后赶紧安抚一下情绪（最下面一层)。但如果一直使用这种模式，那么对方以后就不会听前后的内容了，因为他知道你真正想说的就是中间的内容。\u003cbr> 还有很多管理者担心自己会“得罪人”，在工作中忍气吞声地做“老好人”，不断地扮演“救火队长”的角色，不仅把自己累得半死，还拿不到应有的工作绩效。著名企业教练约翰·惠特默曾说过：“没有正确的信息反馈，改正就不可能恰到好处。”建设性反馈是非常重要的，可以让员工正视自己的工作问题，改善错误的工作方式，以及提升工作效率。\u003cbr> 有效的建设性反馈由3个要素构成：一是描述行为和事实(Act)；二是阐述影响及后果（lmpact）；三是指明期待的行为和结果（Desired outcome）。这三个要素缺一不可，我们简称为AID反馈技术。\u003c/p>","explains":"\u003cp> 在工作中，作为管理者不可避免的需要指出下属工作的不足。当下属的工作方式或工作行为你不满意时，你会如何指出？是随口一句“你这报告毫无价值”，伤害下属的自尊心和自信心，导致下属业绩下滑，影响团队氛围；还是苦口婆心的“三明治”批评法，“你一定是加班加点才做到提前完成报告的吧，真是辛苦了，但是这报告干货不太够，不过没关系，第一稿做成这样已经很不错了”，迟钝点的下属也许觉得你是在表扬他，懂套路的下属下意识的跳过前后的内容，直接听但是了。\u003cbr> 那应该如何指出呀？我们都知道批评要对事不对人，可怎样才能做到对事不对人呢？建设性反馈技术就提供了这样一种对事不对人的批评方法。\u003cbr> 第一步：描述行为和事实。描述具体行为及行为产生的结果，而不是对人的行为做出评判。比如说“遇到问题首先来问领导怎么办而不是自己先思考”的行为描述，而不是“没有思考能力”的评判。而对行为的评判，会让下属觉得你是在针对他个人，产生抵触心理。\u003cbr> 原文中的第二步是说明影响和后果。在这里我们把这一步细化为两个步骤。第一：说明行为和事实对集体或团队的影响及后果。这是你对下属工作行为和方式不满意的主要原因，通过说明对集体或团队的影响及后果，让下属明白他造成的后果。第二：说明行为和事实对他个人的影响及后果。只有下属认识到行为和事实对他个人产生不利影响的时候，跟他自己的利益相关时，他才更有触动，更加重视，更愿意改正。\u003cbr> 第三步：正向指明期待的行为和结果。批评是为了下属改正，提高下属业绩，最终管理好团队。如果我们只告诉下属希望他不做什么，那么下属会不清楚我们到底需要他做什么。\u003cbr> 试想这样一个场景，你的一个下属上班期间跟同事聊八卦，你告诉他不希望他上班期间聊八卦，那他下一步会怎么做呢？有没有可能他开始在上班期间跟同事聊新闻、聊人生了。正向表达就可以避免这样的误解，因为你明确告诉他希望他上班期间专心工作。\u003cbr> 举一个简单的例子，我的一个下属小周经常迟到，我该如何指出他的问题呢？\u003cbr> 第一步：描述行为和事实。\u003cbr> 小周，这周你一共迟到了4次，而且还有两次是上午10点才到公司的，整整比公司的规定晚了1个小时。今天早上，你旁边的小金还替你接过5次电话。\u003cbr> 第二步：阐述行为和事实对集体或团队的影响及后果。\u003cbr> 这样不仅影响了小金的正常工作，让其他部门觉得我们部门没有规矩，更会让上级领导怀疑我们部门的工作饱和度。\u003cbr> 第三步：阐述行为和事实对下属个人的影响及后果。\u003cbr> 迟到时同事帮你接电话也会给你的客户留下了你不专业的印象，严重影响了你的工作进度和客户满意度，最主要也会影响你的实际收益，不是。\u003cbr> 第四步：正向指明期待的行为和结果。\u003cbr> 希望你从明天开始能提前10分钟来公司。\u003cbr> 有学员回问，我不是管理者，这个技巧对我有用吗？答案是肯定的。\u003cbr> 建设性反馈不仅可以运用在工作中，也可以应用在生活里。在生活中，我们想正式的跟重要的他人沟通某个问题，希望对方认识到自己的行为对我们造成影响，希望对方改正或改进时，就可以运用建设性反馈技巧。比如你的另一半喜欢应酬，晚上总是回家很晚，家庭的琐事和孩子的教育都是你一个人负责，你希望通过沟通让他改正，但又担心这样的沟通会变成争吵，就可以应用建设性反馈的技巧，让另一半正视自己的问题，明白行为的影响，同时清楚改正的方向。建设性反馈技巧，通过描述行为和事实避免沟通变成质问，通过说明影响和后果强化改正意愿，通过指明期待的行为和结果避免对方走向另一个我们不期待的结果。当然与所有沟通一样，建设性反馈技巧的前提也是平等的沟通氛围、客观的沟通表达。\u003c/p>","interaction":"\u003cp> 拆书家提问设计（逐字稿）： \u003cbr> 我们刚刚分享了运用建设性反馈技巧批评下属的方法。那么，接下来我们一起做一个演练。请大家认真听一下演练的场景。\u003cbr>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>\u003cstrong>场景描述：\u003c/strong>\u003cbr> 王经理交代给下属小刘上周六前做一份针对学龄前儿童的六一儿童节的活动方案，本周五小刘才提交方案。可王经理打开方案一看，小刘做的六一儿童节方案和上一期针对老年人做的端午节方案除了时间、参与人员外其他的一模一样。下周一六一儿童节的方案就要提报至上级领导审批，可小刘提报的这个方案明显不符合要求，老年人和儿童对活动的要求完全不同。如果把小刘这个方案提报上去，上级领导一定会觉得部门工作很差劲，对工作应付了事，会严重影响部门绩效。如果现在更改方案，部门里相关同事这周末都要加班，领导和同事对小刘一定很有意见，这个月的绩效估计要垫底了。\u003cbr> 现在请大家两人一组，分角色进行演练。一人扮演王经理，一人扮演小刘。请扮演的王经理的小伙伴运用今天所学的建设性反馈技巧，指出小刘工作的问题，让小刘认识到自己造成到影响，并知道改正的方向。\u003cbr> 演练时间4分钟，4分钟后我们选出1-2组进行分享，看大家是如何使用这个方法的。\u003cbr> \u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003cbr> 宇星（小刘）：王经理，你好。这是我做的六一儿童节的方案\u003cbr> 胡旭（王经理）：好的。小刘，这是我上周交给你的任务，这都本周五了，你才交给我。刚我大概看了看方案的内容，和我们上次做老人节的方案内容差不多\u003cstrong>（描述行为和事实）。\u003c/strong>这么长时间才交过来，是有什么问题吗？\u003cbr> 宇星（小刘）：刚好这段时间家里有事太忙了，没有很好的了解这个方案的前因后果。我咨询前辈时，前辈们也没有给我指点，而是直接丢给我了。\u003cbr> 胡旭（王经理）：你的意思是时间紧，又没相关的工作经验，所以着急按之前的方案修改完成的？但这个工作还是拖延了一周的时间，下周一要提交方案，如果让领导看到这个方案，一定会不满，对我们团队会有不好的印象（\u003cstrong>对集体或团队的影响及后果\u003c/strong>）。如果我们重新更改，时间会很仓促，对整个团队来说，需要重新理清思路，大家会对你很有意见\u003cstrong>（对个人的影响及后果）\u003c/strong>。基于你对这个工作并不是很熟悉，接下来我希望你对这个工作一定要去深入思考和理解，并且多多咨询部门老同事，把这个任务进行划分，让部门同事帮你一起尽快完成，在周日时提交上来（\u003cstrong>正向指明期待的行为和结果\u003c/strong>）。\u003cbr> 宇星（小刘）：领导可以帮忙指派几个比较有经验的老同事帮帮我吗？我一个人可能干不完\u003cbr> 胡旭（王经理）：你去找小王、小张，好吧？\u003cbr> 宇星（小刘）：好的\u003cbr> \u003cbr>\u003cstrong> 拆书家总结：\u003c/strong>\u003cbr>感谢两位的分享，两位在描述行为和事实后，基于场景描述中不太清晰的地方，增加了一步原因询问，原因清晰是为了后面第三步更好的指明期待的行为和结果，中间阐述了行为对集体对个人的影响，也提到了期待周日之前看到结果。用这种方式反馈的效果会比直接用批评方法要好的多。\u003cbr> \u003cbr> 相信大家通过刚才的演练和表演，已经学会了建设性反馈技巧。希望大家在以后的生活工作中，当遇到下属工作行为或方式让你不满意时，能够运用今天学到的建设性反馈技巧，让下属认识到自己工作的问题，并清楚改正的方向。我的分享到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1595666271000,"updated_at":1596163127000,"ria":true}]};